function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // ---- Sky gradient ----
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 120, pow(t, 1.6));
    let g = lerp(22, 96, pow(t, 1.7));
    let b = lerp(38, 92, pow(t, 1.4));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // ---- Pale moon / light ----
  let mx = width * 0.5;
  let my = height * 0.30;
  noStroke();
  for (let r = 420; r > 0; r -= 4) {
    let a = map(r, 0, 420, 90, 0);
    fill(230, 225, 200, a * 0.5);
    ellipse(mx, my, r * 2.2);
  }
  fill(238, 233, 212);
  ellipse(mx, my, 300);
  fill(225, 220, 198);
  ellipse(mx, my, 300);

  // ---- Ground ----
  noStroke();
  fill(14, 16, 24);
  rect(0, height * 0.82, width, height * 0.18);
  // soft ground glow
  for (let i = 0; i < 300; i++) {
    let gx = random(width);
    let gy = random(height * 0.82, height);
    fill(120, 120, 110, random(6, 20));
    ellipse(gx, gy, random(2, 7));
  }

  // ---- Bare tree ----
  stroke(10, 10, 14);
  strokeWeight(1);
  fill(10, 10, 14);
  let baseX = width * 0.30;
  let baseY = height * 0.84;
  branch(baseX, baseY, -90, 300, 42);

  // ---- Falling leaves transforming into rising birds ----
  // Leaves near the tree, drifting down-right
  for (let i = 0; i < 60; i++) {
    let lx = baseX + random(-80, 260) + i * 2;
    let ly = baseY - random(100, 460) + random(-40, 40);
    push();
    translate(lx, ly);
    rotate(random(TWO_PI));
    fill(150, 90, 50, random(120, 200));
    noStroke();
    ellipse(0, 0, random(10, 20), random(5, 9));
    pop();
  }

  // Transition stream: leaves lifting and becoming birds toward light
  let n = 90;
  for (let i = 0; i < n; i++) {
    let t = i / n;
    // path arcing from tree up toward the moon
    let px = lerp(baseX + 120, mx + random(-120, 120), t) + sin(t * 10) * 40;
    let py = lerp(baseY - 300, my + random(-60, 60), pow(t, 1.3)) + random(-15, 15);
    let s = lerp(16, 9, t);

    if (t < 0.4) {
      // still a leaf
      push();
      translate(px, py);
      rotate(random(TWO_PI));
      let c = lerp(0.3, 1, random());
      fill(160 * c + 40, 90 * c + 30, 50, 200);
      noStroke();
      ellipse(0, 0, s, s * 0.5);
      pop();
    } else {
      // became a bird
      let col = lerp(40, 220, t);
      stroke(col, col, col - 10, lerp(150, 255, t));
      strokeWeight(lerp(2, 3, t));
      noFill();
      let w = s * 1.1;
      beginShape();
      vertex(px - w, py);
      quadraticVertex(px - w * 0.4, py - w * 0.5, px, py);
      quadraticVertex(px + w * 0.4, py - w * 0.5, px + w, py);
      endShape();
    }
  }

  // A few birds dissolving into the light itself
  for (let i = 0; i < 20; i++) {
    let a = random(TWO_PI);
    let rr = random(120, 220);
    let px = mx + cos(a) * rr;
    let py = my + sin(a) * rr;
    stroke(235, 230, 210, random(40, 120));
    strokeWeight(2);
    noFill();
    let w = random(6, 11);
    beginShape();
    vertex(px - w, py);
    quadraticVertex(px - w * 0.4, py - w * 0.5, px, py);
    quadraticVertex(px + w * 0.4, py - w * 0.5, px + w, py);
    endShape();
  }
}

// recursive branch
function branch(x, y, angle, len, thick) {
  if (len < 8 || thick < 0.6) return;
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;
  strokeWeight(thick);
  stroke(8, 9, 13);
  line(x, y, x2, y2);

  let nBranch = floor(random(2, 4));
  for (let i = 0; i < nBranch; i++) {
    let na = angle + random(-38, 38);
    let nl = len * random(0.62, 0.78);
    branch(x2, y2, na, nl, thick * 0.66);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const horizon = 1180;

  // --- SKY GRADIENT ---
  for (let y = 0; y < horizon; y++) {
    let t = y / horizon;
    let r = lerp(22, 214, pow(t, 2.2));
    let g = lerp(26, 150, pow(t, 2.0));
    let b = lerp(48, 120, pow(t, 1.6));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- PALE LIGHT (moon/sun) ---
  let mx = 900, my = 760, mr = 150;
  noStroke();
  for (let i = 60; i > 0; i--) {
    let a = map(i, 0, 60, 60, 0);
    fill(250, 240, 210, a);
    ellipse(mx, my, mr * 2 + i * 7, mr * 2 + i * 7);
  }
  fill(252, 246, 224);
  ellipse(mx, my, mr * 2, mr * 2);

  // --- WATER ---
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let r = lerp(120, 14, t);
    let g = lerp(96, 18, t);
    let b = lerp(92, 34, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // moon reflection on water, broken into strokes
  noFill();
  for (let y = horizon; y < height; y += 6) {
    let t = (y - horizon) / (height - horizon);
    let w = lerp(mr * 1.6, mr * 0.3, t);
    let wob = noise(y * 0.03) * 60 - 30;
    let a = map(t, 0, 1, 150, 0);
    stroke(250, 240, 210, a);
    strokeWeight(random(1, 4));
    let segs = int(random(2, 5));
    for (let s = 0; s < segs; s++) {
      let x1 = mx - w / 2 + wob + random(-20, 20);
      let x2 = x1 + random(20, w);
      line(x1, y, x2, y);
    }
  }

  // gentle horizontal water texture
  for (let i = 0; i < 400; i++) {
    let y = random(horizon, height);
    let x = random(width);
    let t = (y - horizon) / (height - horizon);
    stroke(255, 255, 240, map(t, 0, 1, 40, 5));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(20, 90), y);
  }

  // --- BARE TREE ---
  drawTree(340, horizon, 300);

  // --- FALLING LEAVES ---
  drawLeaves();
}

function drawTree(baseX, baseY, trunkH) {
  stroke(18, 14, 16);
  strokeCap(ROUND);
  branch(baseX, baseY, -90, trunkH, 34, 9);
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 8) return;
  let rad = radians(angle);
  let ex = x + cos(rad) * len;
  let ey = y + sin(rad) * len;
  strokeWeight(w);
  // slight wobble
  let mx = (x + ex) / 2 + random(-6, 6);
  let my = (y + ey) / 2 + random(-6, 6);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(mx, my, ex, ey);
  endShape();

  let n = random() < 0.4 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let na = angle + random(-42, 42) + (i - n / 2) * 10;
    branch(ex, ey, na, len * random(0.62, 0.78), w * 0.66, depth - 1);
  }
}

function drawLeaves() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    let x = random(250, 700) + random(-60, 900) * random();
    let y = random(200, 1150);
    let s = random(10, 26);
    let rot = random(TWO_PI);
    let c = color(
      random(180, 230),
      random(90, 150),
      random(40, 80),
      random(120, 220)
    );
    fill(c);
    push();
    translate(x, y);
    rotate(rot);
    ellipse(0, 0, s, s * 0.5);
    pop();
  }
  // a few leaves resting / fading on the water
  for (let i = 0; i < 14; i++) {
    let x = random(200, 1100);
    let y = random(1200, 1700);
    fill(150, 90, 60, 90);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(12, 22), random(5, 9));
    pop();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- Sky gradient (twilight) ---
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(
      color(28, 24, 48),
      lerpColor(color(92, 64, 86), color(176, 128, 110), constrain(t * 1.1, 0, 1)),
      t
    );
    stroke(c);
    line(0, y, width, y);
  }

  // --- Faint stars ---
  noStroke();
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let a = random(20, 120);
    fill(255, 250, 230, a);
    circle(x, y, random(1, 3));
  }

  // --- Pale moon with glow ---
  let mx = 1120, my = 440, mr = 150;
  for (let r = mr * 2.6; r > mr; r -= 4) {
    fill(230, 220, 200, map(r, mr, mr * 2.6, 40, 0));
    circle(mx, my, r);
  }
  fill(238, 232, 214);
  circle(mx, my, mr);
  fill(228, 220, 200, 60);
  circle(mx - 30, my - 25, mr * 0.55);

  // --- Misty horizon / ground ---
  for (let y = 1480; y < height; y++) {
    let t = (y - 1480) / (height - 1480);
    stroke(lerpColor(color(60, 44, 58), color(18, 14, 26), t));
    line(0, y, width, y);
  }
  noStroke();
  fill(176, 128, 110, 50);
  rect(0, 1440, width, 120);

  // --- Bare tree ---
  stroke(16, 12, 20);
  drawBranch(560, 1500, -90, 230, 34, 0);

  // --- Rising embers / falling leaves of light ---
  noStroke();
  for (let i = 0; i < 90; i++) {
    let x = random(380, 820) + random(-60, 60);
    let y = random(500, 1520);
    let up = map(y, 500, 1520, 1, 0);
    let size = random(4, 11) * (0.6 + up * 0.8);
    let glow = random(120, 220) * (0.4 + up * 0.9);
    fill(255, 200, 140, glow * 0.4);
    circle(x, y, size * 2.4);
    fill(255, 224, 170, glow);
    circle(x, y, size);
  }

  // A few brighter ascending motes toward the moon
  for (let i = 0; i < 24; i++) {
    let p = i / 24;
    let x = lerp(620, mx, p) + sin(i * 1.7) * 40;
    let y = lerp(1300, my + 80, p) + cos(i * 2.1) * 30;
    fill(255, 236, 190, 200 * (1 - p * 0.5));
    circle(x, y, map(p, 0, 1, 9, 3));
  }
}

function drawBranch(x, y, ang, len, w, depth) {
  if (depth > 6 || len < 8) return;
  let rad = radians(ang);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;
  strokeWeight(w);
  line(x, y, x2, y2);

  let n = depth < 2 ? 2 : 2;
  for (let i = 0; i < n; i++) {
    let spread = random(18, 40) * (i === 0 ? -1 : 1);
    drawBranch(x2, y2, ang + spread + random(-8, 8),
      len * random(0.68, 0.82), w * 0.66, depth + 1);
  }
  if (random() < 0.4) {
    drawBranch(x2, y2, ang + random(-12, 12),
      len * 0.7, w * 0.6, depth + 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- Sky gradient: deep night above, dusk glow below ---
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 120, pow(t, 1.6));
    let g = lerp(22, 70, pow(t, 1.8));
    let b = lerp(40, 55, pow(t, 2.2));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Subtle star / dust texture ---
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(height * 0.75);
    let n = noise(x * 0.01, y * 0.01);
    let a = map(n, 0, 1, 0, 60) * (1 - y / (height * 0.75));
    fill(230, 225, 200, a);
    circle(x, y, random(0.5, 2.2));
  }

  // --- Moon ---
  let mx = 1180, my = 430, mr = 150;
  for (let i = 60; i > 0; i--) {
    fill(230, 225, 200, map(i, 0, 60, 30, 0));
    circle(mx, my, mr * 2 + i * 4);
  }
  fill(235, 230, 205);
  circle(mx, my, mr * 2);
  // moon shading
  fill(90, 90, 100, 40);
  circle(mx + 30, my - 20, mr * 1.6);
  fill(235, 230, 205);
  circle(mx + 10, my - 10, mr * 1.5);

  // --- Ground ---
  for (let y = height * 0.78; y < height; y++) {
    let t = (y - height * 0.78) / (height * 0.22);
    fill(lerp(28, 8, t), lerp(26, 10, t), lerp(30, 14, t));
    rect(0, y, width, 1);
  }

  // --- The tree ---
  stroke(12, 10, 14);
  let baseX = 560;
  let baseY = height * 0.82;
  drawBranch(baseX, baseY, -90, 300, 46);

  // --- Falling leaves drifting into the dark ---
  noStroke();
  for (let i = 0; i < 180; i++) {
    let px = random(300, 1100);
    let drift = random(-120, 120);
    let py = random(400, height * 0.98);
    let fall = map(py, 400, height, 0, 1);
    let x = px + drift * fall;
    let sz = random(5, 16) * (1 - fall * 0.4);
    let hue = random(1);
    if (hue < 0.5) fill(150, 80, 40, 200);
    else if (hue < 0.8) fill(180, 120, 50, 190);
    else fill(90, 50, 40, 180);
    push();
    translate(x, py);
    rotate(random(TWO_PI));
    ellipse(0, 0, sz, sz * 0.5);
    pop();
  }

  // --- Vignette ---
  for (let i = 0; i < 300; i++) {
    noFill();
    stroke(5, 4, 10, 2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function drawBranch(x, y, angle, len, w) {
  if (len < 14 || w < 0.8) return;
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;

  strokeWeight(w);
  // slight bend via mid point
  let mx = (x + x2) / 2 + random(-len * 0.1, len * 0.1);
  let my = (y + y2) / 2;
  noFill();
  beginShape();
  curveVertex(x, y);
  curveVertex(x, y);
  curveVertex(mx, my);
  curveVertex(x2, y2);
  curveVertex(x2, y2);
  endShape();

  let n = floor(random(2, 4));
  for (let i = 0; i < n; i++) {
    let na = angle + random(-42, 42);
    drawBranch(x2, y2, na, len * random(0.62, 0.78), w * 0.68);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- Sky gradient: twilight fading to dusk ---
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(40, 190, 1 - t) + lerp(0, 40, t);
    let g = lerp(45, 120, 1 - t) + lerp(0, 20, t);
    let b = lerp(70, 95, 1 - t);
    // deepen toward top
    r = lerp(28, r, pow(1 - t, 0.6) + 0.15);
    g = lerp(32, g, pow(1 - t, 0.6) + 0.15);
    b = lerp(55, b, pow(1 - t, 0.6) + 0.15);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Faint pale moon ---
  noStroke();
  let mx = 1180, my = 460, mr = 150;
  for (let i = 6; i > 0; i--) {
    fill(230, 220, 190, 12);
    ellipse(mx, my, mr * i * 0.7);
  }
  fill(235, 228, 200);
  ellipse(mx, my, mr);
  fill(210, 200, 170, 60);
  ellipse(mx - 30, my - 20, mr * 0.5);

  // --- Ground ---
  let horizon = 1520;
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let r = lerp(45, 20, t);
    let g = lerp(42, 18, t);
    let b = lerp(50, 24, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- The bare tree ---
  stroke(18, 16, 20);
  let trunkX = 560, trunkBase = 1540;
  drawBranch(trunkX, trunkBase, -90, 420, 46, 0);

  // --- Fallen leaves gathered at roots ---
  for (let i = 0; i < 260; i++) {
    let lx = trunkX + randomGaussian(0, 230);
    let ly = trunkBase + random(10, 300);
    drawLeaf(lx, ly, random(TWO_PI), random(10, 22), leafColor(0.9));
  }

  // --- Falling / drifting leaves in the air ---
  for (let i = 0; i < 70; i++) {
    let lx = random(width);
    let ly = random(200, horizon);
    let s = map(ly, 200, horizon, 10, 22);
    drawLeaf(lx, ly, random(TWO_PI), s, leafColor(random(0.4, 1)));
  }
}

function leafColor(a) {
  let c = random();
  let col;
  if (c < 0.4) col = color(180, 90, 40);      // burnt orange
  else if (c < 0.7) col = color(150, 50, 45);  // deep red
  else if (c < 0.9) col = color(190, 150, 60); // ochre
  else col = color(110, 80, 50);               // brown
  col.setAlpha(255 * a);
  return col;
}

function drawLeaf(x, y, ang, s, col) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.6, -s * 0.4, s * 0.6, s * 0.4, 0, s);
  bezierVertex(-s * 0.6, s * 0.4, -s * 0.6, -s * 0.4, 0, -s);
  endShape(CLOSE);
  pop();
}

function drawBranch(x, y, angle, len, thick, depth) {
  if (depth > 9 || len < 8) return;
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;

  strokeWeight(thick);
  // slight curve via midpoint
  let mx = (x + x2) / 2 + random(-len * 0.08, len * 0.08);
  let my = (y + y2) / 2 + random(-len * 0.08, len * 0.08);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(mx, my, x2, y2);
  endShape();

  let n = (depth < 2) ? 2 : (random() < 0.7 ? 2 : 3);
  for (let i = 0; i < n; i++) {
    let spread = random(18, 42) * (i % 2 === 0 ? 1 : -1);
    drawBranch(x2, y2, angle + spread + random(-8, 8),
               len * random(0.62, 0.78), thick * 0.68, depth + 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const horizon = 1180;

  // ---- SKY GRADIENT ----
  for (let y = 0; y < horizon; y++) {
    let t = y / horizon;
    let r, g, b;
    if (t < 0.55) {
      let u = t / 0.55;
      r = lerp(14, 40, u);
      g = lerp(16, 34, u);
      b = lerp(34, 58, u);
    } else {
      let u = (t - 0.55) / 0.45;
      r = lerp(40, 214, u);
      g = lerp(34, 170, u);
      b = lerp(58, 120, u);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // ---- GLOW AT HORIZON ----
  noStroke();
  for (let i = 0; i < 260; i++) {
    let a = map(i, 0, 260, 60, 0);
    fill(248, 214, 150, a);
    ellipse(width * 0.5, horizon, 1600 - i * 5, 600 - i * 2.2);
  }

  // ---- PALE MOON / LIGHT SOURCE ----
  for (let i = 90; i > 0; i--) {
    fill(255, 244, 220, 3);
    ellipse(width * 0.5, horizon - 150, i * 5, i * 5);
  }
  fill(255, 248, 232);
  ellipse(width * 0.5, horizon - 150, 150, 150);

  // ---- STARS ----
  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(horizon * 0.7);
    let s = random(1, 3.5);
    fill(255, 255, 255, random(40, 160));
    ellipse(x, y, s, s);
  }

  // ---- WATER ----
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let r = lerp(36, 8, t);
    let g = lerp(30, 10, t);
    let b = lerp(52, 22, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // reflection of light on water
  noStroke();
  for (let i = 0; i < 180; i++) {
    let y = horizon + i * 4.2;
    let w = 160 + noise(i * 0.3) * 220 + i * 1.4;
    let a = map(i, 0, 180, 90, 0);
    fill(245, 205, 150, a);
    let jitter = sin(i * 0.9) * 18;
    ellipse(width * 0.5 + jitter, y, w, 7);
  }

  // subtle horizontal ripples
  stroke(255, 255, 255, 10);
  for (let i = 0; i < 70; i++) {
    let y = horizon + random(10, height - horizon);
    let lx = random(width);
    line(lx, y, lx + random(40, 160), y);
  }

  // ---- MIST BANDS ----
  noStroke();
  for (let i = 0; i < 6; i++) {
    let y = horizon - 40 + i * 30;
    fill(230, 225, 230, 16);
    ellipse(width * 0.5 + sin(i) * 120, y, 1700, 90);
  }

  // ---- WITHERED TREE (left) ----
  drawTree(300, horizon + 30);

  // ---- BOAT with ferryman ----
  drawBoat(width * 0.5, horizon + 180);

  // ---- FALLING LEAVES BECOMING BIRDS ----
  // leaves near tree
  for (let i = 0; i < 40; i++) {
    let x = 300 + random(-180, 260);
    let y = random(horizon - 500, horizon - 40);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(150, 90, 60, random(120, 200));
    noStroke();
    ellipse(0, 0, random(8, 16), random(4, 8));
    pop();
  }
  // transitioning birds rising toward the light
  for (let i = 0; i < 34; i++) {
    let p = i / 34;
    let x = lerp(500, width * 0.5, p) + random(-40, 40);
    let y = lerp(horizon - 80, horizon - 420, p) + random(-30, 30);
    let s = lerp(9, 22, p);
    let a = lerp(150, 230, p);
    drawBird(x, y, s, a);
  }

  // ---- VIGNETTE ----
  for (let i = 0; i < 220; i++) {
    noFill();
    stroke(6, 6, 14, 2);
    rect(-i, -i, width + i * 2, height + i * 2);
  }
}

function drawTree(bx, by) {
  stroke(18, 14, 18);
  strokeWeight(26);
  line(bx, by, bx, by - 300);
  branch(bx, by - 300, -HALF_PI, 150, 18);
}

function branch(x, y, ang, len, w) {
  if (len < 14 || w < 1.2) return;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  strokeWeight(w);
  stroke(16, 12, 16);
  line(x, y, x2, y2);
  branch(x2, y2, ang - random(0.3, 0.6), len * 0.72, w * 0.68);
  branch(x2, y2, ang + random(0.3, 0.6), len * 0.72, w * 0.68);
  if (random() < 0.3) branch(x2, y2, ang + random(-0.15, 0.15), len * 0.6, w * 0.5);
}

function drawBoat(cx, cy) {
  push();
  // reflection
  noStroke();
  fill(0, 0, 0, 40);
  beginShape();
  vertex(cx - 150, cy + 10);
  vertex(cx + 150, cy + 10);
  vertex(cx + 110, cy + 70);
  vertex(cx - 110, cy + 70);
  endShape(CLOSE);

  // hull
  fill(10, 8, 14);
  stroke(10, 8, 14);
  beginShape();
  vertex(cx - 150, cy - 8);
  vertex(cx + 150, cy - 8);
  vertex(cx + 108, cy + 28);
  vertex(cx - 108, cy + 28);
  endShape(CLOSE);

  // standing ferryman silhouette
  noStroke();
  fill(8, 6, 10);
  rect(cx + 40, cy - 150, 20, 150, 6);          // body/cloak
  ellipse(cx + 50, cy - 160, 34, 40);            // head/hood
  // long pole
  stroke(8, 6, 10);
  strokeWeight(7);
  line(cx + 20, cy - 220, cx + 95, cy + 40);
  pop();
}

function drawBird(x, y, s, a) {
  push();
  translate(x, y);
  stroke(20, 18, 28, a);
  strokeWeight(map(s, 9, 22, 2.5, 4.5));
  noFill();
  let w = s;
  beginShape();
  vertex(-w, 0);
  quadraticVertex(-w * 0.4, -w * 0.55, 0, 0);
  quadraticVertex(w * 0.4, -w * 0.55, w, 0);
  endShape();
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const horizon = 1240;

  // --- Ciel : dégradé indigo vers ambre ---
  for (let y = 0; y < horizon; y++) {
    let t = y / horizon;
    let r = lerp(18, 220, pow(t, 2.4));
    let g = lerp(22, 150, pow(t, 2.8));
    let b = lerp(46, 96, pow(t, 1.6));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Lueur de l'horizon ---
  const gx = width * 0.5;
  const gy = horizon - 10;
  for (let i = 520; i > 0; i -= 2) {
    let a = map(i, 0, 520, 90, 0);
    noStroke();
    fill(255, 225, 165, a * 0.5);
    ellipse(gx, gy, i * 2.6, i * 1.2);
  }
  noStroke();
  fill(255, 245, 210, 180);
  ellipse(gx, gy, 230, 180);
  fill(255, 252, 235, 230);
  ellipse(gx, gy, 120, 100);

  // --- Poussière d'étoiles / cendres dans le ciel ---
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(horizon * 0.95);
    let d = random(1.5, 4.5);
    let a = random(30, 150) * (1 - y / horizon * 0.5);
    fill(255, 240, 220, a);
    ellipse(x, y, d, d);
  }

  // --- Texture nuageuse du ciel (coups de pinceau) ---
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(horizon);
    let n = noise(x * 0.004, y * 0.004);
    if (n > 0.52) {
      let t = y / horizon;
      let a = (n - 0.52) * 120 * t;
      fill(235, 180, 140, a);
      let w = random(20, 70);
      ellipse(x, y, w, w * 0.3);
    }
  }

  // --- Eau sombre ---
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let r = lerp(40, 10, t);
    let g = lerp(44, 14, t);
    let b = lerp(60, 26, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Reflet lumineux sur l'eau ---
  for (let y = horizon; y < height; y += 3) {
    let t = (y - horizon) / (height - horizon);
    let wobble = noise(y * 0.08) * 60 - 30;
    let wdt = lerp(200, 520, t);
    let a = (1 - t) * 150;
    fill(255, 225, 170, a * (0.5 + 0.5 * noise(y * 0.2)));
    let yy = y + sin(y * 0.3) * 2;
    ellipse(gx + wobble, yy, wdt * (0.3 + noise(y * 0.05) * 0.4), 4);
  }

  // --- Ondulations horizontales de l'eau ---
  for (let i = 0; i < 900; i++) {
    let y = random(horizon, height);
    let x = random(width);
    let t = (y - horizon) / (height - horizon);
    let a = random(15, 70) * (1 - t * 0.6);
    stroke(180, 190, 210, a);
    strokeWeight(random(0.5, 2));
    let len = random(30, 120);
    line(x, y, x + len, y + random(-1, 1));
  }
  noStroke();

  // --- La barque ---
  push();
  translate(gx - 40, horizon + 150);
  // reflet de la barque
  fill(0, 0, 0, 60);
  beginShape();
  vertex(-150, 20);
  vertex(150, 20);
  bezierVertex(110, 90, -110, 90, -150, 20);
  endShape(CLOSE);
  // coque
  fill(14, 12, 18);
  beginShape();
  vertex(-160, 0);
  vertex(160, 0);
  bezierVertex(120, -70, -120, -70, -160, 0);
  endShape(CLOSE);
  // figure assise
  fill(10, 9, 14);
  ellipse(10, -58, 46, 60);      // corps
  ellipse(10, -96, 30, 34);      // tête
  // rame
  stroke(12, 10, 16);
  strokeWeight(7);
  line(60, -70, 150, 30);
  noStroke();
  // petite lanterne
  fill(255, 210, 120, 220);
  ellipse(-110, -70, 20, 26);
  fill(255, 240, 190, 120);
  ellipse(-110, -70, 44, 54);
  pop();

  // --- Pétales / cendres qui tombent ---
  for (let i = 0; i < 40; i++) {
    let x = random(width);
    let y = random(horizon * 1.1);
    let s = random(4, 10);
    fill(255, 200, 170, random(60, 160));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.45);
    pop();
  }

  // --- Vignette ---
  for (let i = 0; i < 260; i++) {
    let a = i * 0.5;
    noFill();
    stroke(6, 5, 12, a * 0.12);
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
  noStroke();

  // --- Grain pictural final ---
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let v = random(-12, 12);
    fill(128 + v, 128 + v, 128 + v, 14);
    rect(x, y, 2, 2);
  }
}

function setup() {
