}

function draw() {
  // --- Ciel en dégradé ---
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.55) {
      let k = t / 0.55;
      r = lerp(18, 60, k);
      g = lerp(20, 55, k);
      b = lerp(45, 80, k);
    } else {
      let k = (t - 0.55) / 0.45;
      r = lerp(60, 15, k);
      g = lerp(55, 18, k);
      b = lerp(80, 30, k);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Étoiles ---
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let s = random(1, 3);
    fill(255, 255, 240, random(40, 180));
    circle(x, y, s);
  }

  // --- Lune ---
  let mx = width * 0.5;
  let my = height * 0.26;
  let mr = 300;
  for (let r = mr; r > 0; r -= 2) {
    let a = map(r, mr, 0, 0, 20);
    fill(230, 230, 210, a);
    circle(mx, my, r * 2.4);
  }
  fill(238, 236, 220);
  circle(mx, my, mr);
  // cratères subtils
  fill(220, 218, 200, 120);
  circle(mx - 70, my - 50, 55);
  circle(mx + 60, my + 40, 80);
  circle(mx + 20, my - 80, 35);
  circle(mx - 40, my + 90, 45);

  // --- Eau ---
  let horizon = height * 0.58;
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let r = lerp(20, 8, t);
    let g = lerp(22, 10, t);
    let b = lerp(40, 20, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Reflet de la lune ---
  noStroke();
  for (let y = horizon; y < height; y += 4) {
    let t = (y - horizon) / (height - horizon);
    let w = lerp(120, 40, t) + noise(y * 0.05) * 60;
    let a = lerp(70, 0, t);
    fill(230, 228, 200, a);
    let wob = sin(y * 0.3) * 10;
    rect(mx - w / 2 + wob, y, w, 3);
  }

  // --- Ondulations de surface ---
  stroke(200, 200, 180, 20);
  for (let i = 0; i < 70; i++) {
    let y = random(horizon, height);
    let x = random(width);
    let w = random(40, 160);
    strokeWeight(random(1, 2));
    noFill();
    line(x, y, x + w, y);
  }

