      let a = map(r, s * 4, 0, 0, 30);
      fill(255, 220, 150, a);
      circle(x, y, r);
    }
    fill(255, 240, 200, 220);
    circle(x, y, s);
  }

  // --- La barque et le passeur ---
  let bx = width * 0.5;
  let by = horizon + 70;

  // reflet de la barque
  push();
  translate(bx, by + 30);
  scale(1, -0.5);
  noStroke();
  fill(0, 0, 0, 60);
  drawBoat();
  pop();

  push();
  translate(bx, by);
  drawBoat();
  pop();

  // --- Vignette ---
  noFill();
  for (let r = 0; r < 400; r += 2) {
    stroke(5, 5, 15, map(r, 0, 400, 60, 0));
    strokeWeight(2);
    rect(r, r, width - r * 2, height - r * 2);
  }
}

