function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- CIEL : dégradé crépusculaire ---
  for (let y = 0; y < 1300; y++) {
    let t = y / 1300;
    let r = lerp(28, 212, pow(t, 2.2));
    let g = lerp(26, 138, pow(t, 2.0));
    let b = lerp(48, 86, pow(t, 1.6));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // --- Lueur de l'horizon ---
  noStroke();
  for (let i = 220; i > 0; i -= 2) {
    let a = map(i, 0, 220, 60, 0);
    fill(248, 224, 150, a);
    ellipse(width * 0.62, 1300, i * 7, i * 2.4);
  }

  // --- Lune pâle ---
  for (let i = 160; i > 0; i -= 3) {
    fill(250, 244, 220, map(i, 0, 160, 55, 0));
    ellipse(width * 0.3, 430, i * 1.9);
  }
  fill(244, 240, 226);
  ellipse(width * 0.3, 430, 190);

  // --- EAU : reflet sous l'horizon ---
  for (let y = 1300; y < height; y++) {
    let t = (y - 1300) / (height - 1300);
    let r = lerp(40, 14, t);
    let g = lerp(44, 16, t);
    let b = lerp(66, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }
  // reflets scintillants
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(1305, height);
    let a = map(y, 1300, height, 90, 5);
    fill(240, 220, 160, a * random(0.3, 1));
    rect(x, y, random(20, 90), random(1, 3));
  }

  // --- ARBRE dénudé ---
  stroke(16, 14, 22);
  strokeCap(ROUND);
  let baseX = width * 0.33;
  let baseY = 1300;
  branch(baseX, baseY, -90, 300, 46);

  // --- FEUILLES qui deviennent oiseaux ---
  for (let i = 0; i < 160; i++) {
    let prog = random();
    // trajectoire : du feuillage vers l'horizon lumineux
    let sx = baseX + random(-260, 160);
    let sy = random(300, 900);
    let ex = width * 0.62 + random(-120, 120);
    let ey = 1300 + random(-180, 10);
    let x = lerp(sx, ex, prog) + sin(prog * 6) * 40;
    let y = lerp(sy, ey, prog * prog);
    let s = lerp(26, 9, prog);

    if (prog < 0.45) {
      // feuille qui tombe
      push();
      translate(x, y);
      rotate(random(TWO_PI));
      noStroke();
      fill(200, lerp(90, 150, random()), 60, 220);
      ellipse(0, 0, s, s * 0.5);
      pop();
    } else {
      // oiseau (deux arcs)
      stroke(20, 18, 26, 230);
      strokeWeight(map(prog, 0.45, 1, 3, 1.2));
      noFill();
      let w = s * 0.8;
      arc(x - w * 0.5, y, w, w * 0.7, PI, TWO_PI);
      arc(x + w * 0.5, y, w, w * 0.7, PI, TWO_PI);
    }
  }

  // --- Vignettage doux ---
  noFill();
  for (let i = 0; i < 160; i++) {
    stroke(8, 6, 14, i * 0.5);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function branch(x, y, angle, len, w) {
  if (len < 14 || w < 0.6) return;
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;
  strokeWeight(w);
  line(x, y, x2, y2);
  let n = floor(random(2, 4));
  for (let i = 0; i < n; i++) {
    let da = random(-34, 34) + (i - n / 2) * 12;
    branch(x2, y2, angle + da, len * random(0.62, 0.78), w * 0.64);
  }
}

