function drawBranch(x1, y1, len, angle, depth) {
  if (depth <= 0) return;
  let x2 = x1 + sin(angle) * len;
  let y2 = y1 - cos(angle) * len;

  let w = depth * 2.2;
  // 右侧偏暖（生），左侧偏冷（死）
  let side = x2 - x1;
  let warm = constrain(map(side, -200, 200, 0, 1), 0, 1);
  let r = lerp(55, 80, warm);
  let g = lerp(48, 60, warm);
  let b = lerp(52, 45, warm);
  stroke(r, g, b);
  strokeWeight(w);
  line(x1, y1, x2, y2);

  if (depth <= 3) {
    // 末梢处偶有残叶（多在右侧）
    if (warm > 0.55 && random() < 0.6) {
      noStroke();
      let lr = lerp(120, 180, random());
      fill(lr, lerp(70, 110, random()), 40, 200);
      ellipse(x2, y2, random(8, 16), random(8, 16));
    }
  }

  let n = depth > 6 ? 2 : (random() < 0.85 ? 2 : 1);
  for (let i = 0; i < n; i++) {
    let spread = random(0.35, 0.75);
    let da = (i === 0 ? -spread : spread) + random(-0.1, 0.1);
    let nl = len * random(0.68, 0.8);
    drawBranch(x2, y2, nl, angle + da, depth - 1);
  }
}

function drawFalling() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(300, 1300);
    let y = random(700, 1560);
    // 越往下越碎、越暗、越透明
    let fall = map(y, 700, 1560, 0, 1);
    let sz = lerp(14, 2, fall) * random(0.5, 1.2);
    let drift = sin(y * 0.01 + i) * fall * 40;
    let a = lerp(200, 25, fall);
    let warm = map(x, 300, 1300, 0.1, 0.9);
    let r = lerp(90, 170, warm) * (1 - fall * 0.5);
    let g = lerp(60, 95, warm) * (1 - fall * 0.5);
    let b = lerp(55, 50, warm) * (1 - fall * 0.4);
    fill(r, g, b, a);
    ellipse(x + drift, y, sz, sz * random(0.8, 1.4));
  }
  // 地面尘粒
  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(1560, 1960);
    fill(40, 36, 38, random(20, 70));
    ellipse(x, y, random(1, 4));
  }
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 300; i++) {
    let a = map(i, 0, 300, 55, 0);
    stroke(8, 8, 14, a);
    strokeWeight(2);
    ellipse(width / 2, height / 2, width + 300 - i * 4, height + 400 - i * 5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- Sky gradient: twilight above, warm amber near horizon ---
  let horizonY = 1350;
  for (let y = 0; y < height; y++) {
    let t = constrain(y / horizonY, 0, 1);
    let c;
    if (t < 1) {
      let top = color(28, 32, 58);
      let mid = color(92, 70, 96);
      let low = color(224, 150, 86);
      if (t < 0.6) {
        c = lerpColor(top, mid, t / 0.6);
      } else {
        c = lerpColor(mid, low, (t - 0.6) / 0.4);
      }
    } else {
      c = color(40, 30, 40);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // --- The glow of the setting sun ---
  let sunX = 1120, sunY = 1280;
  noStroke();
  for (let r = 620; r > 0; r -= 6) {
    let a = map(r, 0, 620, 150, 0);
    fill(255, 210, 140, a * 0.35);
    ellipse(sunX, sunY, r, r);
  }
  fill(255, 236, 196);
  ellipse(sunX, sunY, 150, 150);

  // --- Distant hill silhouette ---
  noStroke();
  fill(54, 44, 56);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let y = 1420 + noise(x * 0.0015) * 180 - 90 + sin(x * 0.004) * 40;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  // Foreground hill (darker)
  fill(28, 22, 30);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let y = 1600 + noise(100 + x * 0.002) * 160 - 60;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  // --- The bare tree ---
  let rootX = 470, rootY = 1650;
  stroke(18, 14, 18);
  strokeCap(ROUND);
  drawBranch(rootX, rootY, -90, 300, 40);

  // --- Falling leaves morphing into birds ---
  // leaves near the tree, birds higher and toward the light
  for (let i = 0; i < 90; i++) {
    // path from tree crown toward the sun
    let startX = rootX + random(-260, 260);
    let startY = rootY - 600 + random(-200, 200);
    let prog = random(1); // 0 = leaf near tree, 1 = bird near sun
    let x = lerp(startX, sunX + random(-260, 180), prog) + random(-30, 30);
    let y = lerp(startY, sunY - 500 + random(-200, 300), prog * prog);

    let warm = lerpColor(color(150, 70, 40), color(255, 190, 120), prog);
    if (prog < 0.4) {
      // a leaf
      let s = lerp(26, 14, prog / 0.4);
      drawLeaf(x, y, s, random(TWO_PI), warm);
    } else {
      // a bird
      let s = lerp(16, 34, (prog - 0.4) / 0.6);
      drawBird(x, y, s, warm);
    }
  }

  // --- A few remaining leaves clinging to branches ---
  for (let i = 0; i < 14; i++) {
    let x = rootX + random(-240, 240);
    let y = rootY - 560 + random(-180, 160);
    drawLeaf(x, y, random(18, 28), random(TWO_PI), color(120, 55, 35));
  }

  // subtle vignette
  noFill();
  for (let r = 0; r < 300; r++) {
    stroke(10, 8, 14, r * 0.25);
    noFill();
    rect(-r, -r, width + 2 * r, height + 2 * r);
  }
}

function drawBranch(x, y, angle, len, w) {
  if (len < 14) return;
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;
  strokeWeight(max(1, w * 0.1));
  stroke(20, 15, 18);
  line(x, y, x2, y2);

  let n = floor(random(2, 4));
  for (let i = 0; i < n; i++) {
    let da = random(-42, 42) + (i - n / 2) * 10;
    drawBranch(x2, y2, angle + da, len * random(0.62, 0.78), w * 0.68);
  }
}

function drawLeaf(x, y, s, rot, col) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, -s * 0.5);
  bezierVertex(s * 0.5, -s * 0.3, s * 0.4, s * 0.4, 0, s * 0.6);
  bezierVertex(-s * 0.4, s * 0.4, -s * 0.5, -s * 0.3, 0, -s * 0.5);
  endShape(CLOSE);
  pop();
}

function drawBird(x, y, s, col) {
  push();
  translate(x, y);
  noFill();
  stroke(col);
  strokeWeight(s * 0.14);
  let w = s;
  beginShape();
  vertex(-w, 0);
  quadraticVertex(-w * 0.4, -w * 0.5, 0, 0);
  quadraticVertex(w * 0.4, -w * 0.5, w, 0);
  endShape();
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 背景渐变：上方深夜，下方余晖
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 120, pow(t, 1.6));
    let g = lerp(22, 70, pow(t, 1.8));
    let b = lerp(40, 55, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 远方地平线光晕
  let gx = width * 0.5;
  let gy = height * 0.72;
  noStroke();
  for (let i = 220; i > 0; i -= 2) {
    fill(255, 180, 120, 2);
    ellipse(gx, gy, i * 6, i * 2.2);
  }

  // 月
  fill(230, 225, 210, 60);
  ellipse(width * 0.74, height * 0.22, 230, 230);
  fill(240, 238, 225, 90);
  ellipse(width * 0.74, height * 0.22, 190, 190);

  // 大地
  noStroke();
  fill(14, 14, 20);
  beginShape();
  vertex(0, height);
  vertex(0, height * 0.74);
  for (let x = 0; x <= width; x += 20) {
    let yy = height * 0.74 + noise(x * 0.004) * 60;
    vertex(x, yy);
  }
  vertex(width, height);
  endShape(CLOSE);

  // 树
  stroke(8, 8, 12);
  let trunkX = width * 0.38;
  let trunkY = height * 0.75;
  drawBranch(trunkX, trunkY, -PI / 2, 300, 34);

  // 坠落的叶 —— 暗色，向下
  for (let i = 0; i < 120; i++) {
    let x = trunkX + random(-380, 380);
    let y = random(height * 0.3, height * 0.74);
    let s = random(3, 9);
    noStroke();
    fill(40, 30, 25, random(120, 200));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.5);
    pop();
  }

  // 升腾的微光 —— 暖色，向上
  for (let i = 0; i < 260; i++) {
    let baseX = trunkX + random(-250, 250);
    let prog = random(1);
    let x = baseX + sin(prog * 6 + i) * 60 * prog;
    let y = lerp(trunkY - 60, height * 0.08, prog);
    let s = lerp(7, 1.5, prog);
    let a = lerp(200, 20, prog);
    noStroke();
    fill(255, 210, 140, a * 0.4);
    ellipse(x, y, s * 3);
    fill(255, 240, 200, a);
    ellipse(x, y, s);
  }

  // 整体柔光叠加
  noStroke();
  fill(255, 200, 150, 8);
  ellipse(gx, gy, width * 1.6, height);
}

function drawBranch(x, y, angle, len, w) {
  if (len < 14 || w < 1) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  strokeWeight(w);
  line(x, y, x2, y2);

  let n = floor(random(2, 4));
  for (let i = 0; i < n; i++) {
    let na = angle + random(-0.6, 0.6);
    drawBranch(x2, y2, na, len * random(0.6, 0.78), w * 0.68);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const horizon = 1250;

  // ---- Sky gradient ----
  for (let y = 0; y < horizon; y++) {
    const t = y / horizon;
    const r = lerp(28, 196, pow(t, 2.2));
    const g = lerp(30, 120, pow(t, 2.4));
    const b = lerp(55, 70, pow(t, 1.4));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // ---- Soft glowing orb low on horizon ----
  const sunX = width * 0.5;
  const sunY = horizon - 40;
  noStroke();
  for (let r = 420; r > 0; r -= 4) {
    const a = map(r, 0, 420, 70, 0);
    fill(230, 160, 90, a);
    ellipse(sunX, sunY, r * 2);
  }
  fill(245, 205, 140);
  ellipse(sunX, sunY, 150);

  // ---- Stars / faint texture in upper sky ----
  for (let i = 0; i < 260; i++) {
    const x = random(width);
    const y = random(horizon * 0.65);
    const a = random(20, 120) * (1 - y / horizon);
    fill(255, 255, 230, a);
    ellipse(x, y, random(1, 3));
  }

  // ---- Water ----
  for (let y = horizon; y < height; y++) {
    const t = (y - horizon) / (height - horizon);
    const r = lerp(40, 14, t);
    const g = lerp(44, 18, t);
    const b = lerp(70, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // ---- Reflection of light on water ----
  for (let y = horizon; y < height; y += 3) {
    const t = (y - horizon) / (height - horizon);
    const w = lerp(90, 320, t);
    const flick = noise(y * 0.05) * 60;
    const a = map(t, 0, 1, 150, 15);
    noStroke();
    fill(235, 180, 110, a * 0.5);
    const segW = random(20, 70);
    for (let x = sunX - w; x < sunX + w; x += segW) {
      const seg = segW * noise(x * 0.02, y * 0.1);
      ellipse(x + flick, y, seg, 3);
    }
  }

  // ---- Horizon mist band ----
  for (let i = 0; i < 40; i++) {
    const y = horizon + i * 1.5;
    stroke(200, 150, 110, 40 - i);
    line(0, y, width, y);
  }

  // ---- The boat and the ferryman ----
  push();
  translate(sunX - 30, horizon + 120);
  // boat hull
  fill(10, 10, 14);
  noStroke();
  beginShape();
  vertex(-150, 0);
  bezierVertex(-90, 45, 90, 45, 150, 0);
  bezierVertex(90, 18, -90, 18, -150, 0);
  endShape(CLOSE);
  // standing figure
  fill(8, 8, 12);
  rect(-8, -120, 16, 120, 4);
  ellipse(0, -128, 26, 30);
  // the long pole
  stroke(8, 8, 12);
  strokeWeight(5);
  line(10, -130, 95, 70);
  pop();

  // ---- Lantern glow on the boat ----
  const lx = sunX - 125;
  const ly = horizon + 95;
  noStroke();
  for (let r = 120; r > 0; r -= 4) {
    fill(255, 190, 110, map(r, 0, 120, 60, 0));
    ellipse(lx, ly, r * 2);
  }
  fill(255, 230, 170);
  ellipse(lx, ly, 18);

  // ---- Drifting embers / spirits rising ----
  for (let i = 0; i < 120; i++) {
    const x = sunX + random(-500, 500) * random();
    const y = random(200, horizon + 80);
    const d = random(2, 6);
    const a = random(40, 160) * (1 - y / height);
    fill(255, 210, 150, a);
    ellipse(x, y, d);
  }

  // ---- Vignette ----
  noFill();
  for (let r = 0; r < 500; r += 2) {
    stroke(0, 0, 0, map(r, 0, 500, 60, 0));
    ellipse(width / 2, height / 2, width + 400 - r, height + 400 - r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 天空渐变：从深蓝到苍白的光
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 210, pow(1 - t, 1.4));
    let g = lerp(22, 200, pow(1 - t, 1.3));
    let b = lerp(38, 180, pow(1 - t, 1.1));
    // 上方的光晕
    let glow = exp(-pow((t - 0.18) * 4.0, 2)) * 60;
    stroke(r + glow, g + glow, b + glow * 0.8);
    line(0, y, width, y);
  }

  // 柔和的光核
  noStroke();
  for (let i = 60; i > 0; i--) {
    let a = map(i, 0, 60, 0, 22);
    fill(245, 240, 220, a);
    ellipse(width * 0.5, height * 0.2, i * 14, i * 11);
  }

  // 大地
  let horizon = height * 0.74;
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    fill(lerp(26, 8, t), lerp(24, 7, t), lerp(34, 12, t));
    rect(0, y, width, 1);
  }
  // 地面雾气
  for (let i = 0; i < 40; i++) {
    noStroke();
    fill(200, 200, 190, 6);
    let yy = horizon + random(-20, 60);
    ellipse(random(width), yy, random(300, 700), random(30, 80));
  }

  // 枯树——根扎黑暗，枝梢散入光
  let baseX = width * 0.5;
  drawBranch(baseX, horizon, -PI / 2, 230, 26, 1);

  // 上升、消散的微粒
  for (let i = 0; i < 2600; i++) {
    let px = baseX + random(-260, 260) * random();
    let riseRatio = random();
    let py = lerp(horizon - 120, height * 0.14, riseRatio);
    // 越往上越散开、越亮、越透明
    px += (noise(px * 0.01, py * 0.01) - 0.5) * 300 * riseRatio;
    let sz = lerp(6, 1.2, riseRatio) * random(0.5, 1.4);
    let a = lerp(200, 20, riseRatio);
    let c = lerp(150, 245, riseRatio);
    noStroke();
    fill(c, c - 10, c - 30, a);
    ellipse(px, py, sz, sz);
  }
}

function drawBranch(x, y, angle, len, w, depth) {
  if (depth > 9 || len < 6) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  // 颜色：底部暗，枝梢偏亮并带透明——象征正在消散
  let fade = map(depth, 1, 9, 255, 90);
  let colR = lerp(20, 190, map(depth, 1, 9, 0, 1));
  stroke(colR, colR - 15, colR - 5, fade);
  strokeWeight(max(w, 1));
  line(x, y, x2, y2);

  let n = (depth < 3) ? 2 : (random() < 0.85 ? 2 : 1);
  for (let i = 0; i < n; i++) {
    let spread = random(0.28, 0.62) * (i === 0 ? 1 : -1);
    let na = angle + spread + (noise(x2 * 0.01, y2 * 0.01, depth) - 0.5) * 0.4;
    drawBranch(x2, y2, na, len * random(0.68, 0.8), w * 0.68, depth + 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(18, 17, 20);
  pixelDensity(1);

  // ---------- palette ----------
  const wallDark = color(34, 31, 36);
  const wallMid  = color(58, 52, 54);
  const lightWarm = color(214, 182, 136);

  // ---------- back wall with soft vignette gradient ----------
  for (let y = 0; y < 1400; y++) {
    let t = y / 1400;
    let c = lerpColor(color(26, 24, 29), color(49, 44, 47), pow(t, 0.8));
    stroke(c);
    line(0, y, width, y);
  }

  // ---------- floor ----------
  const horizon = 1240;
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let c = lerpColor(color(40, 35, 36), color(20, 18, 20), pow(t, 0.7));
    stroke(c);
    line(0, y, width, y);
  }

  // floorboards (perspective)
  push();
  const vpx = 760, vpy = 980;
  for (let i = -14; i <= 14; i++) {
    let xb = width / 2 + i * 190;
    let a = map(abs(i), 0, 14, 26, 4);
    stroke(14, 12, 14, a);
    strokeWeight(2);
    line(vpx, vpy, xb, height);
  }
  // horizontal board lines, spacing increases downward
  let yy = horizon + 6;
  let step = 12;
  while (yy < height) {
    stroke(12, 10, 12, 34);
    strokeWeight(1.4);
    line(0, yy, width, yy);
    step *= 1.17;
    yy += step;
  }
  pop();

  // ---------- window light shaft (geometry) ----------
  // Window opening on the left wall area
  const wx = 150, wy = 300, ww = 330, wh = 520;

  // The pool of light on the floor + shaft
  push();
  blendMode(ADD);
  // shaft: quad from window to floor, soft layered
  for (let i = 0; i < 70; i++) {
    let t = i / 70;
    let a = 7 * (1 - t) * (1 - t);
    noStroke();
    fill(red(lightWarm) * 0.9, green(lightWarm) * 0.82, blue(lightWarm) * 0.62, a * 3.2);
    let spread = t * 300;
    beginShape();
    vertex(wx - spread * 0.12, wy + 20 + t * 40);
    vertex(wx + ww + spread * 0.12, wy - 10 + t * 20);
    vertex(wx + ww + 520 + spread, horizon + 430);
    vertex(wx + 120 + spread * 0.5, horizon + 520);
    endShape(CLOSE);
  }
  pop();

  // ---------- window frame & glow ----------
  // glow behind
  push();
  blendMode(ADD);
  noStroke();
  for (let r = 240; r > 0; r -= 6) {
    fill(200, 170, 128, 2.4);
    ellipse(wx + ww / 2, wy + wh / 2, ww + r * 1.6, wh + r * 1.2);
  }
  pop();

  // window pane
  noStroke();
  fill(226, 203, 164);
  rect(wx, wy, ww, wh);
  // slight gradient in pane
  for (let y = 0; y < wh; y++) {
    let t = y / wh;
    stroke(lerpColor(color(246, 231, 201), color(196, 168, 126), t));
    line(wx, wy + y, wx + ww, wy + y);
  }

  // mullions
  stroke(26, 23, 25);
  strokeWeight(14);
  noFill();
  rect(wx, wy, ww, wh);
  strokeWeight(10);
  line(wx + ww / 2, wy, wx + ww / 2, wy + wh);
  line(wx, wy + wh * 0.42, wx + ww, wy + wh * 0.42);

  // sill
  noStroke();
  fill(30, 27, 29);
  rect(wx - 22, wy + wh, ww + 44, 26);

  // ---------- light pool on floor (soft ellipse) ----------
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    fill(190, 158, 112, 4.5 * (1 - t));
    push();
    translate(760, horizon + 300);
    rotate(-0.12);
    ellipse(0, 0, 1100 - t * 500, 430 - t * 220);
    pop();
  }
  pop();

  // ---------- the empty chair ----------
  drawChair(930, 1540, 1.0);

  // ---------- long shadow of chair ----------
  // (drawn as subtle dark smear going right-down, under chair already painted; add ambient occlusion)
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    fill(30, 26, 30, 7);
    push();
    translate(1150, 1600);
    rotate(0.18);
    ellipse(t * 220, t * 60, 700 - t * 300, 140 - t * 60);
    pop();
  }
  pop();

  // ---------- the absence: faint seated figure of light on the chair ----------
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 46; i++) {
    let t = i / 46;
    let a = 3.0 * (1 - t);
    fill(168, 146, 120, a);
    // head
    ellipse(930, 1218 - t * 2, 112 + t * 90, 132 + t * 95);
    // torso
    ellipse(930, 1380, 200 + t * 130, 240 + t * 120);
    // lap
    ellipse(960, 1520, 230 + t * 140, 120 + t * 90);
  }
  pop();

  // very faint silhouette edge so the absence reads as a shape
  push();
  noFill();
  stroke(188, 166, 136, 16);
  strokeWeight(3);
  ellipse(930, 1216, 108, 128);
  beginShape();
  vertex(876, 1282);
  bezierVertex(830, 1320, 818, 1420, 824, 1510);
  vertex(1038, 1510);
  bezierVertex(1044, 1420, 1032, 1320, 986, 1282);
  endShape();
  pop();

  // ---------- dust motes ----------
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(220, height);
    // density higher inside shaft
    let inShaft = shaftWeight(x, y, wx, ww, wy, horizon);
    if (random() > 0.12 + inShaft * 0.95) continue;
    let s = random(1.0, 4.2) * (0.6 + inShaft);
    let a = random(14, 95) * (0.25 + inShaft);
    fill(234, 210, 172, a);
    ellipse(x, y, s, s);
    if (random() < 0.08) {
      fill(234, 210, 172, a * 0.25);
      ellipse(x, y, s * 5, s * 5);
    }
  }
  pop();

  // ---------- doorway on right: pure darkness ----------
  noStroke();
  fill(14, 12, 15);
  rect(1330, 480, 230, 780, 4);
  // frame
  stroke(44, 39, 42, 180);
  strokeWeight(10);
  noFill();
  rect(1330, 480, 230, 780, 4);
  // faint light leak on frame edge
  push();
  blendMode(ADD);
  noStroke();
  fill(150, 124, 92, 22);
  rect(1316, 470, 16, 800);
  pop();

  // ---------- subtle wall texture / grain ----------
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 11;
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();

  // ---------- vignette ----------
  push();
  noFill();
  for (let r = 0; r < 420; r++) {
    stroke(10, 9, 12, 0.9);
    rect(-r, -r, width + r * 2, height + r * 2);
  }
  pop();

  // corner darkening
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    fill(255 * (0.88 + 0.12 * t), 255 * (0.88 + 0.12 * t), 255 * (0.9 + 0.1 * t), 14);
    ellipse(width / 2, height / 2, width * (2.1 - t * 1.1), height * (2.0 - t * 1.0));
  }
  pop();
}

function shaftWeight(x, y, wx, ww, wy, horizon) {
  // approximate the widening light shaft region
  let t = constrain((y - wy) / (horizon + 400 - wy), 0, 1);
  let cx = lerp(wx + ww / 2, wx + ww / 2 + 520, t);
  let halfW = lerp(ww / 2, ww / 2 + 420, t);
  let d = abs(x - cx) / halfW;
  if (d > 1) return 0;
  return (1 - d) * (1 - t * 0.35);
}

function drawChair(cx, baseY, s) {
  push();
  translate(cx, baseY);
  scale(s);

  const woodDark = color(42, 33, 30);
  const woodMid = color(72, 56, 46);
  const woodLit = color(136, 106, 76);

  // legs (back ones first)
  drawLeg(-108, -300, -92, 0, 16, woodDark);
  drawLeg(96, -300, 112, 0, 16, woodDark);
  // seat slab
  noStroke();
  fill(woodMid);
  beginShape();
  vertex(-150, -300);
  vertex(160, -300);
  vertex(186, -254);
  vertex(-176, -254);
  endShape(CLOSE);
  // seat top (lit)
  fill(woodLit);
  beginShape();
  vertex(-150, -300);
  vertex(160, -300);
  vertex(140, -326);
  vertex(-130, -326);
  endShape(CLOSE);

  // front legs
  drawLeg(-150, -300, -140, 10, 20, woodMid);
  drawLeg(160, -300, 172, 10, 20, woodMid);

  // back posts
  drawLeg(-130, -326, -134, -690, 20, woodMid);
  drawLeg(140, -326, 146, -690, 20, woodMid);

  // back slats
  noStroke();
  for (let i = 0; i < 3; i++) {
    let y = -430 - i * 78;
    fill(lerpColor(woodMid, woodDark, i * 0.25));
    quad(-130, y, 142, y + 2, 142, y - 26, -130, y - 28);
  }
  // top rail
  fill(woodLit);
  quad(-140, -686, 152, -682, 152, -724, -140, -728);

  // stretcher
  fill(woodDark);
  rect(-128, -140, 268, 16);

  pop();
}

function drawLeg(x1, y1, x2, y2, w, col) {
  noStroke();
  fill(col);
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang) * w / 2;
  let ny = cos(ang) * w / 2;
  quad(x1 + nx, y1 + ny, x2 + nx, y2 + ny, x2 - nx, y2 - ny, x1 - nx, y1 - ny);
  // highlight edge
  fill(red(col) * 1.35, green(col) * 1.3, blue(col) * 1.25, 150);
  quad(x1 + nx, y1 + ny, x2 + nx, y2 + ny, x2 + nx * 0.5, y2 + ny * 0.5, x1 + nx * 0.5, y1 + ny * 0.5);
}

let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(30, 28, 30);
  pixelDensity(1);

  // ---------- palette ----------
  const wallDark = color(52, 48, 50);
  const wallLight = color(126, 116, 104);
  const floorDark = color(44, 34, 30);
  const floorLight = color(120, 96, 74);

  // ---------- geometry ----------
  const horizon = H * 0.605;      // wall/floor junction
  const winX = W * 0.14, winY = H * 0.10;
  const winW = W * 0.40, winH = H * 0.36;

  // ---------- back wall ----------
  for (let y = 0; y < horizon; y++) {
    let t = y / horizon;
    let c = lerpColor(wallDark, color(78, 72, 68), pow(t, 0.7));
    stroke(c);
    line(0, y, W, y);
  }

  // soft vignette of wall grime
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = random(W), y = random(horizon);
    let n = noise(x * 0.0025, y * 0.0025);
    fill(255, 240, 220, 5 + n * 12);
    ellipse(x, y, random(20, 180), random(20, 180));
  }

  // ---------- floor ----------
  for (let y = horizon; y < H; y++) {
    let t = (y - horizon) / (H - horizon);
    let c = lerpColor(color(58, 44, 38), color(30, 22, 20), pow(t, 0.9));
    stroke(c);
    line(0, y, W, y);
  }

  // floorboards in perspective (vanishing toward window)
  const vpX = winX + winW * 0.55;
  push();
  for (let i = -14; i <= 26; i++) {
    let xb = i * 150 - 200;
    stroke(20, 14, 12, 90);
    strokeWeight(2.0);
    line(vpX, horizon, xb, H + 60);
  }
  // horizontal plank joints
  for (let k = 1; k < 26; k++) {
    let t = pow(k / 26, 2.1);
    let y = lerp(horizon, H + 80, t);
    stroke(22, 16, 14, 55);
    strokeWeight(1.4);
    line(0, y, W, y);
  }
  pop();

  // ---------- window light pool on floor ----------
  // the beam: quad from window to floor foreground
  const beamTopL = winX + 10, beamTopR = winX + winW - 10;
  const beamBotL = winX - 230, beamBotR = winX + winW + 520;

  // Draw beam as many thin quads for soft gradient
  noStroke();
  const steps = 420;
  for (let s = 0; s < steps; s++) {
    let t = s / steps;
    let y0 = lerp(horizon, H + 120, pow(t, 1.25));
    let y1 = lerp(horizon, H + 120, pow((s + 1) / steps, 1.25));
    let lx0 = lerp(beamTopL, beamBotL, pow(t, 1.1));
    let rx0 = lerp(beamTopR, beamBotR, pow(t, 1.1));
    let lx1 = lerp(beamTopL, beamBotL, pow((s + 1) / steps, 1.1));
    let rx1 = lerp(beamTopR, beamBotR, pow((s + 1) / steps, 1.1));
    let a = 150 * (1 - pow(t, 0.9));
    fill(246, 222, 172, a * 0.55);
    quad(lx0, y0, rx0, y0, rx1, y1, lx1, y1);
  }

  // warm glow where beam hits wall base near window
  for (let i = 0; i < 60; i++) {
    fill(240, 215, 170, 4);
    ellipse(vpX + 40, horizon + 30, 1200 - i * 14, 420 - i * 5);
  }

  // ---------- window ----------
  drawWindow(winX, winY, winW, winH);

  // ---------- light shafts in air ----------
  push();
  blendMode(SCREEN);
  noStroke();
  for (let s = 0; s < 90; s++) {
    let t = s / 90;
    let x0 = lerp(winX + 20, winX + winW - 20, noise(s * 0.3) * 0.9 + 0.05);
    let w0 = random(18, 70);
    let yTop = winY + winH * random(0.1, 0.9);
    let spread = random(220, 520);
    fill(255, 236, 196, 5);
    quad(x0 - w0 / 2, yTop,
         x0 + w0 / 2, yTop,
         x0 + w0 / 2 + spread, H,
         x0 - w0 / 2 + spread * 0.75, H);
  }
  pop();

  // ---------- the chair ----------
  drawChair(W * 0.63, horizon + 300, 1.0);

  // ---------- long shadow of the chair ----------
  // (drawn inside drawChair before chair itself)

  // ---------- dust motes ----------
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(winX - 150, winX + winW + 650);
    let y = random(winY, H);
    // keep mostly inside the beam cone
    let tt = constrain((y - horizon) / (H - horizon), 0, 1);
    let lx = lerp(beamTopL - 60, beamBotL, tt);
    let rx = lerp(beamTopR + 60, beamBotR, tt);
    if (y > horizon && (x < lx || x > rx)) { if (random() > 0.12) continue; }
    let r = random(1.2, 5.2);
    let a = random(30, 180) * (1 - 0.4 * tt);
    fill(255, 244, 214, a);
    ellipse(x, y, r, r);
    if (r > 3.6) {
      fill(255, 244, 214, a * 0.18);
      ellipse(x, y, r * 4, r * 4);
    }
  }

  // ---------- baseboard ----------
  noStroke();
  fill(38, 32, 30, 220);
  rect(0, horizon - 26, W, 26);
  fill(96, 86, 76, 90);
  rect(0, horizon - 28, W, 5);

  // ---------- picture hook / empty nail shadow on wall (a faint pale rectangle) ----------
  push();
  noStroke();
  fill(255, 245, 225, 16);
  rect(W * 0.80, H * 0.18, W * 0.13, H * 0.17);
  fill(0, 0, 0, 18);
  rect(W * 0.80 + 6, H * 0.18 + 8, W * 0.13, H * 0.17);
  pop();

  // ---------- overall grain / glaze ----------
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(W), y = random(H);
    fill(180, 170, 160, 10);
    ellipse(x, y, random(2, 40), random(2, 40));
  }
  pop();

  // canvas tooth
  loadPixels();
  for (let y = 0; y < H; y += 1) {
    for (let x = 0; x < W; x += 1) {
      let idx = 4 * (y * W + x);
      let n = (noise(x * 0.9, y * 0.9) - 0.5) * 16;
      pixels[idx] += n;
      pixels[idx + 1] += n;
      pixels[idx + 2] += n;
    }
  }
  updatePixels();

  // vignette
  push();
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(14, 10, 12, 4);
    strokeWeight(6);
    rect(-i * 2.6, -i * 2.6, W + i * 5.2, H + i * 5.2);
  }
  pop();
}

