function drawWindow(x, y, w, h) {
  // recess shadow
  noStroke();
  fill(26, 22, 22, 160);
  rect(x - 26, y - 26, w + 52, h + 52);

  // glowing sky (overexposed, no detail — just light)
  for (let i = 0; i < h; i++) {
    let t = i / h;
    let c = lerpColor(color(255, 252, 240), color(236, 214, 170), pow(t, 0.8));
    stroke(c);
    line(x, y + i, x + w, y + i);
  }

  // faint far trees as pale washes
  noStroke();
  for (let i = 0; i < 40; i++) {
    let bx = x + random(w);
    let by = y + h * random(0.55, 0.78);
    fill(228, 220, 196, random(20, 55));
    ellipse(bx, by, random(60, 220), random(40, 120));
  }
  fill(232, 224, 200, 70);
  rect(x, y + h * 0.74, w, h * 0.26);

  // bloom spilling past frame
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 70; i++) {
    fill(255, 246, 220, 5);
    rect(x - i * 3, y - i * 3, w + i * 6, h + i * 6, 20);
  }
  pop();

  // mullions
  stroke(36, 30, 28);
  strokeWeight(16);
  noFill();
  rect(x, y, w, h);
  strokeWeight(11);
  line(x + w / 2, y, x + w / 2, y + h);
  line(x, y + h * 0.46, x + w, y + h * 0.46);

  // sill
  noStroke();
  fill(70, 60, 52);
  rect(x - 34, y + h + 4, w + 68, 26);
  fill(150, 136, 114, 150);
  rect(x - 34, y + h + 2, w + 68, 7);
}

