function drawChair(cx, cy, s) {
  push();
  translate(cx, cy);
  scale(s);

  const seatW = 300, seatD = 150, legH = 240, backH = 420;

  // --- long cast shadow (away from window, to the right/front) ---
  push();
  noStroke();
  for (let i = 0; i < 28; i++) {
    fill(18, 12, 12, 10);
    beginShape();
    vertex(-seatW * 0.5 + i, seatD * 0.15 + legH);
    vertex(seatW * 0.5 - i, seatD * 0.1 + legH);
    vertex(seatW * 1.55 + i * 6, legH + 520 + i * 6);
    vertex(seatW * 0.45 + i * 5, legH + 580 + i * 6);
    endShape(CLOSE);
  }
  // shadow of backrest stretched
  for (let i = 0; i < 20; i++) {
    fill(18, 12, 12, 9);
    beginShape();
    vertex(-seatW * 0.45, legH + 10);
    vertex(-seatW * 0.1, legH + 6);
    vertex(seatW * 0.95 + i * 7, legH + 430 + i * 8);
    vertex(seatW * 0.45 + i * 7, legH + 455 + i * 8);
    endShape(CLOSE);
  }
  pop();

  const woodD = color(44, 30, 24);
  const woodM = color(86, 58, 40);
  const woodL = color(168, 126, 86);

  // --- legs ---
  // back legs continue into backrest posts
  drawPost(-seatW * 0.44, -backH, -seatW * 0.40, legH, 20, woodD, woodM, woodL, 0.55);
  drawPost(seatW * 0.40, -backH + 8, seatW * 0.46, legH, 20, woodD, woodM, woodL, 0.3);
  // front legs
  drawPost(-seatW * 0.30, 40, -seatW * 0.36, legH + 60, 22, woodD, woodM, woodL, 0.85);
  drawPost(seatW * 0.34, 44, seatW * 0.42, legH + 64, 22, woodD, woodM, woodL, 0.5);

  // --- stretchers ---
  strokeCap(ROUND);
  stroke(woodM); strokeWeight(13);
  line(-seatW * 0.335, legH * 0.62, seatW * 0.38, legH * 0.64);
  stroke(lerpColor(woodM, woodL, 0.45)); strokeWeight(5);
  line(-seatW * 0.335, legH * 0.62 - 4, seatW * 0.38, legH * 0.64 - 4);

  // --- backrest slats ---
  for (let i = 0; i < 3; i++) {
    let yy = -backH + 70 + i * 92;
    noStroke();
    fill(lerpColor(woodD, woodM, 0.75));
    rect(-seatW * 0.44, yy, seatW * 0.86, 40, 8);
    fill(lerpColor(woodM, woodL, 0.55 - i * 0.08));
    rect(-seatW * 0.44, yy + 2, seatW * 0.86, 12, 6);
    fill(24, 16, 12, 90);
    rect(-seatW * 0.44, yy + 32, seatW * 0.86, 8, 4);
  }
  // top rail
  noStroke();
  fill(lerpColor(woodD, woodM, 0.9));
  rect(-seatW * 0.49, -backH - 34, seatW * 0.96, 48, 14);
  fill(lerpColor(woodM, woodL, 0.8));
  rect(-seatW * 0.49, -backH - 32, seatW * 0.96, 16, 10);
  fill(20, 14, 10, 110);
  rect(-seatW * 0.49, -backH + 4, seatW * 0.96, 10, 5);

  // --- seat (slight perspective) ---
  noStroke();
  fill(lerpColor(woodD, woodM, 0.6));
  beginShape();
  vertex(-seatW * 0.47, 0);
  vertex(seatW * 0.44, 4);
  vertex(seatW * 0.54, seatD * 0.62);
  vertex(-seatW * 0.57, seatD * 0.58);
  endShape(CLOSE);
  // lit top
  fill(lerpColor(woodM, woodL, 0.6));
  beginShape();
  vertex(-seatW * 0.47, 0);
  vertex(seatW * 0.44, 4);
  vertex(seatW * 0.50, seatD * 0.34);
  vertex(-seatW * 0.53, seatD * 0.30);
  endShape(CLOSE);
  // front edge shadow
  fill(26, 18, 14, 150);
  beginShape();
  vertex(-seatW * 0.57, seatD * 0.58);
  vertex(seatW * 0.54, seatD * 0.62);
  vertex(seatW * 0.52, seatD * 0.78);
  vertex(-seatW * 0.56, seatD * 0.74);
  endShape(CLOSE);

  // --- cushion: a worn hollow, still holding a shape ---
  push();
  noStroke();
  // cushion body
  fill(96, 72, 78);
  ellipse(-6, seatD * 0.17, seatW * 0.92, seatD * 0.60);
  fill(120, 92, 96);
  ellipse(-10, seatD * 0.12, seatW * 0.84, seatD * 0.50);
  // the depression
  fill(74, 54, 60, 220);
  ellipse(-4, seatD * 0.19, seatW * 0.52, seatD * 0.30);
  fill(58, 42, 48, 170);
  ellipse(-2, seatD * 0.21, seatW * 0.36, seatD * 0.20);
  // highlight rim from window side (left)
  fill(196, 164, 148, 120);
  arc(-10, seatD * 0.12, seatW * 0.84, seatD * 0.50, PI * 0.72, PI * 1.42);
  pop();

  // worn edges / nicks
  stroke(222, 196, 158, 70);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 26; i++) {
    let yy = -backH + random(0, backH + legH);
    let xx = random(-seatW * 0.5, seatW * 0.5);
    line(xx, yy, xx + random(-14, 14), yy + random(-6, 6));
  }

  pop();
}

function drawPost(x1, y1, x2, y2, w, cd, cm, cl, lit) {
  push();
  noStroke();
  // body
  fill(cd);
  quad(x1 - w / 2, y1, x1 + w / 2, y1, x2 + w / 2, y2, x2 - w / 2, y2);
  fill(cm);
  quad(x1 - w / 2 + 2, y1, x1 + w / 2 - 3, y1, x2 + w / 2 - 3, y2, x2 - w / 2 + 2, y2);
  // lit edge
  fill(lerpColor(cm, cl, lit));
  quad(x1 - w / 2 + 2, y1, x1 - w / 2 + 8, y1, x2 - w / 2 + 8, y2, x2 - w / 2 + 2, y2);
  pop();
}

let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  colorMode(RGB, 255);
}

function draw() {
  background(6, 8, 14);

  // ---------- deep water gradient ----------
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let r = lerp(10, 3, t) + 14 * Math.pow(1 - t, 3);
    let g = lerp(16, 5, t) + 16 * Math.pow(1 - t, 3);
    let b = lerp(28, 11, t) + 24 * Math.pow(1 - t, 3);
    stroke(r, g, b);
    line(0, y, W, y);
  }

  // ---------- horizon glow (cold dawn) ----------
  let hy = H * 0.30;
  noStroke();
  for (let i = 0; i < 260; i++) {
    let t = i / 260;
    let a = 26 * (1 - t) * (1 - t);
    fill(90, 130, 150, a);
    ellipse(W * 0.5, hy, W * (0.5 + t * 1.6), 420 * (0.1 + t * 1.5));
  }
  // horizon line haze
  for (let i = 0; i < 120; i++) {
    let t = i / 120;
    fill(140, 180, 195, 14 * (1 - t));
    rect(0, hy - t * 90, W, 2);
    fill(120, 160, 180, 10 * (1 - t));
    rect(0, hy + t * 130, W, 2);
  }

  // ---------- distant soft bands (sky strata) ----------
  for (let i = 0; i < 60; i++) {
    let y = random(0, hy - 40);
    let h = random(4, 26);
    let a = map(y, 0, hy, 4, 16);
    fill(60 + random(30), 80 + random(30), 100 + random(30), a);
    rect(0, y, W, h);
  }

  // ---------- water surface: concentric rings ----------
  let cx = W * 0.5, cy = H * 0.63;

  push();
  translate(cx, cy);
  noFill();
  for (let i = 0; i < 70; i++) {
    let rr = 20 + Math.pow(i / 70, 1.5) * 1500;
    let fade = 1 - i / 70;
    let alpha = 9 + 70 * Math.pow(fade, 2.0);
    // squash into perspective ellipse
    for (let pass = 0; pass < 2; pass++) {
      stroke(150 + 50 * fade, 190 + 40 * fade, 205, alpha * (pass === 0 ? 1 : 0.35));
      strokeWeight(pass === 0 ? 1.2 + 2.2 * fade : 5 + 7 * fade);
      beginShape();
      for (let a = 0; a <= TWO_PI + 0.05; a += 0.04) {
        let n = noise(cos(a) * 0.9 + 10, sin(a) * 0.9 + 10, i * 0.09);
        let wob = (n - 0.5) * (18 + rr * 0.05);
        let x = cos(a) * (rr + wob);
        let y = sin(a) * (rr + wob) * 0.30;
        vertex(x, y);
      }
      endShape();
    }
  }
  pop();

  // ---------- horizontal ripple streaks on water ----------
  for (let i = 0; i < 900; i++) {
    let y = random(hy + 10, H);
    let depth = (y - hy) / (H - hy);
    let len = random(20, 300) * (0.3 + depth);
    let x = random(-100, W);
    let a = 8 + 26 * noise(x * 0.004, y * 0.01) * (1 - depth * 0.5);
    stroke(140, 180, 200, a);
    strokeWeight(random(0.6, 2.2));
    line(x, y, x + len, y + random(-1, 1));
  }

  // ---------- the vanishing center: dissolving light ----------
  // soft core glow
  noStroke();
  for (let i = 0; i < 160; i++) {
    let t = i / 160;
    fill(170, 210, 225, 20 * (1 - t) * (1 - t));
    ellipse(cx, cy, 40 + t * 900, (40 + t * 900) * 0.32);
  }

  // ---------- ascending motes (light leaving the body) ----------
  for (let i = 0; i < 1400; i++) {
    let a = random(TWO_PI);
    let r = Math.pow(random(), 2.2) * 520;
    let px = cx + cos(a) * r;
    let rise = Math.pow(random(), 1.8);
    let py = cy + sin(a) * r * 0.30 - rise * 1150;
    let s = random(1, 4.2) * (1 - rise * 0.6);
    let alpha = (200 - rise * 170) * random(0.3, 1);
    // drift
    px += (noise(i * 0.05, rise * 2) - 0.5) * 260 * rise;
    noStroke();
    fill(200, 225, 235, alpha * 0.25);
    ellipse(px, py, s * 4, s * 4);
    fill(225, 240, 248, alpha);
    ellipse(px, py, s, s);
  }

  // ---------- faint reflected column on water ----------
  for (let i = 0; i < 400; i++) {
    let y = random(cy - 40, H);
    let d = (y - cy) / (H - cy);
    let w = 60 + d * 320;
    let x = cx + random(-w, w) + (noise(y * 0.01) - 0.5) * 120;
    stroke(190, 220, 230, 30 * (1 - d) * random(0.2, 1));
    strokeWeight(random(0.8, 3));
    line(x, y, x + random(10, 90), y);
  }

  // ---------- drifting dark shapes (lost things) ----------
  noStroke();
  for (let i = 0; i < 9; i++) {
    let x = random(W * 0.08, W * 0.92);
    let y = random(cy + 120, H - 80);
    let d = (y - cy) / (H - cy);
    let w = (40 + random(140)) * (0.5 + d);
    fill(2, 4, 8, 150);
    ellipse(x, y, w, w * 0.18);
    fill(170, 200, 215, 26);
    ellipse(x, y - w * 0.05, w * 0.9, w * 0.08);
  }

  // ---------- upper darkness veil ----------
  for (let y = 0; y < hy * 0.7; y++) {
    let t = 1 - y / (hy * 0.7);
    noStroke();
    fill(2, 3, 7, 120 * t * t);
    rect(0, y, W, 1);
  }

  // ---------- vignette ----------
  for (let i = 0; i < 300; i++) {
    let t = i / 300;
    noFill();
    stroke(1, 2, 5, 2.2 * t * t * 255 / 255 * 3);
    strokeWeight(14);
    ellipse(W / 2, H / 2, W * (1.9 - t * 1.0), H * (1.9 - t * 1.0));
  }

  // ---------- grain ----------
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (Math.random() - 0.5) * 13;
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();
}

// The Lender — a still painting
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
  draw_painting();
}

function draw_painting() {
  background(10, 12, 18);

  // ---------- COLD SKY / VOID GRADIENT ----------
  loadPixels();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    // deep slate-blue above, colder ink below
    let r = lerp(26, 8, t) + 14 * Math.pow(1 - t, 2.2);
    let g = lerp(34, 11, t) + 16 * Math.pow(1 - t, 2.2);
    let b = lerp(52, 20, t) + 20 * Math.pow(1 - t, 2.2);
    for (let x = 0; x < W; x++) {
      // subtle horizontal vignette baked into gradient
      let dx = (x - W / 2) / (W / 2);
      let v = 1 - 0.28 * dx * dx;
      let i = 4 * (y * W + x);
      pixels[i] = r * v;
      pixels[i + 1] = g * v;
      pixels[i + 2] = b * v;
      pixels[i + 3] = 255;
    }
  }
  updatePixels();

  // ---------- FAR ATMOSPHERE: slow cloud of cold dust ----------
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.0013, y * 0.0013);
    let a = map(n, 0.3, 0.75, 0, 20, true);
    fill(70, 90, 125, a);
    ellipse(x, y, random(60, 260), random(60, 260));
  }

  // ---------- THE COLUMN OF LIGHT (the borrowed life) ----------
  const cx = W * 0.5;
  const baseY = H * 0.93;
  const openY = H * 0.30;   // where the column opens
  const topY = -200;

  // outer bloom halo behind the column
  for (let i = 0; i < 70; i++) {
    let k = i / 70;
    let w = lerp(760, 120, k);
    fill(120, 150, 200, 3.0);
    rectMode(CENTER);
    rect(cx, (baseY + openY) / 2, w, baseY - openY + 300, w * 0.5);
  }

  // the column body: many vertical filaments
  drawColumn(cx, baseY, openY);

  // ---------- THE OPENING: light leaving ----------
  drawRelease(cx, openY, topY);

  // ---------- GROUND: cold plane ----------
  drawGround(baseY);

  // ---------- THE WITNESSES: small dark forms ----------
  drawWitnesses(baseY);

  // ---------- EMBERS / MOTES drifting up ----------
  drawMotes(cx, baseY, openY);

  // ---------- FINAL ATMOSPHERE ----------
  grainAndVignette();
}

// ------------------------------------------------------------------
function drawColumn(cx, baseY, openY) {
  noStroke();

  // soft core glow
  for (let i = 0; i < 180; i++) {
    let k = i / 180;
    let y0 = lerp(baseY, openY - 120, 0);
    let w = lerp(300, 30, k);
    fill(255, 236, 206, 2.6);
    rectMode(CENTER);
    rect(cx, (baseY + openY - 120) / 2, w, baseY - openY + 160, w * 0.5);
  }

  // filaments
  for (let f = 0; f < 420; f++) {
    let off = randomGaussian() * 95;
    let xBase = cx + off;
    let life = map(abs(off), 0, 170, 1, 0.25, true);
    if (life <= 0.05) continue;

    // warmth of the filament
    let warm = map(abs(off), 0, 170, 1, 0.2, true);
    let topLimit = lerp(baseY - 100, openY - 60, pow(life, 0.55));

    let w = random(0.7, 3.4);
    let a = random(8, 42) * life;
    let seed = random(1000);

    beginShape();
    noFill();
    stroke(
      lerp(170, 255, warm),
      lerp(150, 232, warm),
      lerp(140, 190, warm),
      a
    );
    strokeWeight(w);
    for (let y = baseY + 10; y > topLimit; y -= 9) {
      let t = (baseY - y) / (baseY - openY);
      let wob = (noise(seed, y * 0.0022) - 0.5) * lerp(8, 70, t);
      vertex(xBase + wob, y);
    }
    endShape();
  }

  // very bright inner spine
  for (let f = 0; f < 90; f++) {
    let off = randomGaussian() * 22;
    let seed = random(1000);
    noFill();
    stroke(255, 250, 232, random(20, 70));
    strokeWeight(random(0.6, 2.2));
    beginShape();
    for (let y = baseY + 10; y > openY - 40; y -= 10) {
      let t = (baseY - y) / (baseY - openY);
      let wob = (noise(seed, y * 0.0025) - 0.5) * lerp(5, 40, t);
      vertex(cx + off + wob, y);
    }
    endShape();
  }
  noStroke();
}

// ------------------------------------------------------------------
function drawRelease(cx, openY, topY) {
  // The column opens: a flaring mouth of light that disperses upward
  noStroke();

  // halo burst at the opening
  for (let i = 0; i < 120; i++) {
    let k = i / 120;
    let d = lerp(40, 900, pow(k, 1.6));
    fill(255, 224, 186, map(k, 0, 1, 10, 0.6));
    ellipse(cx, openY, d, d * 0.72);
  }
  for (let i = 0; i < 60; i++) {
    let k = i / 60;
    let d = lerp(10, 260, pow(k, 1.4));
    fill(255, 248, 230, map(k, 0, 1, 16, 1));
    ellipse(cx, openY, d, d * 0.85);
  }

  // dispersing strands: they arc outward and fade into sky
  for (let s = 0; s < 520; s++) {
    let a0 = random(-PI, 0); // upward hemisphere
    let spread = random(0.25, 1.0);
    let len = random(180, 1150) * spread;
    let seed = random(1000);
    let warmFade = random(0.4, 1);

    noFill();
    let steps = 46;
    beginShape();
    for (let i = 0; i < steps; i++) {
      let t = i / (steps - 1);
      // path: mostly upward, bending outward
      let r = len * t;
      let ang = a0 + (noise(seed, t * 1.6) - 0.5) * 1.1;
      let x = cx + cos(ang) * r * 0.85;
      let y = openY + sin(ang) * r * 1.25;
      // fade color from warm to cold-blue as it leaves
      let c1 = color(255, 230, 190);
      let c2 = color(120, 160, 215);
      let col = lerpColor(c1, c2, constrain(t * 1.25, 0, 1));
      col.setAlpha(map(t, 0, 1, 34 * warmFade, 0));
      stroke(col);
      strokeWeight(lerp(2.6, 0.5, t));
      if (i > 0) {
        line(px, py, x, y);
      }
      var px = x, py = y;
    }
    endShape();
  }

  noStroke();
}

// ------------------------------------------------------------------
function drawGround(baseY) {
  noStroke();

  // the plane
  for (let y = baseY - 60; y < H; y++) {
    let t = (y - (baseY - 60)) / (H - baseY + 60);
    let a = map(t, 0, 1, 0, 255);
    fill(9, 11, 16, a);
    rect(0, y, W, 1.4);
  }

  // reflection / pool of light on the ground
  for (let i = 0; i < 160; i++) {
    let k = i / 160;
    let w = lerp(900, 80, k);
    let h = lerp(230, 16, k);
    fill(255, 222, 180, 2.4);
    ellipse(W / 2, baseY + 36, w, h);
  }

  // faint cracks radiating outward
  stroke(200, 190, 170, 10);
  strokeWeight(1.2);
  for (let i = 0; i < 26; i++) {
    let ang = random(PI * 0.08, PI * 0.92);
    let x = W / 2, y = baseY + 40;
    let len = random(80, 620);
    let steps = 24;
    beginShape();
    noFill();
    for (let j = 0; j < steps; j++) {
      let t = j / (steps - 1);
      let r = len * t;
      let a2 = ang + (noise(i * 10, t * 2) - 0.5) * 0.5;
      vertex(x + cos(a2) * r, y + sin(a2) * r * 0.22);
    }
    endShape();
  }
  noStroke();
}

// ------------------------------------------------------------------
function drawWitnesses(baseY) {
  // small dark standing forms, far away, facing the light
  let positions = [
    [360, 0.95, 1.0],
    [430, 0.90, 0.85],
    [1230, 0.97, 1.05],
    [1160, 0.92, 0.8],
    [1310, 0.88, 0.72],
    [270, 0.86, 0.68]
  ];
  for (let p of positions) {
    let x = p[0];
    let s = p[2];
    let y = baseY + (1 - p[1]) * 90;
    drawFigure(x, y, s);
  }
}

function drawFigure(x, baseY, s) {
  noStroke();
  let h = 190 * s;
  let w = 42 * s;

  // soft shadow on ground
  fill(5, 6, 9, 150);
  ellipse(x, baseY + 4, w * 2.6, 16 * s);

  // body: slight silhouette, rim-lit on side facing center
  let facing = (x < W / 2) ? 1 : -1;

  // main mass
  fill(6, 7, 11, 240);
  beginShape();
  vertex(x - w * 0.5, baseY);
  bezierVertex(x - w * 0.62, baseY - h * 0.45, x - w * 0.55, baseY - h * 0.7, x - w * 0.30, baseY - h * 0.78);
  bezierVertex(x - w * 0.34, baseY - h * 0.95, x + w * 0.34, baseY - h * 0.95, x + w * 0.30, baseY - h * 0.78);
  bezierVertex(x + w * 0.55, baseY - h * 0.7, x + w * 0.62, baseY - h * 0.45, x + w * 0.5, baseY);
  endShape(CLOSE);

  // head
  fill(6, 7, 11, 240);
  ellipse(x, baseY - h * 0.88, w * 0.52, w * 0.60);

  // rim light
  for (let i = 0; i < 24; i++) {
    stroke(255, 216, 170, 7);
    strokeWeight(1.6);
    noFill();
    let o = facing * (w * 0.46 + i * 0.25);
    beginShape();
    vertex(x + o, baseY);
    bezierVertex(
      x + o * 1.18, baseY - h * 0.45,
      x + o * 1.05, baseY - h * 0.7,
      x + facing * w * 0.26, baseY - h * 0.80
    );
    endShape();
  }
  noStroke();
  fill(255, 220, 175, 26);
  ellipse(x + facing * w * 0.22, baseY - h * 0.88, w * 0.18, w * 0.42);
}

// ------------------------------------------------------------------
function drawMotes(cx, baseY, openY) {
  noStroke();
  for (let i = 0; i < 900; i++) {
    let t = pow(random(), 0.6);
    let y = lerp(baseY + 30, -80, t);
    let spread = lerp(180, 760, pow(t, 1.3));
    let x = cx + randomGaussian() * spread * 0.45;
    if (x < -50 || x > W + 50) continue;

    let sz = random(1.2, 4.6) * (1 - t * 0.5);
    let warm = constrain(1 - t * 1.4, 0, 1);
    let a = random(20, 110) * (1 - t * 0.55);

    fill(
      lerp(150, 255, warm),
      lerp(180, 226, warm),
      lerp(225, 180, warm),
      a
    );
    ellipse(x, y, sz, sz);

    if (random() < 0.12) {
      fill(255, 240, 215, a * 0.25);
      ellipse(x, y, sz * 6, sz * 6);
    }
  }
}

// ------------------------------------------------------------------
function grainAndVignette() {
  // vignette
  noFill();
  for (let i = 0; i < 300; i++) {
    let k = i / 300;
    stroke(4, 5, 9, 2.2);
    strokeWeight(14);
    let inset = -260 + k * 760;
    rect(inset, inset * 1.0, W - inset * 2, H - inset * 2);
  }
  noStroke();

  // grain
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 13;
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

function draw() {}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  noStroke();

  // ---------- SKY ----------
  const horizon = 1180;
  for (let y = 0; y < horizon; y++) {
    const t = y / horizon;
    // deep indigo top -> smoky violet -> bruised amber near horizon
    let c;
    if (t < 0.55) {
      c = lerpColor(color(8, 10, 22), color(28, 26, 48), t / 0.55);
    } else if (t < 0.85) {
      c = lerpColor(color(28, 26, 48), color(72, 52, 66), (t - 0.55) / 0.30);
    } else {
      c = lerpColor(color(72, 52, 66), color(132, 96, 78), (t - 0.85) / 0.15);
    }
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();

  // soft clouds / haze bands
  for (let i = 0; i < 160; i++) {
    const y = random(120, horizon - 20);
    const h = random(10, 70);
    const x = random(-300, width + 300);
    const w = random(300, 1300);
    const t = (y / horizon);
    const a = map(t, 0, 1, 4, 14) * random(0.4, 1.3);
    fill(lerpColor(color(60, 60, 90), color(160, 120, 100), t), a);
    ellipse(x, y, w, h);
  }

  // faint stars in upper sky
  for (let i = 0; i < 260; i++) {
    const x = random(width);
    const y = random(0, horizon * 0.62);
    const a = map(y, 0, horizon * 0.62, 180, 10) * random(0.3, 1);
    const r = random(0.8, 2.4);
    fill(225, 228, 245, a);
    ellipse(x, y, r, r);
  }

  // ---------- DISTANT SHORE / TREE LINE ----------
  // far bank haze
  fill(46, 44, 60, 200);
  beginShape();
  vertex(0, horizon);
  for (let x = 0; x <= width; x += 8) {
    const n = noise(x * 0.0018, 10) * 46 + noise(x * 0.008, 30) * 12;
    vertex(x, horizon - 34 - n);
  }
  vertex(width, horizon);
  endShape(CLOSE);

  // silhouetted trees on far bank
  drawTreeLine(horizon - 30, 0.0, color(24, 24, 36, 235), 1.0);
  drawTreeLine(horizon - 16, 7.3, color(14, 14, 22, 250), 0.72);

  // far bank edge
  fill(10, 10, 16);
  rect(0, horizon - 6, width, 12);

  // ---------- WATER ----------
  for (let y = horizon; y < height; y++) {
    const t = (y - horizon) / (height - horizon);
    let c;
    if (t < 0.4) {
      c = lerpColor(color(40, 42, 58), color(22, 26, 40), t / 0.4);
    } else {
      c = lerpColor(color(22, 26, 40), color(7, 8, 14), (t - 0.4) / 0.6);
    }
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();

  // ---------- MOON GLOW (low, behind mist) ----------
  const mx = 1130, my = horizon - 250;
  for (let r = 460; r > 0; r -= 6) {
    const a = map(r, 0, 460, 26, 0);
    fill(220, 180, 140, a);
    ellipse(mx, my, r * 2.1, r * 2.1);
  }
  fill(232, 206, 176, 210);
  ellipse(mx, my, 118, 118);
  fill(244, 226, 200, 120);
  ellipse(mx, my, 86, 86);

  // moon reflection column on water
  for (let i = 0; i < 280; i++) {
    const y = random(horizon + 4, height);
    const t = (y - horizon) / (height - horizon);
    const spread = 40 + t * 420;
    const x = mx + randomGaussian() * spread * 0.45;
    const w = random(20, 150) * (0.4 + t);
    const h = random(1.2, 3.4);
    const a = map(t, 0, 1, 95, 8) * random(0.3, 1.1);
    fill(226, 196, 162, a);
    rect(x - w / 2, y, w, h);
  }

  // ---------- MIST OVER WATER ----------
  for (let i = 0; i < 90; i++) {
    const y = random(horizon - 24, horizon + 150);
    const x = random(-200, width + 200);
    fill(170, 170, 190, random(3, 11));
    ellipse(x, y, random(500, 1500), random(16, 60));
  }

  // ---------- THE BOAT ----------
  push();
  translate(620, 1560);
  rotate(-0.025);
  drawBoat();
  pop();

  // ---------- REFLECTION OF BOAT ----------
  push();
  translate(620, 1660);
  scale(1, -0.55);
  rotate(0.03);
  drawBoatReflection();
  pop();

  // ripples around boat
  noFill();
  for (let i = 0; i < 26; i++) {
    const rr = 60 + i * 42 + noise(i * 0.4) * 30;
    stroke(190, 200, 215, map(i, 0, 26, 42, 2));
    strokeWeight(random(0.8, 2.0));
    ellipse(620 + random(-14, 14), 1620 + i * 6, rr * 3.0, rr * 0.42);
  }
  noStroke();

  // ---------- FOREGROUND WATER STROKES ----------
  for (let i = 0; i < 900; i++) {
    const y = random(horizon + 30, height);
    const t = (y - horizon) / (height - horizon);
    const x = random(-60, width + 60);
    const w = random(30, 300) * (0.3 + t * 1.3);
    const h = random(0.8, 2.6 + t * 2.5);
    const a = random(4, 26) * (0.4 + t * 0.6);
    const warm = constrain(1 - abs(x - mx) / 700, 0, 1);
    fill(lerpColor(color(120, 132, 155), color(206, 172, 138), warm * 0.7), a);
    rect(x, y, w, h);
  }

  // darker foreground ripples
  for (let i = 0; i < 420; i++) {
    const y = random(1700, height);
    const x = random(-60, width + 60);
    fill(4, 5, 10, random(10, 48));
    rect(x, y, random(60, 420), random(1.5, 5));
  }

  // ---------- EMBERS / DRIFTING LIGHT ----------
  for (let i = 0; i < 90; i++) {
    const x = random(340, 1200);
    const y = random(900, 1560);
    const d = random(1.5, 4.5);
    const a = random(30, 170) * map(y, 900, 1560, 0.4, 1);
    fill(255, 196, 120, a);
    ellipse(x, y, d, d);
    fill(255, 170, 90, a * 0.22);
    ellipse(x, y, d * 5, d * 5);
  }

  // ---------- VIGNETTE ----------
  for (let r = 0; r < 760; r += 4) {
    const a = map(r, 0, 760, 0, 92);
    fill(0, 0, 4, a * 0.07);
    noStroke();
    // draw as expanding frame
    rect(0, 0, width, r * 0.5);
    rect(0, height - r * 0.5, width, r * 0.5);
    rect(0, 0, r * 0.42, height);
    rect(width - r * 0.42, 0, r * 0.42, height);
  }

  // final grain
  for (let i = 0; i < 26000; i++) {
    const x = random(width), y = random(height);
    fill(random(255), random(6, 16));
    rect(x, y, 1.4, 1.4);
  }
}

function drawTreeLine(baseY, seedOff, col, scaleF) {
  fill(col);
  noStroke();
  for (let x = -40; x < width + 40; x += 14) {
    const n = noise(x * 0.004 + seedOff, 5);
    const h = (30 + n * 150) * scaleF;
    const w = (14 + n * 26) * scaleF;
    // conifer-ish silhouette
    beginShape();
    vertex(x, baseY + 10);
    vertex(x - w * 0.5, baseY + 6);
    for (let k = 0; k < 5; k++) {
      const f = k / 5;
      vertex(x - w * 0.5 * (1 - f), baseY - h * f);
      vertex(x - w * 0.34 * (1 - f), baseY - h * (f + 0.08));
    }
    vertex(x, baseY - h);
    for (let k = 4; k >= 0; k--) {
      const f = k / 5;
      vertex(x + w * 0.34 * (1 - f), baseY - h * (f + 0.08));
      vertex(x + w * 0.5 * (1 - f), baseY - h * f);
    }
    vertex(x + w * 0.5, baseY + 6);
    endShape(CLOSE);
  }
}

function drawBoat() {
  // hull: a long narrow punt seen in near-profile
  const L = 760;     // length
  const H = 86;      // hull height

  // hull shadow in water
  noStroke();
  fill(0, 0, 0, 110);
  beginShape();
  vertex(-L / 2 - 20, 10);
  bezierVertex(-L / 4, 48, L / 4, 52, L / 2 + 20, 8);
  bezierVertex(L / 4, 70, -L / 4, 72, -L / 2 - 20, 10);
  endShape(CLOSE);

  // outer hull
  fill(16, 14, 16);
  beginShape();
  vertex(-L / 2, -18);
  bezierVertex(-L * 0.30, 6, L * 0.30, 8, L / 2, -26);
  bezierVertex(L * 0.34, H * 0.62, -L * 0.34, H * 0.60, -L / 2, -18);
