  // hull highlight (top edge, catching moonlight)
  stroke(146, 128, 112, 190);
  strokeWeight(3.2);
  noFill();
  beginShape();
  vertex(-L / 2, -18);
  bezierVertex(-L * 0.30, 6, L * 0.30, 8, L / 2, -26);
  endShape();

  // inner gunwale shadow line
  stroke(60, 52, 48, 150);
  strokeWeight(2);
  beginShape();
  vertex(-L / 2 + 16, -10);
  bezierVertex(-L * 0.28, 16, L * 0.28, 18, L / 2 - 16, -18);
  endShape();
  noStroke();

  // plank texture on hull
  for (let i = 0; i < 7; i++) {
    const yy = 6 + i * 9;
    stroke(42, 36, 34, 90 - i * 8);
    strokeWeight(1.6);
    noFill();
    beginShape();
    vertex(-L / 2 + 26 + i * 4, -14 + yy * 0.55);
    bezierVertex(-L * 0.26, 10 + yy, L * 0.26, 12 + yy, L / 2 - 26 - i * 4, -22 + yy * 0.55);
    endShape();
  }
  noStroke();

  // interior (visible dark trough)
  fill(9, 8, 11);
  beginShape();
  vertex(-L / 2 + 26, -14);
  bezierVertex(-L * 0.26, 4, L * 0.26, 6, L / 2 - 26, -22);
  bezierVertex(L * 0.26, 24, -L * 0.26, 22, -L / 2 + 26, -14);
  endShape(CLOSE);

  // the empty seat / thwart
  push();
  translate(70, -6);
  rotate(0.02);
  fill(52, 44, 40);
  rect(-96, -4, 192, 13, 3);
  fill(96, 84, 74, 200);
  rect(-96, -5, 192, 4, 2);
  fill(16, 14, 14, 180);
  rect(-96, 7, 192, 5, 2);
  pop();

  // a second thwart, nearer stern
  push();
  translate(-190, 2);
  fill(44, 38, 35);
  rect(-78, -3, 156, 11, 3);
  fill(84, 74, 66, 150);
  rect(-78, -4, 156, 3.5, 2);
  pop();

  // folded cloth left on the seat (the only trace)
  push();
  translate(96, -14);
  fill(118, 110, 104, 210);
  beginShape();
  vertex(-62, 0);
  bezierVertex(-40, -22, 10, -26, 48, -8);
  bezierVertex(54, 2, 20, 10, -14, 8);
  bezierVertex(-36, 8, -52, 8, -62, 0);
  endShape(CLOSE);
  fill(168, 160, 152, 150);
  beginShape();
  vertex(-50, -3);
  bezierVertex(-30, -18, 6, -20, 34, -8);
  bezierVertex(10, -4, -22, -2, -50, -3);
  endShape(CLOSE);
  fill(50, 46, 46, 160);
  ellipse(-6, 7, 100, 10);
  pop();

  // pole leaning in the boat (no ferryman holding it)
  stroke(104, 90, 76, 230);
  strokeWeight(8);
  line(-300, -40, 250, -300);
  stroke(58, 50, 42, 200);
  strokeWeight(3);
  line(-300, -36, 250, -296);
  noStroke();

  // lantern hanging at the bow
  push();
  translate(300, -96);
  // hook arm
  stroke(70, 62, 54);
  strokeWeight(6);
  noFill();
  beginShape();
  vertex(10, 88);
  bezierVertex(26, 40, 30, 10, 6, -6);
  endShape();
  noStroke();

  // glow
  for (let r = 240; r > 0; r -= 5) {
    fill(255, 186, 104, map(r, 0, 240, 16, 0));
    ellipse(0, 24, r * 2, r * 2);
  }
  // lantern body
  fill(30, 26, 24);
  rect(-24, 0, 48, 52, 3);
  fill(255, 206, 128, 235);
  rect(-17, 6, 34, 40, 2);
  fill(255, 240, 200, 250);
  ellipse(0, 26, 16, 26);
  fill(28, 24, 22);
  rect(-28, -8, 56, 10, 2);
  rect(-28, 50, 56, 9, 2);
  // bars
  fill(22, 18, 16, 220);
  rect(-2, 4, 4, 44);
  pop();

  // small bow rope trailing into water
  stroke(120, 110, 98, 160);
  strokeWeight(3);
  noFill();
  beginShape();
  vertex(360, -16);
  bezierVertex(420, 30, 430, 70, 392, 98);
  endShape();
  noStroke();
}

function drawBoatReflection() {
  const L = 760, H = 86;
  // blurred, broken reflection: draw in bands with gaps
  for (let i = 0; i < 22; i++) {
    const y = i * 7;
    if (random() < 0.3) continue;
    fill(14, 14, 20, map(i, 0, 22, 120, 6));
    const wobble = sin(i * 0.9) * 16 + random(-10, 10);
    const w = L * (1 - i * 0.012);
    rect(-w / 2 + wobble, y - 24, w, 5.2);
  }
  // lantern reflection
  for (let i = 0; i < 30; i++) {
    const y = i * 9;
    fill(255, 180, 100, map(i, 0, 30, 90, 3));
    const wob = sin(i * 1.3) * 20 + random(-12, 12);
    rect(300 - 40 + wob, y - 70, random(30, 90), random(2, 5));
  }
}

// "La chambre qui respire encore"
// Huile imaginaire — p5.js 1.11

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

// ---------- utilitaires ----------
function lerpCol(a, b, t) { return lerpColor(a, b, constrain(t, 0, 1)); }

// Tache de pinceau organique
function brushBlob(x, y, r, col, alpha, detail, wob) {
  push();
  noStroke();
  fill(red(col), green(col), blue(col), alpha);
  beginShape();
  for (let a = 0; a < TWO_PI; a += TWO_PI / detail) {
    let n = noise(cos(a) * wob + x * 0.004, sin(a) * wob + y * 0.004, r * 0.01);
    let rr = r * (0.62 + n * 0.78);
    vertex(x + cos(a) * rr, y + sin(a) * rr * 0.86);
  }
  endShape(CLOSE);
  pop();
}

// Trait de pinceau directionnel
function stroke2(x1, y1, x2, y2, w, col, alpha, segs) {
  push();
  noStroke();
  let d = dist(x1, y1, x2, y2);
  let n = segs || max(6, floor(d / 6));
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    let taper = sin(t * PI);
    let nn = noise(x * 0.01, y * 0.01, t * 2.0);
    let ww = w * (0.35 + taper * 0.75) * (0.6 + nn * 0.8);
    fill(red(col), green(col), blue(col), alpha * (0.4 + taper * 0.6));
    ellipse(x + (nn - 0.5) * w * 0.5, y + (nn - 0.5) * w * 0.4, ww, ww * 0.9);
  }
  pop();
}

function draw() {
  background(30, 26, 24);

  // ================= PALETTE =================
  const C = {
    deepShadow: color(28, 24, 26),
    wallDark:   color(58, 50, 52),
    wallMid:    color(104, 92, 88),
    wallLight:  color(168, 152, 138),
    warmGlow:   color(236, 206, 158),
    paleGlow:   color(250, 238, 214),
    sheetDark:  color(118, 114, 118),
    sheetMid:   color(186, 182, 180),
    sheetLight: color(238, 234, 226),
    sheetCool:  color(150, 158, 170),
    woodDark:   color(62, 44, 36),
    woodMid:    color(98, 70, 52),
    floorDark:  color(48, 38, 36),
    floorMid:   color(86, 68, 58),
    blue:       color(92, 104, 128),
    rust:       color(146, 82, 58)
  };

  // ================= FOND : MUR =================
  // dégradé vertical + lumière venant de la gauche
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let ny = y / height;
      let nx = x / width;

      // base mur
      let base = lerpCol(C.wallDark, C.wallMid, 0.25 + ny * 0.35);

      // halo lumineux depuis la fenêtre (haut-gauche)
      let lx = 300, ly = 420;
      let dl = dist(x, y, lx, ly) / 1500;
      let glow = pow(constrain(1 - dl, 0, 1), 1.7);

      // ombre bas / coins
      let vign = 1 - pow(dist(x, y, 800, 1000) / 1450, 2.1);
      vign = constrain(vign, 0, 1);

      let c = lerpCol(base, C.wallLight, glow * 0.85);
      c = lerpCol(c, C.warmGlow, glow * glow * 0.45);
      c = lerpCol(C.deepShadow, c, 0.28 + vign * 0.72);

      // grain de toile
      let g = noise(x * 0.012, y * 0.012) * 26 - 13;
      let g2 = (noise(x * 0.14, y * 0.14) - 0.5) * 14;

      let i = (y * width + x) * 4;
      pixels[i]     = constrain(red(c) + g + g2, 0, 255);
      pixels[i + 1] = constrain(green(c) + g * 0.95 + g2, 0, 255);
      pixels[i + 2] = constrain(blue(c) + g * 0.85 + g2, 0, 255);
      pixels[i + 3] = 255;
    }
  }
  updatePixels();

  // ================= FENÊTRE (hors champ, à gauche) =================
  // rectangle de lumière projeté sur le mur
  push();
  noStroke();
  // grande nappe lumineuse oblique
  for (let k = 0; k < 90; k++) {
    let t = k / 89;
    let a = 16 * (1 - t * 0.75);
    fill(250, 240, 214, a);
    beginShape();
    vertex(-60, 180 + t * 40);
    vertex(560 - t * 120, 120 + t * 90);
    vertex(700 - t * 180, 760 + t * 160);
    vertex(-60, 980 + t * 200);
    endShape(CLOSE);
  }
  // barre de croisillon : bande d'ombre
  for (let k = 0; k < 30; k++) {
    fill(70, 60, 58, 7);
    beginShape();
    vertex(-60, 470 + k * 0.6);
    vertex(600 - k, 430 + k * 0.6);
    vertex(610 - k, 500 + k * 0.6);
    vertex(-60, 548 + k * 0.6);
    endShape(CLOSE);
  }
  pop();

  // Texture du mur : coups de brosse larges verticaux
  for (let i = 0; i < 520; i++) {
    let x = random(width);
    let y = random(-50, 1250);
    let lx = 300, ly = 420;
    let dl = constrain(1 - dist(x, y, lx, ly) / 1500, 0, 1);
    let c = lerpCol(C.wallDark, C.wallLight, 0.2 + dl * 0.9);
    c = lerpCol(c, C.warmGlow, dl * dl * 0.5);
    stroke2(x, y, x + random(-30, 30), y + random(70, 230), random(16, 46), c, random(8, 24));
  }

  // Taches d'humidité / mémoire du mur
  for (let i = 0; i < 26; i++) {
    let x = random(60, width - 60);
    let y = random(80, 1150);
    let dl = constrain(1 - dist(x, y, 300, 420) / 1600, 0, 1);
    brushBlob(x, y, random(40, 150), lerpCol(C.wallDark, C.rust, 0.18 + dl * 0.2), random(6, 16), 24, 1.6);
  }

  // Rectangle plus clair : un cadre décroché du mur
  push();
  noStroke();
  let fx = 1120, fy = 420, fw = 300, fh = 380;
  for (let k = 0; k < 40; k++) {
    fill(192, 176, 158, 5);
    rect(fx + random(-4, 4), fy + random(-4, 4), fw, fh);
  }
  // léger liseré d'ombre
  for (let k = 0; k < 26; k++) {
    fill(48, 40, 40, 9);
    rect(fx + random(-3, 3), fy + fh - 10 + random(-3, 3), fw, 18);
    rect(fx + fw - 12 + random(-3, 3), fy + random(-3, 3), 16, fh);
  }
  // clou
  fill(42, 34, 32, 150);
  ellipse(fx + fw / 2, fy - 26, 10, 12);
  pop();

  // ================= PLINTHE + SOL =================
  const floorY = 1340;

  push();
  noStroke();
  // plinthe
  for (let k = 0; k < 50; k++) {
    fill(red(C.woodDark), green(C.woodDark), blue(C.woodDark), 16);
    rect(0, floorY - 54 + random(-5, 5), width, 58);
  }
  pop();

  // sol
  for (let y = floorY; y < height; y++) {
    let t = (y - floorY) / (height - floorY);
    let c = lerpCol(C.floorMid, C.floorDark, pow(t, 0.6));
    push();
    stroke(red(c), green(c), blue(c), 230);
    line(0, y, width, y);
    pop();
  }
  // lattes + lumière au sol
  for (let i = 0; i < 300; i++) {
    let y = random(floorY, height);
    let t = (y - floorY) / (height - floorY);
    let x = random(width);
    let lit = constrain(1 - dist(x, y, 220, floorY + 140) / 900, 0, 1);
    let c = lerpCol(C.floorDark, C.warmGlow, lit * 0.5 * (1 - t * 0.5));
    stroke2(x - random(80, 240), y, x + random(80, 240), y + random(-6, 6), random(6, 20), c, random(10, 26));
  }
  // flaque de lumière au sol
  push();
  noStroke();
  for (let k = 0; k < 60; k++) {
    let t = k / 59;
    fill(244, 224, 184, 9 * (1 - t));
    beginShape();
    vertex(-40, floorY + 40 + t * 30);
    vertex(420 - t * 90, floorY + 10 + t * 40);
    vertex(520 - t * 140, floorY + 320 + t * 60);
    vertex(-40, floorY + 420 + t * 80);
    endShape(CLOSE);
  }
  pop();

  // ================= LE LIT =================
  // géométrie générale
  const bedTop = 1080;     // ligne du matelas au fond
  const bedFrontY = 1620;  // bord avant du matelas
  const bedLeft = 240;
  const bedRight = 1500;

  // --- tête de lit en bois ---
  push();
  noStroke();
  for (let k = 0; k < 70; k++) {
    fill(red(C.woodDark), green(C.woodDark), blue(C.woodDark), 14);
    rect(bedLeft + 40 + random(-5, 5), 780 + random(-6, 6), bedRight - bedLeft - 140, 330, 14);
  }
  pop();
  for (let i = 0; i < 260; i++) {
    let x = random(bedLeft + 40, bedRight - 100);
    let y = random(780, 1110);
    let lit = constrain(1 - dist(x, y, 320, 760) / 1300, 0, 1);
    let c = lerpCol(C.woodDark, C.woodMid, 0.2 + lit * 1.0);
    c = lerpCol(c, C.warmGlow, lit * lit * 0.35);
    stroke2(x - random(40, 160), y, x + random(40, 160), y + random(-4, 4), random(8, 22), c, random(14, 34));
  }
  // montants
  push();
  noStroke();
  for (let k = 0; k < 40; k++) {
    fill(44, 32, 26, 16);
    rect(bedLeft + 20 + random(-4, 4), 740 + random(-5, 5), 46, 400, 10);
    rect(bedRight - 110 + random(-4, 4), 752 + random(-5, 5), 46, 390, 10);
  }
  pop();
  // lumière sur le montant gauche
  for (let i = 0; i < 70; i++) {
    stroke2(bedLeft + 28, 760 + random(380), bedLeft + 34, 790 + random(380), random(6, 14),
      lerpCol(C.woodMid, C.warmGlow, random(0.3, 0.8)), random(12, 30));
  }

  // --- ombre portée du lit sur le mur ---
  push();
  noStroke();
  for (let k = 0; k < 40; k++) {
    fill(34, 28, 30, 10);
    beginShape();
    vertex(bedRight - 160, 760);
    vertex(bedRight + 160 + k, 790);
    vertex(bedRight + 200 + k, 1340);
    vertex(bedRight - 200, 1330);
    endShape(CLOSE);
  }
  pop();

  // --- matelas / masse du lit ---
  push();
  noStroke();
  for (let k = 0; k < 60; k++) {
    fill(red(C.sheetDark), green(C.sheetDark), blue(C.sheetDark), 14);
    beginShape();
    vertex(bedLeft - 20 + random(-6, 6), bedTop + random(-8, 8));
    vertex(bedRight + 30 + random(-6, 6), bedTop + 30 + random(-8, 8));
    vertex(bedRight + 60, bedFrontY + 140);
    vertex(bedLeft - 70, bedFrontY + 110);
    endShape(CLOSE);
  }
  pop();

  // ================= LES DRAPS =================
  // champ de hauteur : on sculpte une "forme absente" (creux) au centre
  function sheetHeight(x, y) {
    // vallée du corps : une longue dépression diagonale
    let bodyAx = 560, bodyAy = 1200;   // tête
    let bodyBx = 1180, bodyBy = 1520;  // pieds
    // distance au segment
    let vx = bodyBx - bodyAx, vy = bodyBy - bodyAy;
    let wx = x - bodyAx, wy = y - bodyAy;
    let t = constrain((wx * vx + wy * vy) / (vx * vx + vy * vy), 0, 1);
    let px = bodyAx + vx * t, py = bodyAy + vy * t;
    let d = dist(x, y, px, py);
    let wid = 190 - 60 * abs(t - 0.5) * 2 + 40 * sin(t * PI);
    let hollow = -exp(-pow(d / wid, 2)) * (0.55 + 0.45 * sin(t * PI));

    // plis
    let f = 0;
    f += noise(x * 0.0022, y * 0.0038) * 1.0;
    f += noise(x * 0.006, y * 0.009) * 0.45;
    f += noise(x * 0.016, y * 0.02) * 0.18;
    f = f / 1.63;

    // bourrelet autour du creux
    let ridge = exp(-pow((d - wid * 1.25) / (wid * 0.5), 2)) * 0.3;

    return f * 0.9 + hollow * 1.15 + ridge;
  }

  // rendu des draps par petits traits suivant la pente
  const sx0 = bedLeft - 40, sx1 = bedRight + 40;
  const sy0 = bedTop + 10, sy1 = bedFrontY + 130;

  // sous-couche
  push();
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = random(sx0, sx1);
    let y = random(sy0, sy1);
    if (y < bedTop + 10) continue;
    let h = sheetHeight(x, y);
    let lit = constrain(1 - dist(x, y, 380, 1150) / 1500, 0, 1);
    let v = constrain(0.5 + h * 0.6 + lit * 0.35, 0, 1);
    let c = lerpCol(C.sheetDark, C.sheetLight, v);
    c = lerpCol(c, C.sheetCool, 0.25 * (1 - lit));
    fill(red(c), green(c), blue(c), 28);
    ellipse(x, y, random(30, 90), random(24, 60));
  }
  pop();

  // traits de modelé : suivent le gradient du champ
  for (let i = 0; i < 5200; i++) {
    let x = random(sx0, sx1);
    let y = random(sy0, sy1);
    let h = sheetHeight(x, y);
    let e = 9;
    let gx = sheetHeight(x + e, y) - sheetHeight(x - e, y);
    let gy = sheetHeight(x, y + e) - sheetHeight(x, y - e);
    // direction perpendiculaire au gradient => suit les plis
    let ang = atan2(gx, -gy);
    let len = random(22, 95);

    let lit = constrain(1 - dist(x, y, 380, 1140) / 1550, 0, 1);
    // éclairage : pente face à la lumière (haut-gauche)
    let slope = -(gx * -0.72 + gy * -0.69) * 9.0;
    let v = constrain(0.46 + h * 0.5 + slope * 0.5 + lit * 0.32, 0, 1);

    let c = lerpCol(C.sheetDark, C.sheetLight, v);
    c = lerpCol(c, C.sheetCool, 0.3 * (1 - lit) * (1 - v));
    if (v > 0.78) c = lerpCol(c, C.paleGlow, (v - 0.78) * 2.2 * (0.3 + lit * 0.7));
    if (v < 0.3) c = lerpCol(c, C.deepShadow, (0.3 - v) * 1.4);

    let w = random(5, 16);
    stroke2(x - cos(ang) * len * 0.5, y - sin(ang) * len * 0.5,
            x + cos(ang) * len * 0.5, y + sin(ang) * len * 0.5,
            w, c, random(22, 58));
  }

  // accents hautes lumières sur les crêtes
  for (let i = 0; i < 900; i++) {
    let x = random(sx0, sx1);
    let y = random(sy0, sy1);
    let h = sheetHeight(x, y);
    if (h < 0.62) continue;
    let e = 9;
    let gx = sheetHeight(x + e, y) - sheetHeight(x - e, y);
    let gy = sheetHeight(x, y + e) - sheetHeight(x, y - e);
    let ang = atan2(gx, -gy);
    let lit = constrain(1 - dist(x, y, 380, 1140) / 1600, 0, 1);
    let c = lerpCol(C.sheetLight, C.paleGlow, 0.3 + lit * 0.7);
    stroke2(x - cos(ang) * 30, y - sin(ang) * 30, x + cos(ang) * 30, y + sin(ang) * 30,
      random(4, 11), c, random(30, 75));
  }

  // ombres profondes dans le creux
  for (let i = 0; i < 1100; i++) {
    let x = random(420, 1340);
    let y = random(1120, 1660);
    let h = sheetHeight(x, y);
    if (h > -0.1) continue;
    let e = 9;
    let gx = sheetHeight(x + e, y) - sheetHeight(x - e, y);
    let gy = sheetHeight(x, y + e) - sheetHeight(x, y - e);
    let ang = atan2(gx, -gy);
    let c = lerpCol(C.sheetDark, C.blue, 0.35 + random(0.3));
    c = lerpCol(c, C.deepShadow, constrain(-h * 0.8, 0, 0.7));
    stroke2(x - cos(ang) * 40, y - sin(ang) * 40, x + cos(ang) * 40, y + sin(ang) * 40,
      random(8, 20), c, random(14, 40));
  }

  // ================= OREILLER =================
  const px0 = 430, py0 = 1040, pw = 440, ph = 240;

  function pillowH(x, y) {
    let u = (x - px0) / pw, v = (y - py0) / ph;
    let d = pow((u - 0.5) * 2, 2) * 1.0 + pow((v - 0.5) * 2, 2) * 1.0;
    let base = constrain(1 - d, 0, 1);
    // creux de la tête, décalé
    let hollow = exp(-(pow((x - (px0 + pw * 0.52)) / 135, 2) + pow((y - (py0 + ph * 0.58)) / 88, 2)));
    let n = noise(x * 0.008, y * 0.012) * 0.35;
    return pow(base, 0.6) * 1.0 - hollow * 0.95 + n;
  }

  // ombre sous l'oreiller
  push();
  noStroke();
  for (let k = 0; k < 40; k++) {
    fill(40, 36, 42, 11);
    ellipse(px0 + pw / 2 + 30, py0 + ph + 34 + random(-8, 8), pw * 1.06, 110);
  }
  pop();

  for (let i = 0; i < 2600; i++) {
    let x = random(px0 - 40, px0 + pw + 40);
    let y = random(py0 - 40, py0 + ph + 50);
    let u = (x - px0) / pw, v = (y - py0) / ph;
    let d = pow((u - 0.5) * 2, 2) + pow((v - 0.5) * 2, 2);
    let edge = noise(x * 0.01, y * 0.01) * 0.35;
    if (d > 1.0 + edge * 0.6) continue;

    let h = pillowH(x, y);
    let e = 7;
    let gx = pillowH(x + e, y) - pillowH(x - e, y);
    let gy = pillowH(x, y + e) - pillowH(x, y - e);
    let ang = atan2(gx, -gy);
    let slope = -(gx * -0.7 + gy * -0.7) * 10.0;

    let lit = constrain(1 - dist(x, y, 380, 1060) / 1100, 0, 1);
    let val = constrain(0.5 + h * 0.3 + slope * 0.5 + lit * 0.3, 0, 1);
    let c = lerpCol(C.sheetDark, C.sheetLight, val);
    if (val > 0.72) c = lerpCol(c, C.paleGlow, (val - 0.72) * 2.6);
    if (val < 0.32) c = lerpCol(c, C.blue, (0.32 - val) * 1.5);

    let len = random(16, 56);
    stroke2(x - cos(ang) * len * 0.5, y - sin(ang) * len * 0.5,
            x + cos(ang) * len * 0.5, y + sin(ang) * len * 0.5,
            random(5, 14), c, random(26, 62));
  }

  // ================= DRAP QUI TOMBE AU SOL =================
  push();
  noStroke();
  for (let i = 0; i < 1500; i++) {
    let t = random(1);
    let bx = lerp(bedLeft - 30, bedLeft - 230, pow(t, 1.3)) + random(-70, 70);
    let by = lerp(bedFrontY + 60, floorY + 480, pow(t, 0.8)) + random(-50, 50);
    if (by < bedFrontY - 20) continue;
    let n = noise(bx * 0.006, by * 0.006);
    let lit = constrain(1 - dist(bx, by, 300, 1500) / 900, 0, 1);
    let v = constrain(0.3 + n * 0.7 + lit * 0.3, 0, 1);
    let c = lerpCol(C.sheetDark, C.sheetLight, v);
    c = lerpCol(c, C.deepShadow, 0.35 * (1 - lit));
    let ang = -PI / 2.6 + (n - 0.5) * 1.4;
    stroke2(bx, by, bx + cos(ang) * random(30, 90), by + sin(ang) * random(30, 90),
      random(6, 18), c, random(16, 48));
  }
  pop();

  // ================= CHAISE / FORME SOMBRE À DROITE =================
  push();
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(1340, 1600);
    let y = random(1180, 1760);
    let c = lerpCol(C.woodDark, C.deepShadow, random(0.3, 0.9));
    stroke2(x, y, x + random(-20, 20), y + random(-70, 70), random(10, 30), c, random(8, 22));
  }
  pop();

  // ================= POUSSIÈRE DANS LA LUMIÈRE =================
  push();
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(-40, 900);
    let y = random(60, 1500);
    // dans le faisceau ?
    let inBeam = (y > 120 + x * 0.45) && (y < 900 + x * 0.55);
    if (!inBeam) continue;
    let lit = constrain(1 - dist(x, y, 320, 620) / 1200, 0, 1);
    let s = random(1.5, 7);
    fill(255, 246, 224, random(18, 95) * (0.3 + lit));
    ellipse(x, y, s, s);
    if (random() < 0.08) {
      fill(255, 250, 238, random(60, 150));
      ellipse(x, y, s * 0.5, s * 0.5);
    }
  }
  pop();

  // ================= UNIFICATION / GLACIS =================
  push();
  noStroke();
  // glacis chaud dans la lumière
  for (let k = 0; k < 30; k++) {
    let t = k / 29;
    fill(246, 214, 170, 4);
    ellipse(360, 760, 1500 - t * 900, 1900 - t * 1100);
  }
  // glacis froid dans l'ombre droite/bas
  for (let k = 0; k < 30; k++) {
    let t = k / 29;
    fill(58, 62, 86, 5);
    ellipse(1420, 1700, 1500 - t * 900, 1600 - t * 1000);
  }
  pop();

  // vignettage pictural
  push();
  noStroke();
  for (let k = 0; k < 120; k++) {
    let t = k / 119;
    fill(24, 20, 22, 3.2);
    beginShape();
    vertex(0, 0); vertex(width, 0); vertex(width, height); vertex(0, height);
    beginContour();
    let m = 60 + t * 620;
    vertex(m, m * 0.8);
    vertex(width - m, m * 0.8);
    vertex(width - m, height - m * 0.8);
    vertex(m, height - m * 0.8);
    endContour();
    endShape(CLOSE);
  }
  pop();

  // ================= GRAIN FINAL / TOILE =================
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = (y * width + x) * 4;
      let weave = (sin(x * 0.9) * sin(y * 0.9)) * 5.0;
      let g = (noise(x * 0.3, y * 0.3) - 0.5) * 16;
      let craq = noise(x * 0.004, y * 0.004) > 0.73 ? -4 : 0;
      pixels[i]     = constrain(pixels[i] + g + weave + craq, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + g * 0.96 + weave + craq, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + g * 0.9 + weave + craq, 0, 255);
    }
  }
  updatePixels();
}

// "La chambre qui se vide"
// Huile imaginaire — une chambre au moment où la lumière se retire.

let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(30, 27, 26);

  groundWash();        // fond mural, pénombre chaude
  floorPlane();        // sol
  windowLight();       // la fenêtre, source unique
  lightWedge();        // le rai de lumière sur le sol
  bedStructure();      // le lit
  sheetMass();         // les draps / le corps devenu drap
  chairAndCoat();      // la chaise, le vêtement abandonné
  dustMotes();         // poussière en suspension
  glazeAndGrain();     // glacis, grain, vignettage
}

/* ---------------------------------------------------------- */
/* Utilitaires                                                 */
/* ---------------------------------------------------------- */

function lerpCol(a, b, t) { return lerpColor(a, b, constrain(t, 0, 1)); }

// Trace une tache de pinceau douce
function brush(x, y, r, col, alpha, elong, ang) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  let steps = 5;
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    fill(red(col), green(col), blue(col), alpha * (1 - t) * 0.9);
    ellipse(0, 0, r * 2 * t * elong, r * 2 * t);
  }
  pop();
}

// Bande de coups de pinceau le long d'un chemin
function strokeBand(x1, y1, x2, y2, width_, col, alpha, n, jitter) {
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let x = lerp(x1, x2, t) + random(-jitter, jitter);
    let y = lerp(y1, y2, t) + random(-jitter, jitter);
    let ang = atan2(y2 - y1, x2 - x1);
    brush(x, y, width_ * random(0.6, 1.2), col, alpha, random(1.4, 2.6), ang + random(-0.2, 0.2));
  }
}

/* ---------------------------------------------------------- */
/* 1. Mur / pénombre                                           */
/* ---------------------------------------------------------- */

function groundWash() {
  let darkA = color(36, 31, 30);
  let darkB = color(58, 50, 46);
  let warm  = color(92, 76, 63);

  noStroke();
  // dégradé vertical de base
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let c = lerpCol(darkA, darkB, pow(t, 0.7));
    fill(c);
    rect(0, y, W, 1);
  }

  // halo de chaleur venant de la fenêtre (droite haute)
  for (let i = 0; i < 2600; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(), 0.55) * 1150;
    let x = 1180 + cos(a) * rr * 1.05;
    let y = 620 + sin(a) * rr * 0.95;
    let d = dist(x, y, 1180, 620) / 1150;
    let c = lerpCol(warm, darkB, d);
    brush(x, y, random(40, 120), c, 10 * (1 - d), random(1.2, 2.2), random(-0.5, 0.5));
  }

  // texture murale : coups verticaux
  for (let i = 0; i < 2200; i++) {
    let x = random(W);
    let y = random(-50, 1350);
    let n = noise(x * 0.0012, y * 0.0012);
    let base = lerpCol(darkA, color(80, 68, 58), n);
    brush(x, y, random(18, 55), base, 9, random(0.4, 0.8), HALF_PI + random(-0.15, 0.15));
  }

  // coin gauche très sombre
  for (let i = 0; i < 900; i++) {
    let x = random(-60, 520);
    let y = random(-60, 1500);
    let d = constrain(x / 520, 0, 1);
    brush(x, y, random(40, 130), color(22, 19, 20), 16 * (1 - d), random(0.8, 1.6), random(TWO_PI));
  }
}

/* ---------------------------------------------------------- */
/* 2. Sol                                                      */
/* ---------------------------------------------------------- */

function floorPlane() {
  let horizon = 1310;
  let floorDark = color(44, 35, 30);
  let floorLit = color(104, 84, 64);

  noStroke();
  for (let y = horizon; y < H; y++) {
    let t = (y - horizon) / (H - horizon);
    let c = lerpCol(color(52, 42, 35), color(34, 27, 24), pow(t, 0.8));
    fill(c);
    rect(0, y, W, 1);
  }

  // lattes du plancher en perspective
  for (let k = -14; k < 20; k++) {
    let xTop = 760 + k * 62;
    let xBot = 760 + k * 230;
    stroke(26, 21, 19, 70);
    strokeWeight(2.2);
    line(xTop, horizon, xBot, H + 40);
  }
  noStroke();

  // texture de plancher
  for (let i = 0; i < 2600; i++) {
    let y = horizon + pow(random(), 0.8) * (H - horizon);
    let x = random(-80, W + 80);
    let t = (y - horizon) / (H - horizon);
    let n = noise(x * 0.002, y * 0.004);
    let c = lerpCol(floorDark, floorLit, n * (1 - t * 0.6) * 0.75);
    brush(x, y, random(20, 70), c, 11, random(2.0, 4.5), random(-0.08, 0.08));
  }
}

/* ---------------------------------------------------------- */
/* 3. Fenêtre                                                  */
/* ---------------------------------------------------------- */

function windowLight() {
  let wx = 1040, wy = 215, ww = 440, wh = 760;

  // embrasure sombre
  noStroke();
  fill(26, 22, 21, 230);
  rect(wx - 46, wy - 46, ww + 92, wh + 92);

  // la vitre : blanc chaud presque aveuglant, non uniforme
  for (let i = 0; i < 5200; i++) {
    let x = wx + random(ww);
    let y = wy + random(wh);
    let ty = (y - wy) / wh;
    let c = lerpCol(color(255, 250, 238), color(214, 206, 188), pow(ty, 1.3) * 0.9);
    let n = noise(x * 0.004, y * 0.004);
    c = lerpCol(c, color(246, 238, 222), n * 0.5);
    brush(x, y, random(18, 48), c, 26, random(0.8, 1.8), random(TWO_PI));
  }

  // bord de la vitre un peu éteint
  for (let i = 0; i < 1400; i++) {
    let edge = random();
    let x, y;
    if (edge < 0.5) { x = wx + random(ww); y = wy + (random() < 0.5 ? random(70) : wh - random(70)); }
    else { y = wy + random(wh); x = wx + (random() < 0.5 ? random(70) : ww - random(70)); }
    brush(x, y, random(20, 55), color(196, 190, 176), 11, random(1, 2), random(TWO_PI));
  }

  // meneaux
  noStroke();
  fill(38, 32, 29, 245);
  rect(wx + ww * 0.5 - 11, wy, 22, wh);
  rect(wx, wy + wh * 0.42 - 11, ww, 22);
  // léger halo sur les meneaux
  for (let i = 0; i < 400; i++) {
    let x = wx + ww * 0.5 + random(-18, 18);
    let y = wy + random(wh);
    brush(x, y, random(6, 16), color(120, 110, 98), 14, 1, random(TWO_PI));
  }

  // cadre / chambranle
  noFill();
  stroke(60, 51, 45, 200);
  strokeWeight(16);
  rect(wx - 14, wy - 14, ww + 28, wh + 28);
  strokeWeight(5);
  stroke(132, 116, 98, 150);
  rect(wx - 4, wy - 4, ww + 8, wh + 8);
  noStroke();

  // appui de fenêtre
  fill(70, 60, 52, 235);
  quad(wx - 60, wy + wh + 46, wx + ww + 60, wy + wh + 46,
       wx + ww + 86, wy + wh + 86, wx - 86, wy + wh + 86);
  for (let i = 0; i < 700; i++) {
    let x = random(wx - 80, wx + ww + 80);
    let y = random(wy + wh + 46, wy + wh + 86);
    brush(x, y, random(10, 30), color(150, 132, 110), 12, random(2, 4), 0);
  }

  // débordement lumineux (bloom)
  for (let i = 0; i < 1600; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(), 0.5) * 300;
    let x = wx + ww / 2 + cos(a) * rr * 1.25;
    let y = wy + wh / 2 + sin(a) * rr * 1.9;
    let d = dist(x, y, wx + ww / 2, wy + wh / 2) / 520;
    brush(x, y, random(30, 90), color(248, 240, 224), 9 * (1 - d), random(1, 2), random(TWO_PI));
  }
}

/* ---------------------------------------------------------- */
/* 4. Rai de lumière au sol                                    */
/* ---------------------------------------------------------- */

function lightWedge() {
  push();
  // trapèze de lumière projeté depuis la fenêtre vers la gauche-bas
  let p = [
    [1040, 1320],
    [1480, 1320],
    [1180, 2000],
    [180, 2000]
  ];
  // peinture par points à l'intérieur
  for (let i = 0; i < 9000; i++) {
    let t1 = random(), t2 = random();
    // interpolation bilinéaire sur le quad
    let ax = lerp(p[0][0], p[1][0], t1), ay = lerp(p[0][1], p[1][1], t1);
    let bx = lerp(p[3][0], p[2][0], t1), by = lerp(p[3][1], p[2][1], t1);
    let x = lerp(ax, bx, t2), y = lerp(ay, by, t2);
    let fade = 1 - pow(t2, 1.25) * 0.85;
    let edge = 1 - pow(abs(t1 - 0.5) * 2, 2.4);
    let a = 16 * fade * edge;
    let c = lerpCol(color(255, 243, 219), color(196, 164, 124), t2 * 0.8);
    brush(x, y, random(22, 70), c, a, random(2, 4.5), random(-0.12, 0.12));
  }

  // ombre de la croisée dans le rai
  noStroke();
  for (let i = 0; i < 2400; i++) {
    let t1 = random(), t2 = random();
    let ax = lerp(p[0][0], p[1][0], t1), ay = p[0][1];
    let bx = lerp(p[3][0], p[2][0], t1), by = p[3][1];
    let x = lerp(ax, bx, t2), y = lerp(ay, by, t2);
    let inBarV = abs(t1 - 0.5) < 0.035;
    let inBarH = abs(t2 - 0.40) < 0.028;
    if (inBarV || inBarH) {
      brush(x, y, random(14, 34), color(84, 66, 50), 16, random(1.5, 3), 0);
    }
  }
  pop();
}

/* ---------------------------------------------------------- */
/* 5. Le lit                                                   */
/* ---------------------------------------------------------- */

function bedStructure() {
  // tête de lit (gauche)
  let hx = 150, hy = 820, hw = 70, hh = 560;
  noStroke();
  // montants
  for (let i = 0; i < 1500; i++) {
    let x = hx + random(-30, hw + 30);
    let y = hy + random(hh);
    let lit = constrain(map(x, hx - 30, hx + hw + 30, 0.15, 0.75), 0, 1);
    let c = lerpCol(color(32, 26, 24), color(118, 94, 70), lit * (0.5 + 0.5 * noise(x * 0.01, y * 0.01)));
    brush(x, y, random(10, 28), c, 16, random(0.6, 1.2), HALF_PI);
  }
  // barre horizontale haute
  for (let i = 0; i < 900; i++) {
    let x = random(hx - 36, hx + 300);
    let y = hy + random(-24, 18);
    let c = lerpCol(color(40, 32, 28), color(132, 106, 78), noise(x * 0.01) * 0.9);
    brush(x, y, random(9, 22), c, 15, random(2, 3.5), 0);
  }

  // pied de lit (droite, dans l'ombre)
  for (let i = 0; i < 900; i++) {
    let x = 1020 + random(-26, 26);
    let y = 1130 + random(350);
    let c = lerpCol(color(26, 22, 20), color(96, 78, 58), noise(x * 0.01, y * 0.01) * 0.6);
    brush(x, y, random(10, 26), c, 15, random(0.6, 1.2), HALF_PI);
  }

  // châssis / ombre sous le lit
  for (let i = 0; i < 2600; i++) {
    let x = random(90, 1120);
    let y = 1430 + pow(random(), 1.4) * 230;
    let d = (y - 1430) / 230;
    brush(x, y, random(30, 90), color(20, 16, 15), 16 * (1 - d * 0.75), random(2.2, 4.5), random(-0.1, 0.1));
  }
}

/* ---------------------------------------------------------- */
/* 6. Drap et corps                                            */
/* ---------------------------------------------------------- */

function sheetMass() {
  // Profil du drap : une longue masse horizontale avec un relief
  // (épaule, hanche, pieds) — jamais un visage.
  let x0 = 130, x1 = 1060;
  let baseY = 1420;

  // hauteur du drap en fonction de x
  function sheetTop(x) {
    let t = (x - x0) / (x1 - x0);
    let h = 0;
    h += 118 * exp(-pow((t - 0.17) / 0.105, 2));   // tête/épaule
    h += 96  * exp(-pow((t - 0.37) / 0.13, 2));    // torse
    h += 132 * exp(-pow((t - 0.57) / 0.10, 2));    // hanche
    h += 58  * exp(-pow((t - 0.80) / 0.11, 2));    // genoux
    h += 74  * exp(-pow((t - 0.945) / 0.045, 2));  // pieds
    h += 36;                                        // matelas
    h += 14 * noise(t * 7.0, 11.3);
    return baseY - h;
  }

  // Masse principale du drap, peinte en coups suivant la forme
  for (let i = 0; i < 46000; i++) {
    let x = random(x0 - 25, x1 + 25);
    let topY = sheetTop(x);
    let y = topY + pow(random(), 0.75) * (baseY + 40 - topY);
    if (x < x0 || x > x1) { if (random() > 0.25) continue; }

    let depth = (y - topY) / max(1, (baseY + 40 - topY)); // 0 = crête

    // éclairage : la lumière vient de la droite (fenêtre)
    let lightX = constrain(map(x, 300, 1100, 0.08, 1.0), 0, 1);
    // courbure locale -> micro plis
    let fold = noise(x * 0.012, y * 0.009, 3.1);
    let fold2 = noise(x * 0.045, y * 0.03, 8.7);

    let lum = lightX * (1 - depth * 0.72);
    lum *= (0.55 + 0.75 * fold);
    lum += (fold2 - 0.5) * 0.30;
    lum = constrain(lum, 0, 1);

    let shadow = color(42, 38, 40);
    let mid    = color(126, 118, 112);
    let lit    = color(222, 213, 198);
    let hot    = color(250, 244, 230);

    let c;
    if (lum < 0.45) c = lerpCol(shadow, mid, lum / 0.45);
    else if (lum < 0.82) c = lerpCol(mid, lit, (lum - 0.45) / 0.37);
    else c = lerpCol(lit, hot, (lum - 0.82) / 0.18);

    // teinte froide dans les creux, chaude dans les lumières
    c = lerpCol(c, color(96, 104, 120), (1 - lum) * 0.28);
    c = lerpCol(c, color(255, 234, 198), pow(lum, 3) * 0.45);

    let ang = atan2(sheetTop(x + 12) - topY, 12) * 0.7 + (fold - 0.5) * 1.1;
    brush(x, y, random(7, 22), c, 22, random(1.3, 3.2), ang);
  }

  // Crête lumineuse : le fil de lumière qui court sur le corps
  for (let x = x0; x < x1; x += 2.0) {
    let topY = sheetTop(x);
    let lightX = constrain(map(x, 280, 1080, 0.0, 1.0), 0, 1);
    let n = noise(x * 0.02, 50.0);
    let a = 34 * pow(lightX, 1.4) * (0.35 + n);
    let c = lerpCol(color(236, 226, 206), color(255, 248, 228), n);
    brush(x + random(-3, 3), topY + random(-5, 7), random(4, 13), c, a, random(1.6, 3.0), -0.1);
  }

  // Plis tombants sur le bord avant du lit
  for (let k = 0; k < 26; k++) {
    let x = random(x0 + 20, x1 - 10);
    let topY = sheetTop(x);
    let len = random(70, 210);
    let lightX = constrain(map(x, 300, 1080, 0.05, 1), 0, 1);
    let dark = lerpCol(color(36, 33, 36), color(110, 100, 94), lightX * 0.8);
    strokeBand(x, baseY - len * 0.2, x + random(-28, 28), baseY + 34, random(5, 13), dark, 16, 36, 5);
    let brightC = lerpCol(color(150, 142, 134), color(240, 232, 214), lightX);
    strokeBand(x + 12, baseY - len * 0.2, x + 12 + random(-20, 20), baseY + 26, random(3, 7), brightC, 13, 28, 4);
  }

  // Un pan de drap qui glisse au sol — le geste le plus humain du tableau
  let fx = 940, fy = 1455;
  for (let i = 0; i < 5200; i++) {
    let t = random();
    let x = fx + t * 230 + random(-26, 26);
    let y = fy + pow(t, 0.8) * 300 + random(-24, 24);
    let lightX = constrain(map(x, 900, 1250, 0.3, 1.0), 0, 1);
    let n = noise(x * 0.02, y * 0.02);
    let c = lerpCol(color(60, 56, 56), color(228, 218, 200), lightX * (0.35 + n * 0.8));
    brush(x, y, random(8, 24), c, 18, random(1.4, 3), atan2(300, 230) + (n - 0.5));
  }
  // ombre portée du pan
  for (let i = 0; i < 1600; i++) {
    let x = 950 + random(260);
    let y = 1700 + random(160);
    brush(x, y, random(24, 70), color(26, 20, 18), 11, random(2, 4), 0.2);
  }

  // Oreiller, creusé, vide
  for (let i = 0; i < 6000; i++) {
    let a = random(TWO_PI), r = pow(random(), 0.55);
    let x = 250 + cos(a) * r * 150;
    let y = 1172 + sin(a) * r * 62;
    let d = r;
    let hollow = 1 - exp(-pow((x - 268) / 86, 2)) * 0.55;  // creux
    let lightX = constrain(map(x, 120, 420, 0.25, 0.85), 0, 1);
    let lum = constrain(lightX * hollow * (1 - d * 0.35) * (0.6 + 0.7 * noise(x * 0.02, y * 0.02)), 0, 1);
    let c = lerpCol(color(52, 48, 50), color(236, 228, 212), lum);
    c = lerpCol(c, color(92, 100, 116), (1 - lum) * 0.3);
    brush(x, y, random(8, 24), c, 20, random(1.4, 3), a * 0.3);
  }
}

/* ---------------------------------------------------------- */
/* 7. Chaise et vêtement                                       */
/* ---------------------------------------------------------- */

function chairAndCoat() {
  let cx = 1340, cy = 1560;

  // ombre au sol
  for (let i = 0; i < 1400; i++) {
    let x = cx + random(-150, 190);
    let y = cy + 180 + random(-40, 110);
    brush(x, y, random(26, 76), color(24, 19, 17), 10, random(2.2, 4), 0.1);
  }

  // pieds
  for (let k = 0; k < 4; k++) {
    let ox = [-96, -34, 56, 112][k];
    let sk = [18, 10, -10, -20][k];
    strokeBand(cx + ox, cy + 20, cx + ox + sk, cy + 206, random(7, 11), color(48, 38, 30), 22, 40, 3);
    strokeBand(cx + ox + 4, cy + 20, cx + ox + sk + 4, cy + 206, 3.5, color(142, 116, 86), 16, 34, 3);
  }
  // assise
  for (let i = 0; i < 1800; i++) {
    let x = cx + random(-110, 130);
    let y = cy + random(-20, 24);
    let n = noise(x * 0.01, y * 0.02);
    let c = lerpCol(color(44, 35, 28), color(150, 122, 90), n * 0.95);
    brush(x, y, random(10, 26), c, 17, random(2, 3.6), 0.05);
  }
  // dossier
  strokeBand(cx - 104, cy - 10, cx - 88, cy - 300, 11, color(46, 37, 29), 22, 46, 3);
  strokeBand(cx + 116, cy - 10, cx + 100, cy - 300, 11, color(52, 42, 33), 22, 46, 3);
  strokeBand(cx - 90, cy - 296, cx + 102, cy - 310, 12, color(60, 48, 37), 22, 46, 3);
  strokeBand(cx - 86, cy - 288, cx + 100, cy - 302, 4, color(158, 130, 96), 15, 40, 3);

  // vêtement jeté sur le dossier — la dernière présence
  for (let i = 0; i < 9000; i++) {
    let t = random();
    let u = random();
    let x = lerp(cx - 120, cx + 118, t) + sin(t * 3.1) * 18 + random(-16, 16);
    let topY = cy - 316 + 40 * sin(t * PI) * -1;
    let y = topY + u * (210 + 150 * sin(t * PI)) + random(-10, 10);
    let n = noise(x * 0.014, y * 0.012, 2.2);
    let n2 = noise(x * 0.05, y * 0.04, 9.9);
    let lightX = constrain(map(x, cx - 130, cx + 140, 0.25, 1.0), 0, 1);
    let lum = constrain(lightX * (1 - u * 0.55) * (0.4 + 0.9 * n) + (n2 - 0.5) * 0.3, 0, 1);
    let deep = color(28, 30, 42);
    let mid = color(72, 72, 86);
    let hi = color(164, 156, 150);
    let c = lum < 0.5 ? lerpCol(deep, mid, lum / 0.5) : lerpCol(mid, hi, (lum - 0.5) / 0.5);
    c = lerpCol(c, color(196, 150, 104), pow(lum, 3) * 0.5);
    brush(x, y, random(7, 20), c, 19, random(1.2, 2.8), HALF_PI + (n - 0.5) * 1.4);
  }
}

/* ---------------------------------------------------------- */
/* 8. Poussière                                                */
/* ---------------------------------------------------------- */

function dustMotes() {
  // dans le cône de lumière de la fenêtre
  for (let i = 0; i < 1500; i++) {
    let t = random();
    let x = lerp(1260, 620, t) + random(-320, 320) * (0.3 + t);
    let y = lerp(340, 1700, t) + random(-110, 110);
    if (x < 60 || x > W - 40) continue;
    let near = 1 - t;
    let r = random(1.2, 5.2) * (0.5 + near);
    let a = random(14, 95) * (0.35 + near * 0.9);
    brush(x, y, r * 2.4, color(255, 248, 230), a * 0.28, 1, 0);
    noStroke();
    fill(255, 250, 236, a);
    ellipse(x, y, r, r);
  }
  // quelques points très brillants
  for (let i = 0; i < 90; i++) {
    let x = random(760, 1500);
    let y = random(420, 1500);
    brush(x, y, random(7, 18), color(255, 252, 240), 42, 1, 0);
  }
}

/* ---------------------------------------------------------- */
/* 9. Glacis, grain, vignettage                                */
/* ---------------------------------------------------------- */

function glazeAndGrain() {
  // glacis froid général (la chaleur qui se retire)
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let x = random(W), y = random(H);
    let d = dist(x, y, 1180, 640) / 1500;
    brush(x, y, random(60, 180), color(58, 66, 84), 4 * constrain(d, 0, 1), random(1, 2), random(TWO_PI));
  }

  // glacis chaud autour de la fenêtre
  for (let i = 0; i < 1200; i++) {
    let a = random(TWO_PI), r = pow(random(), 0.6) * 900;
    let x = 1230 + cos(a) * r, y = 640 + sin(a) * r;
    brush(x, y, random(60, 180), color(214, 178, 128), 3.2, random(1, 2), random(TWO_PI));
  }

  // vignettage
  for (let i = 0; i < 9000; i++) {
    let x = random(-60, W + 60), y = random(-60, H + 60);
    let dx = (x - W / 2) / (W / 2), dy = (y - H / 2) / (H / 2);
    let d = sqrt(dx * dx * 0.9 + dy * dy);
    if (d < 0.68) continue;
    let a = pow((d - 0.68) / 0.75, 1.5) * 26;
    brush(x, y, random(50, 150), color(16, 13, 13), a, random(1, 2), random(TWO_PI));
  }

  // grain de toile
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let g = ((x * 7919 + y * 104729) % 97) / 97 - 0.5;
      let weave = (sin(x * 1.05) + sin(y * 1.05)) * 1.7;
      let v = g * 11 + weave;
      pixels[idx]     = constrain(pixels[idx] + v, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + v, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + v, 0, 255);
    }
  }
  updatePixels();

  // bord de toile légèrement usé
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(18, 14, 13, random(20, 70));
    strokeWeight(random(1, 7));
    let e = int(random(4));
    if (e === 0) line(random(W), random(0, 10), random(W), random(0, 14));
    if (e === 1) line(random(W), H - random(0, 14), random(W), H - random(0, 10));
    if (e === 2) line(random(0, 12), random(H), random(0, 14), random(H));
    if (e === 3) line(W - random(0, 12), random(H), W - random(0, 14), random(H));
  }
  noStroke();
}

// "La chambre qui respire encore"
// Une peinture statique en p5.js

let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(20, 18, 22);

  // ---------- PALETTE ----------
  const WALL_DARK   = [38, 36, 44];
  const WALL_MID    = [62, 58, 66];
  const WALL_LIGHT  = [112, 104, 102];
  const SKY_PALE    = [226, 222, 208];
  const SHEET_WARM  = [214, 200, 182];
  const SHEET_SHAD  = [120, 110, 112];
  const FLOOR_DARK  = [30, 26, 28];

  drawWalls(WALL_DARK, WALL_MID, WALL_LIGHT);
  drawFloor(FLOOR_DARK);
  drawWindow(SKY_PALE);
  drawLightShaft();
  drawBed(SHEET_WARM, SHEET_SHAD);
  drawDustMotes();
  drawChair();
  drawVignetteAndGrain();
}

/* =========================================================
   MURS
   ========================================================= */
function drawWalls(dark, mid, light) {
  // Mur du fond : dégradé vertical peint par bandes irrégulières
  noStroke();
  for (let y = 0; y < H; y += 2) {
    let t = y / H;
    // plus clair vers le haut-droite (source de lumière = fenêtre)
    let c = lerpColor(color(mid[0], mid[1], mid[2]), color(dark[0], dark[1], dark[2]), constrain(t * 1.15, 0, 1));
    fill(c);
    rect(0, y, W, 2.2);
  }

  // Gradient latéral : lumière venant de la fenêtre (droite-haut)
  for (let i = 0; i < 2600; i++) {
    let x = random(W);
    let y = random(H);
    // distance au foyer lumineux
    let d = dist(x, y, W * 0.80, H * 0.26);
    let a = map(d, 0, 1200, 46, 0, true);
    if (a <= 0) continue;
    noStroke();
    fill(light[0], light[1], light[2], a * random(0.3, 1.0));
    let r = random(60, 320);
    ellipse(x, y, r, r * random(0.5, 1.4));
  }

  // Texture de plâtre : touches de pinceau
  for (let i = 0; i < 5200; i++) {
    let x = random(-50, W + 50);
    let y = random(-50, H + 50);
    let n = noise(x * 0.0015, y * 0.0015);
    let n2 = noise(x * 0.006, y * 0.006, 10);
    let base = lerp(26, 96, n * 0.75 + n2 * 0.25);
    let warm = map(x, 0, W, -6, 14);
    let dl = dist(x, y, W * 0.80, H * 0.26);
    let lift = map(dl, 0, 1400, 34, 0, true);
    push();
    translate(x, y);
    rotate(random(-0.5, 0.5) + noise(x * 0.001, y * 0.001) * 1.4);
    noStroke();
    fill(base + warm + lift, base + warm * 0.6 + lift * 0.95, base + lift * 0.85, random(14, 48));
    rect(0, 0, random(14, 70), random(3, 9), 2);
    pop();
  }

  // Coin / arête du mur à gauche (changement de plan)
  push();
  noStroke();
  for (let i = 0; i < 160; i++) {
    let a = map(i, 0, 160, 54, 0);
    fill(14, 12, 16, a);
    rect(0, 0, 150 + i * 1.6, H);
  }
  pop();

  // Plinthe suggérée
  push();
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(W);
    let y = H * 0.615 + random(-14, 26);
    fill(22, 19, 22, random(30, 110));
    rect(x, y, random(20, 90), random(5, 16), 2);
  }
  pop();
}

/* =========================================================
   SOL
   ========================================================= */
function drawFloor(dark) {
  let horizon = H * 0.635;
  noStroke();
  for (let y = horizon; y < H; y += 2) {
    let t = (y - horizon) / (H - horizon);
    let c = lerpColor(color(58, 48, 44), color(dark[0], dark[1], dark[2]), pow(t, 0.55));
    fill(c);
    rect(0, y, W, 2.4);
  }

  // Lattes du parquet, en perspective douce
  push();
  for (let i = -6; i < 22; i++) {
    let xTop = W * 0.52 + i * 42;
    let xBot = W * 0.52 + i * 165;
    stroke(16, 13, 15, 90);
    strokeWeight(random(1.5, 3.5));
    noFill();
    beginShape();
    for (let t = 0; t <= 1.001; t += 0.1) {
      let y = lerp(horizon, H + 40, t);
      let x = lerp(xTop, xBot, pow(t, 1.35));
      vertex(x + noise(i * 10, t * 4) * 10 - 5, y);
    }
    endShape();
  }
  pop();

  // Touches de peinture sur le sol
  for (let i = 0; i < 3400; i++) {
    let y = random(horizon - 10, H);
    let t = (y - horizon) / (H - horizon);
    let x = random(W);
    let n = noise(x * 0.002, y * 0.004, 50);
    let v = lerp(18, 86, n) * (1 - t * 0.55);
    push();
    translate(x, y);
    rotate(random(-0.12, 0.12));
    noStroke();
    fill(v + 14, v + 8, v + 2, random(16, 60));
    rect(0, 0, random(30, 190) * (0.4 + t), random(3, 10), 2);
    pop();
  }
}

/* =========================================================
   FENÊTRE
   ========================================================= */
function drawWindow(sky) {
  let wx = W * 0.615, wy = H * 0.085;
  let ww = W * 0.335, wh = H * 0.405;

  // Ébrasement : lumière renvoyée sur le mur
  push();
  noStroke();
  for (let i = 60; i > 0; i--) {
    fill(180, 172, 160, 2.4);
    rect(wx - i * 2.2, wy - i * 2.2, ww + i * 4.4, wh + i * 4.4, 6);
  }
  pop();

  // Ciel : dégradé pâle, légèrement verdâtre en bas
  push();
  noStroke();
  for (let y = wy; y < wy + wh; y += 2) {
    let t = (y - wy) / wh;
    let c = lerpColor(
      color(236, 234, 224),
      color(186, 192, 184),
      pow(t, 0.8)
    );
    fill(c);
    rect(wx, y, ww, 2.4);
  }
  // nuages très doux
  for (let i = 0; i < 1400; i++) {
    let x = wx + random(ww);
    let y = wy + random(wh);
    let n = noise(x * 0.003, y * 0.005, 200);
    if (n > 0.52) {
      fill(252, 250, 244, map(n, 0.52, 0.9, 0, 60, true));
      ellipse(x, y, random(50, 180), random(16, 54));
    }
  }
  // brume basse
  for (let i = 0; i < 500; i++) {
    let x = wx + random(ww);
    let y = wy + wh * random(0.72, 1.0);
    fill(206, 208, 198, random(10, 42));
    ellipse(x, y, random(80, 260), random(10, 34));
  }
  pop();

  // Une branche nue, à peine visible
  push();
  translate(wx + ww * 0.08, wy + wh * 1.02);
  stroke(70, 66, 60, 150);
  noFill();
  branch(0, 0, -HALF_PI - 0.5, 150, 5, 0);
  pop();

  // Meneaux
  push();
  noStroke();
  let barW = 16;
  fill(28, 25, 26);
  rect(wx + ww * 0.5 - barW / 2, wy, barW, wh);
  rect(wx, wy + wh * 0.42 - barW / 2, ww, barW);
  // reflets sur les montants
  fill(130, 124, 114, 110);
  rect(wx + ww * 0.5 - barW / 2, wy, 4, wh);
  rect(wx, wy + wh * 0.42 - barW / 2, ww, 4);
  pop();

  // Cadre de la fenêtre
  push();
  noFill();
  stroke(24, 21, 22);
  strokeWeight(26);
  rect(wx, wy, ww, wh);
  stroke(140, 132, 120, 120);
  strokeWeight(5);
  rect(wx - 11, wy - 11, ww + 22, wh + 22);
  pop();

  // Rideau à gauche de la fenêtre, soulevé par un courant d'air
  drawCurtain(wx - 70, wy - 40, wh + 120);
}

function branch(x, y, a, len, w, depth) {
  if (depth > 4 || len < 8) return;
  let x2 = x + cos(a) * len;
  let y2 = y + sin(a) * len;
  strokeWeight(w);
  line(x, y, x2, y2);
  branch(x2, y2, a - random(0.25, 0.6), len * random(0.55, 0.75), w * 0.6, depth + 1);
  branch(x2, y2, a + random(0.25, 0.6), len * random(0.55, 0.75), w * 0.6, depth + 1);
}

function drawCurtain(cx, cy, ch) {
  push();
  noStroke();
  let cw = 230;
  // masse du rideau
  for (let i = 0; i < 2600; i++) {
    let t = random();
    let y = cy + t * ch;
    // bord flottant
    let sway = sin(t * 3.0) * 60 * pow(t, 1.6);
    let x = cx - random(cw) + sway;
    let fold = sin((x + y * 0.3) * 0.045) * 0.5 + 0.5;
    let v = lerp(44, 168, fold * noise(x * 0.004, y * 0.004, 300));
    fill(v + 14, v + 8, v - 2, random(18, 60));
    push();
    translate(x, y);
    rotate(0.06 + sin(t * 3.0) * 0.14);
    rect(0, 0, random(8, 40), random(14, 60), 3);
    pop();
  }
  // bord lumineux
  for (let i = 0; i < 600; i++) {
    let t = random();
    let y = cy + t * ch;
    let sway = sin(t * 3.0) * 60 * pow(t, 1.6);
    let x = cx + sway;
    fill(226, 216, 198, random(20, 95));
    ellipse(x + random(-6, 10), y, random(4, 14), random(10, 34));
  }
  pop();
}

/* =========================================================
   RAYON DE LUMIÈRE
   ========================================================= */
function drawLightShaft() {
  push();
  blendMode(SCREEN);
  noStroke();
  let wx = W * 0.615, wy = H * 0.085;
  let ww = W * 0.335, wh = H * 0.405;

  // Deux volumes lumineux (les deux carreaux bas) projetés vers la gauche-bas
  let panes = [
    { x1: wx + 14,          x2: wx + ww * 0.5 - 8 },
    { x1: wx + ww * 0.5 + 8, x2: wx + ww - 14 }
  ];

  for (let p of panes) {
    for (let i = 0; i < 90; i++) {
      let a = map(i, 0, 90, 16, 1.2);
      let off = i * 2.0;
      fill(236, 228, 206, a * 0.5);
      beginShape();
      vertex(p.x1 - off * 0.1, wy + wh * 0.46);
      vertex(p.x2 + off * 0.1, wy + wh * 0.46);
      vertex(p.x2 - 300 + off * 1.4, H * 0.80);
      vertex(p.x1 - 620 - off * 1.4, H * 0.86);
      endShape(CLOSE);
    }
  }

  // Halo autour de la fenêtre
  for (let i = 0; i < 70; i++) {
    let r = i * 26;
    fill(220, 214, 196, 2.6);
    ellipse(wx + ww * 0.5, wy + wh * 0.45, ww + r, wh + r);
  }
  blendMode(BLEND);
  pop();
}

/* =========================================================
   LE LIT
   ========================================================= */
function drawBed(warm, shad) {
  let bx = W * 0.07;      // gauche
  let by = H * 0.60;      // haut du matelas (côté tête)
  let bw = W * 0.74;
  let bh = H * 0.26;

  // --- ombre portée au sol
  push();
  noStroke();
  for (let i = 0; i < 40; i++) {
    fill(10, 8, 10, 7);
    ellipse(bx + bw * 0.5, by + bh + 60 + i, bw * 1.02 + i * 2, 150 - i);
  }
  pop();

  // --- structure du lit (bois sombre)
  push();
  noStroke();
  // tête de lit
  fill(26, 21, 20);
  rect(bx - 40, by - 220, 46, 300, 6);
  fill(40, 33, 30);
  rect(bx - 40, by - 220, 12, 300, 6);
  for (let i = 0; i < 400; i++) {
    fill(random(30, 86), random(24, 66), random(20, 56), random(20, 70));
    rect(bx - 40 + random(46), by - 220 + random(300), random(3, 10), random(10, 40), 2);
  }
  // pied du lit, à droite
  fill(24, 20, 19);
  rect(bx + bw - 10, by + bh * 0.30, 44, 260, 6);
  // cadre bas
  fill(20, 17, 17);
  quad(bx - 10, by + bh * 0.82, bx + bw + 30, by + bh * 0.52,
       bx + bw + 30, by + bh * 0.52 + 70, bx - 10, by + bh * 0.82 + 86);
  pop();

  // --- matelas / masse du drap
  // Forme générale : trapèze en perspective
  let topL = { x: bx, y: by };
  let topR = { x: bx + bw, y: by - bh * 0.16 };
  let botR = { x: bx + bw + 20, y: by + bh * 0.62 };
  let botL = { x: bx - 24, y: by + bh * 0.95 };

  push();
  noStroke();
  fill(shad[0], shad[1], shad[2]);
  beginShape();
  vertex(topL.x, topL.y); vertex(topR.x, topR.y);
  vertex(botR.x, botR.y); vertex(botL.x, botL.y);
  endShape(CLOSE);
  pop();

  // --- le drap : champ de plis peint en touches
  // Hauteur du relief : un corps absent, creux en son milieu
  function sheetField(u, v) {
    // u: 0 (tête, gauche) -> 1 (pieds, droite) ; v: 0 (arrière) -> 1 (avant)
    let base = noise(u * 3.2, v * 3.2, 900) * 0.5;
    // creux du corps : une dépression allongée
    let cu = u - 0.42, cv = v - 0.48;
    let hollow = -0.55 * exp(-(cu * cu) / 0.055 - (cv * cv) / 0.035);
    // bourrelet de l'oreiller
    let pu = u - 0.10, pv = v - 0.42;
    let pillow = 0.65 * exp(-(pu * pu) / 0.004 - (pv * pv) / 0.045);
    // plis directionnels
    let folds = 0.22 * sin(u * 26 + noise(u * 4, v * 4) * 6) * (0.4 + v * 0.6);
    let folds2 = 0.14 * sin(v * 17 + u * 9);
    return base + hollow + pillow + folds + folds2;
  }

  let steps = 240;
  push();
  noStroke();
  for (let i = 0; i < steps; i++) {
    for (let j = 0; j < steps * 0.6; j++) {
      let u = (i + random(-0.5, 0.5)) / steps;
      let v = (j + random(-0.5, 0.5)) / (steps * 0.6);
      if (u < 0 || u > 1 || v < 0 || v > 1) continue;

      // bilinéaire sur le quadrilatère
      let xa = lerp(topL.x, topR.x, u), ya = lerp(topL.y, topR.y, u);
      let xb = lerp(botL.x, botR.x, u), yb = lerp(botL.y, botR.y, u);
      let x = lerp(xa, xb, v), y = lerp(ya, yb, v);

      let hgt = sheetField(u, v);
      // pseudo-normale -> éclairage depuis la fenêtre (haut droite)
      let e = 0.012;
      let dx = (sheetField(u + e, v) - sheetField(u - e, v)) / (2 * e);
      let dy = (sheetField(u, v + e) - sheetField(u, v - e)) / (2 * e);
      let lightDir = createVector(0.80, -0.45);
      let lum = -(dx * lightDir.x + dy * lightDir.y) * 0.28;
      lum = constrain(lum, -1, 1);

      // atténuation : plus sombre vers la gauche et l'avant
      let falloff = map(u, 0, 1, 0.55, 1.0) * map(v, 0, 1, 1.0, 0.62);
      // le rayon de lumière frappe la zone médiane-droite
      let inShaft = exp(-pow((u - 0.60) / 0.30, 2)) * exp(-pow((v - 0.45) / 0.42, 2));

      let val = 108 + lum * 150 + hgt * 38;
      val *= falloff;
      val += inShaft * 72;
      val = constrain(val, 8, 252);

      // teinte : chaude dans la lumière, froide dans l'ombre
      let r = val * 1.06 + inShaft * 16;
      let g = val * 0.99;
      let b = val * 0.93 + (1 - inShaft) * 16;

      push();
      translate(x, y);
      // les touches suivent la direction des plis
      rotate(atan2(dy, dx) * 0.22 + map(v, 0, 1, -0.22, 0.14));
      fill(r, g, b, random(42, 118));
      rect(0, 0, random(10, 36) * (0.6 + v * 0.8), random(3, 9), 2);
      pop();
    }
  }
  pop();

  // --- accents : arêtes claires sur les plis principaux
  push();
  noStroke();
  for (let k = 0; k < 2600; k++) {
    let u = random(), v = random();
    let hgt = sheetField(u, v);
    if (hgt < 0.38) continue;
    let xa = lerp(topL.x, topR.x, u), ya = lerp(topL.y, topR.y, u);
    let xb = lerp(botL.x, botR.x, u), yb = lerp(botL.y, botR.y, u);
    let x = lerp(xa, xb, v), y = lerp(ya, yb, v);
    let inShaft = exp(-pow((u - 0.60) / 0.30, 2)) * exp(-pow((v - 0.45) / 0.42, 2));
    let a = map(hgt, 0.38, 1.1, 10, 120, true) * (0.35 + inShaft);
    fill(246, 238, 222, a);
    push();
    translate(x, y);
    rotate(map(v, 0, 1, -0.2, 0.12));
    rect(0, 0, random(8, 30), random(2, 5), 2);
    pop();
  }
  pop();

  // --- ombres profondes dans le creux du corps
  push();
  noStroke();
  for (let k = 0; k < 2600; k++) {
    let u = random(), v = random();
    let hgt = sheetField(u, v);
    if (hgt > -0.10) continue;
    let xa = lerp(topL.x, topR.x, u), ya = lerp(topL.y, topR.y, u);
    let xb = lerp(botL.x, botR.x, u), yb = lerp(botL.y, botR.y, u);
    let x = lerp(xa, xb, v), y = lerp(ya, yb, v);
    let a = map(hgt, -0.10, -0.6, 8, 90, true);
    fill(42, 38, 44, a);
    push();
    translate(x, y);
    rotate(map(v, 0, 1, -0.2, 0.12));
    rect(0, 0, random(10, 40), random(3, 8), 2);
    pop();
  }
  pop();

  // --- le drap qui pend sur le bord avant
  push();
  noStroke();
  for (let i = 0; i < 4200; i++) {
    let u = random();
    let xTop = lerp(botL.x, botR.x, u);
    let yTop = lerp(botL.y, botR.y, u);
    let dropLen = 60 + 110 * (0.4 + 0.6 * noise(u * 7, 400));
    let t = pow(random(), 0.8);
    let x = xTop + sin(u * 30) * 10 * t;
    let y = yTop + t * dropLen;
    let fold = sin(u * 42 + noise(u * 9, 500) * 5) * 0.5 + 0.5;
    let inShaft = exp(-pow((u - 0.62) / 0.26, 2));
    let val = lerp(26, 150, fold) * (0.5 + inShaft * 0.8) * (1 - t * 0.45);
    fill(val * 1.05 + 10, val, val * 0.95 + 8, random(28, 95));
    push();
    translate(x, y);
    rotate(1.45 + random(-0.2, 0.2));
    rect(0, 0, random(8, 28), random(3, 8), 2);
    pop();
  }
  pop();

  // --- l'oreiller : son creux, le plus précis de la toile
  push();
  noStroke();
  let px = bx + bw * 0.11, py = by + bh * 0.23;
  for (let i = 0; i < 5200; i++) {
    let a = random(TWO_PI), rr = pow(random(), 0.6);
    let ex = cos(a) * rr * 170, ey = sin(a) * rr * 100;
    let x = px + ex, y = py + ey * 0.9 + ex * 0.10;
    // creux central
    let d = dist(ex, ey * 1.6, 0, 0) / 170;
    let depth = exp(-pow((d - 0.0) / 0.5, 2));
    let rim = exp(-pow((d - 0.85) / 0.25, 2));
    let val = 92 + rim * 110 - depth * 46 + noise(x * 0.02, y * 0.02, 600) * 48;
    fill(val * 1.08 + 12, val * 1.0 + 4, val * 0.92, random(34, 100));
    push();
    translate(x, y);
    rotate(a * 0.3 + 0.1);
    rect(0, 0, random(9, 30), random(3, 8), 2);
    pop();
  }
  // ombre du creux
  for (let i = 0; i < 900; i++) {
    let a = random(TWO_PI), rr = pow(random(), 1.6) * 0.55;
    let ex = cos(a) * rr * 170, ey = sin(a) * rr * 100;
    fill(60, 54, 58, random(10, 44));
    ellipse(px + ex, py + ey * 0.9 + ex * 0.10, random(14, 48), random(8, 20));
  }
  pop();
}

/* =========================================================
   POUSSIÈRE DANS LA LUMIÈRE
   ========================================================= */
function drawDustMotes() {
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 1500; i++) {
    // confiner approximativement au cône de lumière
    let t = random();
    let y = lerp(H * 0.20, H * 0.84, t);
    let xLeft = lerp(W * 0.60, W * 0.16, t);
    let xRight = lerp(W * 0.94, W * 0.72, t);
    let x = random(xLeft, xRight);
    let a = random(8, 85) * (1 - t * 0.35);
    fill(250, 244, 226, a);
    let s = random(1.2, 5.5);
    ellipse(x, y, s, s);
  }
  // quelques grains plus brillants
  for (let i = 0; i < 90; i++) {
    let t = random();
    let y = lerp(H * 0.22, H * 0.78, t);
    let x = random(lerp(W * 0.62, W * 0.22, t), lerp(W * 0.92, W * 0.70, t));
    fill(255, 252, 240, random(90, 190));
    ellipse(x, y, random(3, 7), random(3, 7));
  }
  blendMode(BLEND);
  pop();
}

/* =========================================================
   CHAISE VIDE
   ========================================================= */
function drawChair() {
  push();
  translate(W * 0.885, H * 0.70);
  rotate(-0.03);
  noStroke();

  // ombre
  for (let i = 0; i < 26; i++) {
    fill(10, 8, 10, 8);
    ellipse(-10, 215 + i * 2, 300 - i * 4, 70 - i);
  }

  // pieds
  for (let p of [[-95, 0], [75, 0], [-55, 40], [110, 40]]) {
    for (let i = 0; i < 180; i++) {
      let t = random();
      let x = p[0] + t * (p[1] === 40 ? -6 : 6) + random(-3, 3);
      let y = lerp(10, 215 - p[1] * 0.4, t);
      let lum = random(26, 78) + (x > 0 ? 24 : 0);
      fill(lum + 12, lum * 0.86, lum * 0.72, random(50, 140));
      rect(x, y, random(5, 12), random(8, 24), 2);
    }
  }

  // assise
  for (let i = 0; i < 1400; i++) {
    let x = random(-120, 135);
    let y = random(-24, 22) + x * 0.06;
    let lum = 40 + noise(x * 0.02, y * 0.03, 700) * 70 + map(x, -120, 135, -10, 45);
    fill(lum + 16, lum * 0.87, lum * 0.70, random(40, 120));
    push();
    translate(x, y);
    rotate(0.05);
    rect(0, 0, random(10, 34), random(4, 10), 2);
    pop();
  }

  // dossier
  for (let i = 0; i < 1600; i++) {
    let x = random(-110, 120);
    let y = random(-250, -30);
    // barreaux verticaux : garder seulement certaines bandes
    let band = (sin(x * 0.075) > 0.35) || abs(y + 240) < 22 || abs(y + 40) < 18;
    if (!band) continue;
    let lum = 34 + noise(x * 0.03, y * 0.02, 800) * 62 + map(x, -110, 120, -8, 50);
    fill(lum + 18, lum * 0.86, lum * 0.70, random(45, 135));
    rect(x, y, random(5, 14), random(8, 26), 2);
  }

  // reflets chauds venant de la fenêtre
  for (let i = 0; i < 420; i++) {
    let x = random(20, 135);
    let y = random(-250, 30);
    fill(236, 216, 180, random(10, 60));
    rect(x, y, random(3, 10), random(6, 20), 2);
  }
  pop();
}

/* =========================================================
   VIGNETTAGE, GRAIN, VERNIS
   ========================================================= */
function drawVignetteAndGrain() {
  // glacis chaud général
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = random(W), y = random(H);
    fill(228, 216, 198, 7);
    ellipse(x, y, random(200, 700), random(200, 700));
  }
  blendMode(BLEND);
  pop();

  // vignettage
  push();
  noStroke();
  for (let i = 0; i < 180; i++) {
    let a = map(i, 0, 180, 0, 11);
    fill(12, 10, 14, a);
    let inset = i * 7;
    beginShape();
    vertex(0, 0); vertex(W, 0); vertex(W, H); vertex(0, H);
    beginContour();
    vertex(inset, inset);
    vertex(inset, H - inset);
    vertex(W - inset, H - inset);
    vertex(W - inset, inset);
    endContour();
    endShape(CLOSE);
  }
  pop();

  // grain de toile
  push();
  noStroke();
  for (let i = 0; i < 26000; i++) {
    let x = random(W), y = random(H);
    let v = random(-1, 1);
    fill(v > 0 ? 255 : 0, abs(v) * 15);
    rect(x, y, random(1, 3), random(1, 3));
  }
  // trame horizontale/verticale du tissu
  for (let y = 0; y < H; y += 4) {
    fill(0, 7);
    rect(0, y, W, 1);
  }
  for (let x = 0; x < W; x += 4) {
    fill(255, 4);
    rect(x, 0, 1, H);
  }
  pop();

  // craquelures discrètes
  push();
  stroke(0, 26);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 140; i++) {
    let x = random(W), y = random(H);
    beginShape();
    for (let j = 0; j < 7; j++) {
      vertex(x, y);
      x += random(-34, 34);
      y += random(-34, 34);
    }
    endShape();
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(30, 28, 32);
  pixelDensity(1);

  // ---------- PALETTE ----------
  const WALL_D = [52, 48, 56];
  const WALL_L = [122, 116, 112];
  const LIGHT = [238, 226, 198];
  const SHEET_D = [120, 116, 120];
  const SHEET_L = [222, 215, 205];
  const FLOOR_D = [46, 38, 36];
  const FLOOR_L = [96, 80, 66];

  // ---------- WALL GRADIENT ----------
  // Light enters from window at upper-right
  const lightX = 1180, lightY = 520;
  for (let y = 0; y < 1360; y += 2) {
    for (let x = 0; x < width; x += 8) {
      let d = dist(x, y, lightX, lightY) / 1700;
      d = constrain(d, 0, 1);
      let t = pow(1 - d, 2.1);
      let n = noise(x * 0.0018, y * 0.0018) * 0.35 + 0.82;
      let r = lerp(WALL_D[0], WALL_L[0], t) * n;
      let g = lerp(WALL_D[1], WALL_L[1], t) * n;
      let b = lerp(WALL_D[2], WALL_L[2], t) * n;
      noStroke();
      fill(r, g, b);
      rect(x, y, 9, 3);
    }
  }

  // Wall subtle vertical stains / damp
  for (let i = 0; i < 70; i++) {
    let x = random(width);
    let w = random(20, 90);
    let h = random(200, 900);
    let y = random(-100, 900);
    noStroke();
    fill(40, 36, 42, random(6, 16));
    rect(x, y, w, h);
  }

  // ---------- FLOOR ----------
  const floorY = 1360;
  noStroke();
  for (let y = floorY; y < height; y += 2) {
    let t = (y - floorY) / (height - floorY);
    let d = dist(width * 0.72, y, lightX, lightY) / 1500;
    let lum = constrain(pow(1 - constrain(d, 0, 1), 2) * 0.9 + 0.1, 0, 1);
    let r = lerp(FLOOR_D[0], FLOOR_L[0], lum * (0.4 + t * 0.6));
    let g = lerp(FLOOR_D[1], FLOOR_L[1], lum * (0.4 + t * 0.6));
    let b = lerp(FLOOR_D[2], FLOOR_L[2], lum * (0.4 + t * 0.6));
    fill(r, g, b);
    rect(0, y, width, 3);
  }

  // Floorboards
  stroke(26, 20, 20, 90);
  strokeWeight(2);
  for (let i = 0; i < 14; i++) {
    let xTop = map(i, 0, 13, -600, 2200);
    let xBot = map(i, 0, 13, -1400, 3000);
    line(xTop, floorY, xBot, height);
  }
  // horizontal plank joints
  noStroke();
  for (let i = 0; i < 9; i++) {
    let yy = floorY + pow(i / 8, 1.7) * (height - floorY);
    fill(24, 18, 18, 55);
    rect(0, yy, width, 2.5);
  }

  // Skirting
  noStroke();
  fill(38, 33, 36);
  rect(0, floorY - 26, width, 28);
  fill(70, 64, 62, 120);
  rect(0, floorY - 26, width, 5);

  // ---------- WINDOW ----------
  const wx = 1010, wy = 230, ww = 430, wh = 700;

  // outer dark frame recess
  noStroke();
  fill(34, 31, 36);
  rect(wx - 34, wy - 34, ww + 68, wh + 68);

  // sky / outside: pale, washed, nothing to see
  for (let y = wy; y < wy + wh; y += 2) {
    let t = (y - wy) / wh;
    let r = lerp(246, 198, t);
    let g = lerp(241, 196, t);
    let b = lerp(226, 192, t);
    fill(r, g, b);
    rect(wx, y, ww, 3);
  }
  // faint distant haze bands
  noStroke();
  for (let i = 0; i < 26; i++) {
    let yy = wy + random(wh * 0.3, wh);
    fill(255, 255, 250, random(8, 26));
    rect(wx, yy, ww, random(3, 22));
  }
  // a horizon, very low contrast
  fill(186, 184, 180, 120);
  rect(wx, wy + wh * 0.74, ww, wh * 0.26);
  fill(170, 170, 168, 90);
  rect(wx, wy + wh * 0.74, ww, 6);

  // window mullions
  fill(46, 42, 44);
  rect(wx + ww / 2 - 9, wy, 18, wh);
  rect(wx, wy + wh * 0.42 - 9, ww, 18);
  // frame
  noFill();
  stroke(52, 47, 48);
  strokeWeight(26);
  rect(wx - 13, wy - 13, ww + 26, wh + 26);
  // lit inner edge of frame
  stroke(226, 214, 186, 150);
  strokeWeight(4);
  line(wx - 1, wy, wx - 1, wy + wh);
  line(wx, wy + wh + 1, wx + ww, wy + wh + 1);
  noStroke();

  // sill
  fill(96, 88, 80);
  rect(wx - 44, wy + wh + 20, ww + 88, 26);
  fill(190, 178, 152, 170);
  rect(wx - 44, wy + wh + 20, ww + 88, 7);
  fill(40, 35, 36, 120);
  rect(wx - 44, wy + wh + 46, ww + 88, 14);

  // ---------- CURTAIN (left of window, lifted slightly) ----------
  push();
  noStroke();
  let cx = wx - 60;
  for (let k = 0; k < 4; k++) {
    let a = 200 - k * 30;
    fill(208 - k * 22, 200 - k * 22, 186 - k * 20, a);
    beginShape();
    vertex(cx - 70 + k * 16, wy - 50);
    for (let y = wy - 50; y <= wy + wh + 180; y += 20) {
      let t = (y - wy) / wh;
      let sway = sin(t * 3.0 + k * 0.9) * (24 + t * 50) - t * t * 70;
      vertex(cx - 70 + k * 16 + sway, y);
    }
    for (let y = wy + wh + 180; y >= wy - 50; y -= 20) {
      let t = (y - wy) / wh;
      let sway = sin(t * 3.0 + k * 0.9) * (24 + t * 50) - t * t * 70;
      vertex(cx - 70 + k * 16 + sway + 46, y);
    }
    endShape(CLOSE);
  }
  // a wisp of curtain blown inward (breath)
  fill(232, 226, 210, 120);
  beginShape();
  vertex(cx - 10, wy + 120);
  bezierVertex(cx - 150, wy + 220, cx - 230, wy + 420, cx - 120, wy + 620);
  bezierVertex(cx - 60, wy + 480, cx - 30, wy + 320, cx + 10, wy + 180);
  endShape(CLOSE);
  pop();

  // ---------- LIGHT SHAFT ON FLOOR & BED ----------
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 40; i++) {
    let a = 7;
    fill(LIGHT[0], LIGHT[1], LIGHT[2], a);
    let spread = i * 3;
    beginShape();
    vertex(wx - 10 - spread * 0.2, wy + 40);
    vertex(wx + ww + 10 + spread * 0.2, wy + 40);
    vertex(wx + ww + 300 + spread, 2000);
    vertex(wx - 420 - spread, 2000);
    endShape(CLOSE);
  }
  pop();

  // ---------- BED ----------
  // geometry
  const bedL = 150, bedR = 1050, bedTop = 1000, bedBot = 1620;

  // shadow under bed
  noStroke();
  fill(20, 15, 16, 180);
  ellipse((bedL + bedR) / 2, bedBot + 40, (bedR - bedL) * 1.12, 170);

  // headboard (left, dark)
  push();
  fill(44, 34, 32);
  rect(bedL - 70, 760, 92, 760, 8);
  fill(60, 47, 42);
  rect(bedL - 70, 760, 92, 40, 8);
  // slight rim light
  fill(150, 136, 112, 90);
  rect(bedL + 14, 760, 8, 760);
  pop();

  // mattress block
  noStroke();
  fill(96, 90, 88);
  quad(bedL, bedTop + 70, bedR, bedTop + 10, bedR + 10, bedBot, bedL - 10, bedBot + 20);

  // bed frame foot
  fill(40, 31, 29);
  rect(bedR - 10, bedTop - 20, 60, 640, 6);
  fill(150, 138, 114, 70);
  rect(bedR - 10, bedTop - 20, 16, 640);

  // legs
  fill(32, 25, 24);
  rect(bedL - 46, 1520, 36, 110);
  rect(bedR + 6, 1600, 36, 90);

  // ---------- SHEETS ----------
  // Base sheet shape (crumpled white mass)
  const shade = (nx, ny) => {
    // returns 0..1 light factor based on distance to window light
    let d = dist(nx, ny, lightX, lightY + 200) / 1500;
    return constrain(pow(1 - constrain(d, 0, 1), 1.6), 0, 1);
  };

  // big sheet body
  push();
  noStroke();
  beginShape();
  vertex(bedL - 20, bedTop + 60);
  bezierVertex(bedL + 200, bedTop - 40, bedR - 300, bedTop - 30, bedR + 20, bedTop + 30);
  bezierVertex(bedR + 60, bedTop + 300, bedR + 40, bedBot - 120, bedR - 20, bedBot - 20);
  bezierVertex(bedR - 400, bedBot + 40, bedL + 150, bedBot + 50, bedL - 30, bedBot - 40);
  endShape(CLOSE);
  // fill via scanlines for gradient
  pop();

  // Draw sheet with per-pixel-ish bands inside a clipping shape approximated by redraw
  push();
  // we re-render the sheet region as many thin horizontal slabs modulated by folds
  for (let y = bedTop - 50; y < bedBot + 60; y += 3) {
    let ty = (y - (bedTop - 50)) / (bedBot + 60 - (bedTop - 50));
    // left and right boundary of sheet at this y
    let xl = lerp(bedL - 22, bedL - 34, ty) + sin(ty * 7 + 1.2) * 18;
    let xr = lerp(bedR + 24, bedR + 6, ty) + sin(ty * 5.5) * 14;
    // top cap curve
    if (y < bedTop + 40) {
      let k = (bedTop + 40 - y) / 90;
      xl += k * 260;
      xr -= k * 240;
    }
    if (y > bedBot - 20) {
      let k = (y - (bedBot - 20)) / 80;
      xl += k * 200;
      xr -= k * 220;
    }
    for (let x = xl; x < xr; x += 7) {
      // fold field
      let f = noise(x * 0.0035, y * 0.009) * 1.0 +
              noise(x * 0.011, y * 0.004) * 0.55;
      f = f / 1.55;
      // the hollow where a body lay: elongated depression
      let bodyCx = (bedL + bedR) * 0.47;
      let bodyCy = (bedTop + bedBot) * 0.52;
      let dxn = (x - bodyCx) / 420;
      let dyn = (y - bodyCy) / 250;
      let hollow = exp(-(dxn * dxn + dyn * dyn) * 1.9);
      // pillow depression near head (left)
      let pdx = (x - (bedL + 130)) / 190;
      let pdy = (y - (bedTop + 180)) / 120;
      let pillowHollow = exp(-(pdx * pdx + pdy * pdy) * 2.2);

      let lum = shade(x, y);
      let v = 0.30 + lum * 0.72 + (f - 0.5) * 0.46;
      v -= hollow * 0.30;
      v -= pillowHollow * 0.16;
      v = constrain(v, 0, 1.25);

      let r = lerp(SHEET_D[0], SHEET_L[0], constrain(v, 0, 1)) * (v > 1 ? v : 1);
      let g = lerp(SHEET_D[1], SHEET_L[1], constrain(v, 0, 1)) * (v > 1 ? v : 1);
      let b = lerp(SHEET_D[2], SHEET_L[2], constrain(v, 0, 1)) * (v > 1 ? v : 1);
      // cool shadow tint in troughs
      if (v < 0.45) { b += 22; r -= 8; }
      noStroke();
      fill(r, g, b);
      rect(x, y, 8, 4);
    }
  }
  pop();

  // Sharper fold ridges (impasto-ish strokes)
  push();
  for (let i = 0; i < 260; i++) {
    let x0 = random(bedL + 10, bedR - 10);
    let y0 = random(bedTop + 30, bedBot - 30);
    let f = noise(x0 * 0.0035, y0 * 0.009);
    let lum = shade(x0, y0);
    let len = random(40, 220);
    let ang = -0.35 + noise(x0 * 0.002, y0 * 0.002) * 1.1;
    let bright = f > 0.52;
    strokeWeight(random(2, 7));
    if (bright) stroke(245, 238, 224, 20 + lum * 110);
    else stroke(70, 66, 74, 40 + (1 - lum) * 70);
    let px = x0, py = y0;
    noFill();
    beginShape();
    for (let s = 0; s < len; s += 10) {
      let a = ang + noise(px * 0.004, py * 0.004) * 0.8 - 0.4;
      px += cos(a) * 10;
      py += sin(a) * 10;
      vertex(px, py);
    }
    endShape();
  }
  pop();

  // ---------- PILLOW ----------
  push();
  noStroke();
  // pillow mass
  for (let y = bedTop + 40; y < bedTop + 330; y += 3) {
    let t = (y - (bedTop + 40)) / 290;
    let cx2 = bedL + 170;
    let halfW = 210 * sin(PI * constrain(t * 0.9 + 0.08, 0, 1)) + 40;
    for (let x = cx2 - halfW; x < cx2 + halfW; x += 7) {
      let nx = (x - cx2) / halfW;
      let dome = sqrt(max(0, 1 - nx * nx));
      let lum = shade(x, y);
      let f = noise(x * 0.006, y * 0.012);
      // the dent of a head
      let hd = exp(-(pow((x - (cx2 + 10)) / 130, 2) + pow((y - (bedTop + 165)) / 85, 2)) * 1.8);
