  // final warm unifying glaze
  push();
  blendMode(OVERLAY);
  noStroke();
  fill(140, 120, 90, 26);
  rect(0, 0, width, height);
  pop();
}

// "La chambre qui respire encore"
// Huile imaginaire — p5.js 1.11

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

// ---------- helpers ----------

function vnoise(x, y, s) {
  return noise(x * s, y * s);
}

// dépose une tache de peinture douce
function blob(x, y, r, col, a, irregular) {
  push();
  noStroke();
  for (let i = 0; i < 7; i++) {
    let t = i / 6;
    let rr = r * (1 - t * 0.85);
    fill(red(col), green(col), blue(col), a * (0.14 + t * 0.5));
    if (irregular) {
      beginShape();
      for (let ang = 0; ang < TWO_PI; ang += 0.5) {
        let n = noise(x * 0.01 + cos(ang) * 0.6, y * 0.01 + sin(ang) * 0.6, i * 0.3);
        let rad = rr * (0.7 + n * 0.7);
        vertex(x + cos(ang) * rad, y + sin(ang) * rad * 0.8);
      }
      endShape(CLOSE);
    } else {
      ellipse(x, y, rr * 2, rr * 1.7);
    }
  }
  pop();
}

// coup de brosse directionnel
function stroke2(x1, y1, x2, y2, w, col, a) {
  push();
  noStroke();
  let steps = max(3, int(dist(x1, y1, x2, y2) / 4));
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    let taper = sin(t * PI);
    let ww = w * (0.35 + taper * 0.85);
    fill(red(col), green(col), blue(col), a * (0.35 + taper * 0.65));
    ellipse(x + random(-1.2, 1.2), y + random(-1.2, 1.2), ww, ww * 0.9);
  }
  pop();
}

function main() {}

// ---------- draw ----------

function draw() {
  randomSeed(1);
  noiseSeed(1);

  const W = width, H = height;

  // =========================================================
