  for (let y = 0; y < H; y += 2) {
    let t = y / H;
    // haut plus clair (lumière), bas plus sourd
    let r = lerp(196, 128, t) - 10;
    let g = lerp(194, 126, t) - 4;
    let b = lerp(178, 118, t);
    fill(r, g, b);
    rect(0, y, W, 2.2);
  }

  // empâtement du mur
  for (let i = 0; i < 24000; i++) {
    let x = random(W), y = random(H);
    let n = vnoise(x, y, 0.0035);
    let n2 = vnoise(x + 900, y - 400, 0.013);
    let v = (n - 0.5) * 60 + (n2 - 0.5) * 26;
    noStroke();
    fill(200 + v, 198 + v * 0.95, 182 + v * 0.8, 26);
    ellipse(x, y, random(3, 13), random(3, 10));
  }

  // =========================================================
  // 2. LA FENÊTRE (haut gauche) : source de lumière
