      let t = (y - wy) / wh;
      let sw = sin(t * 3.0 + layer * 1.1) * (26 + t * 100) + t * 170 + noise(y * 0.01, layer) * 40;
      vertex(baseX + sw, y);
    }
    vertex(baseX + 360, wy + wh + 150);
    vertex(baseX - 80, wy + wh + 150);
    endShape(CLOSE);
  }
  pop();

  // =========================================================
  // 3. NAPPE DE LUMIÈRE : le rayon oblique qui traverse
  // =========================================================
  push();
  noStroke();
  blendMode(SCREEN);
  for (let i = 0; i < 1500; i++) {
    let t = random();
    // trajet du rayon : de la fenêtre vers le bas-droite
