  let sheet = [];
  for (let x = -40; x <= W + 40; x += 10) {
    let base = bedTop + 60;
    // relief : oreiller à droite, creux du corps au centre
    let pillow = 140 * exp(-pow((x - 1180) / 300, 2));
    let bodyLift = 60 * exp(-pow((x - 700) / 420, 2));
    let fold = noise(x * 0.004) * 50;
    sheet.push([x, base - pillow - bodyLift - fold + 20]);
  }

  push();
  noStroke();
  fill(226, 222, 208);
  beginShape();
  for (let p of sheet) vertex(p[0], p[1]);
  vertex(W + 40, bedBot + 120);
  vertex(-40, bedBot + 120);
  endShape(CLOSE);
  pop();

  // modelé du drap : lumière venant de la fenêtre (haut gauche)
  for (let i = 0; i < 52000; i++) {
    let x = random(-20, W + 20);
