    let idx = constrain(int((x + 40) / 10), 0, sheet.length - 1);
    if (y < sheet[idx][1]) continue;

    // champ de plis
    let f1 = noise(x * 0.0022, y * 0.0045);
    let f2 = noise(x * 0.009 + 50, y * 0.004 + 80);
    let folds = sin(f1 * 14 + x * 0.004 - y * 0.002) * 0.5 + 0.5;

    // creux du corps : dépression ovale au centre-gauche
    let cx = 760, cy = 1430;
    let dxx = (x - cx) / 430, dyy = (y - cy) / 230;
    let body = exp(-(dxx * dxx + dyy * dyy) * 1.5);

    // ombre de la dépression : plus sombre en bas-droite du creux
    let bodyShade = body * (0.45 + 0.55 * constrain((dxx * 0.7 + dyy * 0.9), -1, 1));

    // éclairement global
    let light = 1 - (y - bedTop) / (bedBot - bedTop) * 0.55;
    light -= (x / W) * 0.18;

    let v = 236 * light + folds * 26 + (f2 - 0.5) * 30 - bodyShade * 86;

    let rr = v + 6;
    let gg = v + 2;
    let bb = v - 10;

    // reflet froid de la fenêtre dans les creux
    if (folds < 0.35) { bb += 16; rr -= 6; }
    // chaleur de la lumière sur les crêtes
    if (folds > 0.72) { rr += 12; gg += 6; bb -= 6; }

    fill(rr, gg, bb, random(16, 46));
    ellipse(x, y, random(6, 26), random(4, 14));
