    // dépression de la tête
    let head = exp(-(pow((x - 1215) / 120, 2) + pow((y - 1160) / 72, 2)));
    let light = 1 - d2 * 0.3 - (x - 900) / 1400 * 0.25;
    let v = 240 * light - head * 78 + noise(x * 0.01, y * 0.01) * 24;
    fill(v + 6, v + 3, v - 8, random(18, 48));
