  }
  // liseré clair sur le bord supérieur gauche
  for (let i = 0; i < 1400; i++) {
    let a = random(PI * 0.75, PI * 1.85);
    let x = 1200 + cos(a) * 290 * random(0.93, 1.03);
    let y = 1150 + sin(a) * 155 * random(0.93, 1.03);
