    ellipse(chx + random(-60, 260), 1900 + random(-30, 50), random(30, 150), random(8, 26));
  }
  // montants
  function woodBar(x1, y1, x2, y2, w) {
    for (let i = 0; i < 160; i++) {
      let t = random();
      let x = lerp(x1, x2, t) + random(-w / 2, w / 2);
      let y = lerp(y1, y2, t) + random(-w / 2, w / 2);
      let n = noise(x * 0.01, y * 0.01);
      let lit = (x < chx + 90) ? 1.5 : 0.75;
      fill(96 * n * lit + 28, 74 * n * lit + 22, 58 * n * lit + 18, random(60, 150));
      ellipse(x, y, w * random(0.5, 1.1), w * random(0.5, 1.1));
    }
  }
  // dossier
  woodBar(chx + 10, 1180, chx + 24, 1520, 18);
  woodBar(chx + 200, 1200, chx + 206, 1520, 18);
  woodBar(chx + 10, 1200, chx + 202, 1222, 16);
  woodBar(chx + 12, 1300, chx + 204, 1320, 13);
  // assise
  for (let i = 0; i < 3000; i++) {
    let x = chx + random(-14, 230);
    let y = 1500 + random(0, 46) + (x - chx) * 0.03;
    let n = noise(x * 0.008, y * 0.02);
    fill(118 * n + 40, 94 * n + 32, 74 * n + 26, random(50, 120));
    ellipse(x, y, random(6, 22), random(3, 8));
  }
  // pieds
  woodBar(chx + 4, 1540, chx - 6, 1880, 16);
  woodBar(chx + 206, 1548, chx + 224, 1880, 16);
  woodBar(chx + 120, 1530, chx + 128, 1840, 13);
  pop();

  // châle / tissu oublié sur la chaise — tache sourde, rouge éteint
  push();
  noStroke();
  for (let i = 0; i < 5200; i++) {
    let t = random();
    let x = chx + 30 + t * 160 + random(-50, 50);
    let y = 1420 + t * 60 + random(-70, 180) + pow(t, 2) * 120;
    let n = noise(x * 0.006, y * 0.006);
    let lit = x < chx + 110 ? 1.25 : 0.8;
    fill(126 * lit * n + 46, 56 * lit * n + 24, 48 * lit * n + 26, random(22, 70));
    ellipse(x, y, random(8, 30), random(6, 20));
  }
  pop();

  // =========================================================
  // 7. POUSSIÈRE EN SUSPENSION dans le rayon
  // =========================================================
  push();
  noStroke();
  for (let i = 0; i < 2000; i++) {
    let t = random();
    let x = random(wx - 60, W);
    let y = random(wy + 60, bedBot);
    // densité dans l'axe du rayon
    let axis = (x - wx) * 0.62 - (y - wy - 200) * 0.78;
    let band = exp(-pow(axis / 420, 2));
    if (random() > band * 0.95 + 0.03) continue;
    let s = random(1.5, 6);
    fill(255, 252, 230, random(50, 190) * band);
    ellipse(x, y, s, s);
    if (random() < 0.12) {
      fill(255, 255, 245, 40);
      ellipse(x, y, s * 3.5, s * 3.5);
    }
  }
  pop();

  // =========================================================
  // 8. VERRE D'EAU sur une petite table à droite
  // =========================================================
  push();
  noStroke();
  // table
  fill(66, 52, 42);
  rect(1420, 1340, 220, 30, 4);
  for (let i = 0; i < 900; i++) {
    let x = random(1420, 1640), y = random(1340, 1372);
    let n = noise(x * 0.01, y * 0.02);
    fill(118 * n + 30, 92 * n + 24, 72 * n + 20, 60);
    ellipse(x, y, random(10, 40), random(2, 5));
  }
  fill(54, 42, 34);
  rect(1448, 1370, 24, 460);
  rect(1588, 1370, 24, 460);

  // verre
  let gx = 1512, gy = 1240, gw = 96, gh = 150;
  for (let i = 0; i < 4500; i++) {
    let x = gx + random(-gw / 2, gw / 2);
    let y = gy + random(0, gh);
    let edge = abs(x - gx) / (gw / 2);
    let water = y > gy + gh * 0.45;
    let v = water ? 186 : 206;
    v += pow(edge, 3) * 50;
    let aa = water ? random(25, 70) : random(10, 34);
    fill(v - 10, v, v - 4, aa);
    ellipse(x, y, random(3, 10), random(3, 10));
  }
  // surface de l'eau
  for (let i = 0; i < 400; i++) {
    let x = gx + random(-gw / 2 + 4, gw / 2 - 4);
    fill(240, 248, 244, random(40, 120));
    ellipse(x, gy + gh * 0.45 + random(-3, 3), random(4, 14), random(2, 5));
  }
  // reflet vertical
  for (let i = 0; i < 300; i++) {
    fill(255, 255, 250, random(40, 130));
    ellipse(gx - 28 + random(-4, 4), gy + random(6, gh - 10), random(3, 8), random(8, 22));
  }
  // base
  for (let i = 0; i < 500; i++) {
    let a = random(TWO_PI);
    fill(220, 228, 224, random(20, 60));
    ellipse(gx + cos(a) * random(0, gw / 2), gy + gh - 4 + sin(a) * 7, random(4, 12), random(3, 7));
  }
  pop();

  // =========================================================
  // 9. UNIFICATION : glacis, vignettage, grain, craquelures
  // =========================================================

  // glacis chaud léger
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = random(W), y = random(H);
    let n = vnoise(x, y, 0.0016);
    fill(255 - (1 - n) * 24, 250 - (1 - n) * 26, 238 - (1 - n) * 20, 18);
    ellipse(x, y, random(120, 520), random(100, 420));
  }
  pop();

  // vignettage
  push();
  noStroke();
  for (let i = 0; i < 150; i++) {
    let t = i / 150;
    fill(36, 30, 26, 4);
    let m = t * 520;
    rect(0, 0, W, m * 0.5);
    rect(0, H - m, W, m);
    rect(0, 0, m * 0.7, H);
    rect(W - m, 0, m, H);
  }
  pop();

  // regain de lumière au coin fenêtre (pour contrer le vignettage)
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = wx + ww * 0.5 + random(-500, 500);
    let y = wy + wh * 0.4 + random(-460, 460);
    let d = dist(x, y, wx + ww * 0.5, wy + wh * 0.4);
    fill(255, 250, 225, map(d, 0, 700, 10, 0, true));
    ellipse(x, y, random(80, 300), random(80, 300));
  }
  pop();

  // grain de toile
  push();
  noStroke();
  for (let i = 0; i < 60000; i++) {
    let x = random(W), y = random(H);
    let v = random(-16, 16);
    fill(128 + v, 126 + v, 120 + v, 12);
    rect(x, y, random(1, 3), random(1, 3));
  }
  // trame horizontale/verticale de la toile
  for (let y = 0; y < H; y += 4) {
    fill(255, 255, 255, 5);
    rect(0, y, W, 1);
    fill(0, 0, 0, 4);
    rect(0, y + 2, W, 1);
  }
  for (let x = 0; x < W; x += 4) {
    fill(255, 255, 255, 4);
    rect(x, 0, 1, H);
    fill(0, 0, 0, 3);
    rect(x + 2, 0, 1, H);
  }
  pop();

  // craquelures fines
  push();
  noFill();
  for (let i = 0; i < 90; i++) {
    let x = random(W), y = random(H);
    let a = random(TWO_PI);
    stroke(48, 42, 36, random(14, 40));
    strokeWeight(random(0.6, 1.5));
    beginShape();
    for (let s = 0; s < 26; s++) {
      vertex(x, y);
      a += random(-0.7, 0.7);
      x += cos(a) * random(5, 22);
      y += sin(a) * random(5, 22);
    }
    endShape();
  }
  pop();

  // bord de toile, pigment plus dense
  push();
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let e = int(random(4));
    let x, y;
    if (e === 0) { x = random(W); y = random(26); }
    else if (e === 1) { x = random(W); y = H - random(26); }
    else if (e === 2) { x = random(26); y = random(H); }
    else { x = W - random(26); y = random(H); }
    fill(40, 34, 30, random(12, 50));
    ellipse(x, y, random(4, 18), random(4, 18));
  }
  pop();
}

// Retreating Tide
let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(238, 233, 224);

  drawSky();
  drawLight();
  drawSand();
  drawHollow();
  drawTideLines();
  drawFoamEdge();
  drawWater();
  drawDissolvingTraces();
  drawDust();
  vignette();
  grain();
}

// ---------- sky / upper emptiness ----------
function drawSky() {
  let horizon = H * 0.42;
  noStroke();
  for (let y = 0; y < horizon; y++) {
    let t = y / horizon;
    let r = lerp(246, 226, pow(t, 0.8));
    let g = lerp(243, 221, pow(t, 0.8));
    let b = lerp(236, 213, pow(t, 0.8));
    fill(r, g, b);
    rect(0, y, W, 1);
  }
  // soft cloud bands
  for (let i = 0; i < 14; i++) {
    let cy = random(H * 0.03, horizon * 0.95);
    let h = random(18, 70);
    let a = random(6, 18);
    fill(255, 255, 252, a);
    for (let k = 0; k < 3; k++) {
      ellipse(random(-200, W + 200), cy + random(-10, 10), random(700, 1700), h);
    }
  }
}

function drawLight() {
  // a faint high glow, like late light
  noStroke();
  let cx = W * 0.62, cy = H * 0.12;
  for (let r = 900; r > 0; r -= 12) {
    let a = map(r, 0, 900, 16, 0);
    fill(255, 252, 240, a);
    ellipse(cx, cy, r * 2.1, r * 1.5);
  }
}

// ---------- sand ----------
function drawSand() {
  let horizon = H * 0.42;
  noStroke();
  for (let y = horizon; y < H; y++) {
    let t = (y - horizon) / (H - horizon);
    let r = lerp(222, 199, t);
    let g = lerp(212, 184, t);
    let b = lerp(196, 166, t);
    fill(r, g, b);
    rect(0, y, W, 1);
  }

  // sand mottling with noise
  loadPixels();
  for (let y = floor(horizon); y < H; y += 1) {
    for (let x = 0; x < W; x += 1) {
      let n = noise(x * 0.004, y * 0.004);
      let m = noise(x * 0.02, y * 0.02) * 0.5;
      let v = (n + m - 0.75) * 26;
      let idx = 4 * (y * W + x);
      pixels[idx] = constrain(pixels[idx] + v, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + v, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + v * 0.9, 0, 255);
    }
  }
  updatePixels();
}

// ---------- the hollow: a body-shaped depression ----------
function bodyOutline(t) {
  // parametric closed-ish silhouette of a reclining figure, returns point
  // built from a set of control ellipses blended
  return null;
}

function bodyField(x, y) {
  // metaball-ish field of a reclining body, centered around (cx, cy)
  let parts = BODY_PARTS;
  let s = 0;
  for (let p of parts) {
    let dx = (x - p.x) * cos(-p.a) - (y - p.y) * sin(-p.a);
    let dy = (x - p.x) * sin(-p.a) + (y - p.y) * cos(-p.a);
    let d = (dx * dx) / (p.rx * p.rx) + (dy * dy) / (p.ry * p.ry);
    s += 1 / (0.35 + d * d);
  }
  return s;
}

let BODY_PARTS;

function buildBody() {
  let cx = W * 0.47, cy = H * 0.665;
  BODY_PARTS = [
    { x: cx - 330, y: cy - 60, rx: 70, ry: 62, a: 0 },        // head
    { x: cx - 240, y: cy - 20, rx: 48, ry: 40, a: 0.2 },      // neck
    { x: cx - 120, y: cy + 10, rx: 150, ry: 92, a: 0.05 },    // chest
    { x: cx + 60, y: cy + 36, rx: 140, ry: 78, a: -0.03 },    // belly
    { x: cx + 215, y: cy + 48, rx: 95, ry: 72, a: -0.05 },    // hips
    { x: cx + 385, y: cy + 60, rx: 130, ry: 48, a: 0.03 },    // thigh
    { x: cx + 560, y: cy + 78, rx: 120, ry: 36, a: 0.06 },    // shin
    { x: cx + 665, y: cy + 92, rx: 48, ry: 26, a: 0.15 },     // foot
    { x: cx - 60, y: cy + 110, rx: 120, ry: 32, a: 0.12 },    // arm
    { x: cx + 110, y: cy + 140, rx: 70, ry: 26, a: 0.08 },    // hand
  ];
}

function drawHollow() {
  buildBody();
  push();
  // shadowed depression: darker lower-right side, lighter rim upper-left
  let threshold = 1.5;
  loadPixels();
  let x0 = 60, x1 = W - 40, y0 = floor(H * 0.50), y1 = floor(H * 0.88);
  for (let y = y0; y < y1; y++) {
    for (let x = x0; x < x1; x++) {
      let nx = x + (noise(x * 0.006, y * 0.006, 10) - 0.5) * 46;
      let ny = y + (noise(x * 0.006, y * 0.006, 20) - 0.5) * 46;
      let f = bodyField(nx, ny);
      if (f > threshold * 0.55) {
        // gradient of depth
        let depth = constrain(map(f, threshold * 0.55, threshold * 2.4, 0, 1), 0, 1);
        depth = pow(depth, 0.85);

        // fake lighting: light from upper-left
        let fx = bodyField(nx + 6, ny) - bodyField(nx - 6, ny);
        let fy = bodyField(nx, ny + 6) - bodyField(nx, ny - 6);
        let lightTerm = (-fx * 0.7 - fy * 0.7) * 26;
        lightTerm = constrain(lightTerm, -30, 30);

        let shade = -depth * 26 + lightTerm;
        // water filling the lower part of the hollow
        let fillLevel = H * 0.70;
        let wet = 0;
        if (y > fillLevel - 10) {
          wet = constrain(map(y, fillLevel - 10, fillLevel + 70, 0, 1), 0, 1) * depth;
        }

        let idx = 4 * (y * W + x);
        let r = pixels[idx], g = pixels[idx + 1], b = pixels[idx + 2];
        r = r + shade - wet * 34;
        g = g + shade - wet * 22;
        b = b + shade * 0.8 - wet * 2;
        pixels[idx] = constrain(r, 0, 255);
        pixels[idx + 1] = constrain(g, 0, 255);
        pixels[idx + 2] = constrain(b, 0, 255);
      }
    }
  }
  updatePixels();
  pop();

  // faint rim highlight along the upper edge
  push();
  noFill();
  for (let pass = 0; pass < 2; pass++) {
    stroke(255, 250, 238, 26 - pass * 10);
    strokeWeight(2 + pass * 3);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.01) {
      // march outward to find contour (cheap): sample radial from body center
      let cx = W * 0.47 + 120, cy = H * 0.665 + 40;
      let rr = 0, found = -1;
      for (let r = 40; r < 820; r += 6) {
        let x = cx + cos(a) * r, y = cy + sin(a) * r * 0.9;
        if (bodyField(x, y) < 1.2) { found = r; break; }
      }
      if (found > 0) {
        let x = cx + cos(a) * found;
        let y = cy + sin(a) * found * 0.9;
        if (sin(a) < 0.25) vertex(x, y);
        else endShape();
        if (sin(a) >= 0.25) beginShape();
      }
    }
    endShape();
  }
  pop();
}

// ---------- tide lines on sand ----------
function drawTideLines() {
  push();
  noFill();
  for (let i = 0; i < 26; i++) {
    let baseY = map(i, 0, 25, H * 0.44, H * 0.99);
    let amp = map(i, 0, 25, 6, 30);
    let a = map(i, 0, 25, 14, 34);
    stroke(255, 250, 240, a);
    strokeWeight(map(i, 0, 25, 0.8, 2.4));
    beginShape();
    for (let x = -20; x <= W + 20; x += 8) {
      let y = baseY + (noise(x * 0.0022, i * 0.6) - 0.5) * amp * 2
                    + (noise(x * 0.01, i * 1.3) - 0.5) * amp * 0.5;
      curveVertex(x, y);
    }
    endShape();

    // shadow beneath line
    stroke(140, 120, 100, a * 0.5);
    strokeWeight(map(i, 0, 25, 0.6, 1.6));
    beginShape();
    for (let x = -20; x <= W + 20; x += 8) {
      let y = 3 + baseY + (noise(x * 0.0022, i * 0.6) - 0.5) * amp * 2
                    + (noise(x * 0.01, i * 1.3) - 0.5) * amp * 0.5;
      curveVertex(x, y);
    }
    endShape();
  }
  pop();
}

// ---------- the water's leading edge ----------
function foamY(x) {
  return H * 0.845
    + (noise(x * 0.0016, 77) - 0.5) * 120
    + (noise(x * 0.006, 33) - 0.5) * 46
    + (noise(x * 0.02, 99) - 0.5) * 14;
}

function drawFoamEdge() {
  push();
  // wet sand band above water
  noStroke();
  for (let x = 0; x < W; x += 2) {
    let fy = foamY(x);
    for (let d = 0; d < 90; d += 2) {
      let a = map(d, 0, 90, 40, 0);
      fill(150, 132, 112, a * 0.5);
      rect(x, fy - d, 2, 2);
    }
  }
  pop();
}

function drawWater() {
  push();
  noStroke();
  // water body below foam line
  for (let x = 0; x < W; x += 1) {
    let fy = foamY(x);
    for (let y = fy; y < H; y += 1) {
      let t = constrain((y - fy) / (H - fy), 0, 1);
      let r = lerp(196, 150, t);
      let g = lerp(198, 158, t);
      let b = lerp(196, 158, t);
      // shimmer
      let n = (noise(x * 0.01, y * 0.03, 5) - 0.5) * 22;
      fill(r + n, g + n, b + n, 230);
      rect(x, y, 1, 1);
    }
  }

  // foam lace
  for (let i = 0; i < 2600; i++) {
    let x = random(W);
    let fy = foamY(x);
    let y = fy + randomGaussian(0, 16);
    let s = random(1, 7);
    fill(255, 254, 250, random(40, 150));
    ellipse(x, y, s, s * random(0.4, 0.9));
  }
  // thin bright line
  noFill();
  stroke(255, 255, 252, 130);
  strokeWeight(2);
  beginShape();
  for (let x = -10; x <= W + 10; x += 6) curveVertex(x, foamY(x));
  endShape();

  // water reflections / horizontal streaks
  for (let i = 0; i < 180; i++) {
    let y = random(H * 0.85, H);
    let x = random(W);
    let len = random(40, 320);
    stroke(255, 255, 250, random(8, 40));
    strokeWeight(random(0.6, 2.2));
    line(x, y, x + len, y + random(-2, 2));
  }
  pop();
}

// ---------- traces being dissolved by water ----------
function drawDissolvingTraces() {
  push();
  // lower part of the hollow's outline broken into dashes by the water
  noFill();
  for (let i = 0; i < 400; i++) {
    let x = random(W * 0.1, W * 0.95);
    let y = random(H * 0.78, H * 0.9);
    let f = bodyField(x, y);
    if (f > 1.0 && f < 1.9) {
      stroke(120, 106, 92, random(20, 70));
      strokeWeight(random(0.8, 2.4));
      let a = random(TWO_PI);
      let l = random(4, 20);
      line(x, y, x + cos(a) * l, y + sin(a) * l);
    }
  }

  // faint echo outlines of the body, further up, nearly erased
  for (let k = 1; k <= 3; k++) {
    let off = -k * 150;
    stroke(255, 250, 240, 20 - k * 4);
    strokeWeight(1.4);
    noFill();
    for (let i = 0; i < 900; i++) {
      let x = random(W * 0.05, W * 0.98);
      let y = random(H * 0.48, H * 0.78);
      let f = bodyField(x, y - off);
      if (f > 1.35 && f < 1.55) point(x, y);
    }
  }
  pop();
}

// ---------- airborne dust / scattered light ----------
function drawDust() {
  push();
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(W);
    let y = random(H * 0.02, H * 0.6);
    let s = random(1, 4.2);
    fill(255, 253, 245, random(10, 70));
    ellipse(x, y, s, s);
  }
  pop();
}

function vignette() {
  push();
  noFill();
  for (let r = 0; r < 420; r++) {
    stroke(60, 50, 44, map(r, 0, 420, 24, 0));
    strokeWeight(2);
    rect(-r, -r, W + 2 * r, H + 2 * r);
  }
  pop();
}

function grain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-9, 9);
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

// "退潮" — Ebb
let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(230, 226, 218);

  drawSky();
  drawSeaBand();
  drawWetSand();
  drawRipples();
  drawHollow();
  drawFoamLine();
  drawLightShaft();
  grainAndVignette();
}

/* ---------- SKY ---------- */
function drawSky() {
  let horizon = H * 0.30;
  for (let y = 0; y < horizon; y++) {
    let t = y / horizon;
    // pale morning: cool grey-blue high, warm milky low
    let r = lerp(190, 232, pow(t, 0.8));
    let g = lerp(196, 224, pow(t, 0.8));
    let b = lerp(204, 212, pow(t, 0.8));
    stroke(r, g, b);
    line(0, y, W, y);
  }
  // soft cloud veils
  noStroke();
  for (let i = 0; i < 90; i++) {
    let cy = random(horizon * 0.05, horizon * 0.95);
    let cx = random(-200, W + 200);
    let w = random(300, 1100);
    let h = random(12, 70);
    let a = map(cy, 0, horizon, 14, 4);
    fill(255, 255, 252, a);
    ellipse(cx, cy, w, h);
  }
  for (let i = 0; i < 40; i++) {
    let cy = random(horizon * 0.1, horizon * 0.8);
    fill(176, 184, 194, random(4, 10));
    ellipse(random(W), cy, random(400, 1300), random(10, 40));
  }
}

/* ---------- SEA ---------- */
function drawSeaBand() {
  let horizon = H * 0.30;
  let seaBottom = H * 0.395;
  for (let y = horizon; y < seaBottom; y++) {
    let t = (y - horizon) / (seaBottom - horizon);
    let r = lerp(150, 196, t);
    let g = lerp(163, 203, t);
    let b = lerp(172, 203, t);
    stroke(r, g, b);
    line(0, y, W, y);
  }
  // horizon crisp line
  stroke(140, 152, 162, 150);
  strokeWeight(1.2);
  line(0, horizon, W, horizon);

  // glints on water
  noStroke();
  for (let i = 0; i < 700; i++) {
    let y = random(horizon + 2, seaBottom);
    let t = (y - horizon) / (seaBottom - horizon);
    let x = random(W);
    let a = random(10, 70) * (0.3 + 0.7 * t);
    fill(255, 255, 250, a);
    rect(x, y, random(4, 46), 1);
  }
  // distant wave lines
  for (let i = 0; i < 26; i++) {
    let y = lerp(horizon + 6, seaBottom - 4, i / 26) + random(-2, 2);
    stroke(255, 255, 252, random(18, 55));
    strokeWeight(random(0.8, 2));
    let px = 0;
    beginShape();
    noFill();
    for (let x = 0; x <= W; x += 20) {
      let yy = y + sin(x * 0.01 + i) * 1.6 + noise(x * 0.004, i * 10) * 3;
      vertex(x, yy);
    }
    endShape();
  }
  noStroke();
}

/* ---------- WET SAND GROUND ---------- */
function drawWetSand() {
  let top = H * 0.395;
  for (let y = top; y < H; y++) {
    let t = (y - top) / (H - top);
    // wet darker near water, drier/warmer toward viewer
    let r = lerp(176, 214, pow(t, 0.7));
    let g = lerp(170, 205, pow(t, 0.7));
    let b = lerp(160, 190, pow(t, 0.7));
    stroke(r, g, b);
    line(0, y, W, y);
  }
  noStroke();

  // broad tonal patches — damp areas
  for (let i = 0; i < 160; i++) {
    let y = random(top, H);
    let t = (y - top) / (H - top);
    let x = random(-200, W + 200);
    let w = random(300, 1400) * (0.5 + t);
    let h = random(40, 220) * (0.4 + t);
    let dark = random() < 0.55;
    if (dark) fill(150, 146, 138, random(5, 16));
    else fill(236, 230, 215, random(5, 14));
    ellipse(x, y, w, h);
  }
}

/* ---------- RIPPLE PATTERN ---------- */
function drawRipples() {
  let top = H * 0.40;
  noFill();
  for (let i = 0; i < 230; i++) {
    let t0 = i / 230;
    let y = top + pow(t0, 1.35) * (H - top) + random(-4, 4);
    let t = (y - top) / (H - top);
    let amp = lerp(4, 34, t);
    let freq = lerp(0.010, 0.0030, t);
    let sw = lerp(0.8, 3.4, t);
    let phase = noise(i * 0.21) * 100;

    // shadow line
    stroke(140, 134, 124, lerp(26, 52, t));
    strokeWeight(sw);
    rippleLine(y, amp, freq, phase, 0);

    // highlight just above
    stroke(248, 244, 232, lerp(28, 60, t));
    strokeWeight(sw * 0.8);
    rippleLine(y - sw * 1.5 - 1, amp, freq, phase, 0.0);
  }
  noStroke();
}

function rippleLine(y, amp, freq, phase, off) {
  beginShape();
  for (let x = -20; x <= W + 20; x += 12) {
    let n = noise(x * freq, phase);
    let yy = y + (n - 0.5) * 2 * amp + sin(x * freq * 2.1 + phase) * amp * 0.25;
    // avoid drawing straight through hollow interior (handled by overdraw later)
    vertex(x, yy);
  }
  endShape();
}

/* ---------- THE HOLLOW (absent body) ---------- */
function hollowPoints() {
  // a body-shaped depression, head top, slightly turned
  let cx = W * 0.50;
  let cy = H * 0.665;
  let pts = [];
  let N = 220;
  for (let i = 0; i < N; i++) {
    let a = TWO_PI * i / N;
    // base ellipse elongated vertically
    let rx = 215, ry = 540;
    let x = cos(a) * rx;
    let y = sin(a) * ry;
    // narrow at the "neck" region
    let ny = y / ry; // -1 top .. 1 bottom
    let narrow = 1.0;
    narrow *= 1 - 0.42 * exp(-pow((ny + 0.56) / 0.11, 2));   // neck
    narrow *= 1 + 0.30 * exp(-pow((ny + 0.18) / 0.26, 2));   // shoulders/torso
    narrow *= 1 - 0.30 * exp(-pow((ny - 0.30) / 0.22, 2));   // waist->hips taper
    narrow *= 1 + 0.16 * exp(-pow((ny - 0.08) / 0.18, 2));
    narrow *= 1 - 0.55 * exp(-pow((ny - 0.92) / 0.14, 2));   // feet
    // head bulge
    let headBulge = 0.55 + 0.75 * exp(-pow((ny + 0.86) / 0.13, 2));
    if (ny < -0.68) narrow = headBulge;
    x *= narrow;
    // slight sway
    x += sin(ny * 2.1) * 26;
    // organic noise
    let nn = noise(i * 0.06, 7.7) - 0.5;
    x += nn * 26;
    y += (noise(i * 0.05, 19.3) - 0.5) * 18;
    pts.push([cx + x, cy + y]);
  }
  return pts;
}

function drawHollow() {
  let pts = hollowPoints();

  // 1) soft outer damp halo
  noStroke();
  for (let k = 8; k >= 1; k--) {
    fill(160, 154, 143, 7);
    beginShape();
    for (let p of pts) {
      let dx = p[0] - W * 0.5, dy = p[1] - H * 0.665;
      vertex(W * 0.5 + dx * (1 + k * 0.035), H * 0.665 + dy * (1 + k * 0.030));
    }
    endShape(CLOSE);
  }

  // 2) interior: smoothed sand, ripples erased/softened
  fill(198, 191, 178, 230);
  beginShape();
  for (let p of pts) vertex(p[0], p[1]);
  endShape(CLOSE);

  // interior shading: depth gradient (darker along left/upper inner edge)
  push();
  // clip-like: draw many inset shapes
  for (let k = 0; k < 26; k++) {
    let f = k / 26;
    let a = 7 * (1 - f);
    fill(152, 146, 136, a);
    beginShape();
    for (let p of pts) {
      let dx = p[0] - (W * 0.5 - 20), dy = p[1] - (H * 0.665 - 30);
      let s = 1 - f * 0.9;
      vertex(W * 0.5 - 20 + dx * s, H * 0.665 - 30 + dy * s);
    }
    endShape(CLOSE);
  }
  pop();

  // 3) inner faint residual ripples (much softer, following the hollow)
  push();
  noFill();
  for (let i = 0; i < 46; i++) {
    let t = i / 46;
    let y = lerp(H * 0.665 - 520, H * 0.665 + 520, t);
    stroke(166, 160, 149, 20);
    strokeWeight(1.2);
    beginShape();
    for (let x = W * 0.5 - 300; x <= W * 0.5 + 300; x += 10) {
      if (!insidePoly(x, y, pts)) continue;
      let yy = y + (noise(x * 0.006, i * 3.1) - 0.5) * 10;
      vertex(x, yy);
    }
    endShape();
  }
  pop();

  // 4) rim: bright lip on light side, shadow on other
  push();
  strokeWeight(3.2);
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let q = pts[(i + 1) % pts.length];
    let mx = (p[0] + q[0]) / 2, my = (p[1] + q[1]) / 2;
    let ang = atan2(q[1] - p[1], q[0] - p[0]);
    let nx = cos(ang - HALF_PI), ny = sin(ang - HALF_PI);
    // light from upper-left
    let lit = nx * -0.6 + ny * -0.8;
    if (lit > 0) {
      stroke(246, 241, 228, 90 * lit);
      line(p[0] + nx * 3, p[1] + ny * 3, q[0] + nx * 3, q[1] + ny * 3);
    } else {
      stroke(132, 126, 116, 80 * -lit);
      line(p[0] - nx * 2, p[1] - ny * 2, q[0] - nx * 2, q[1] - ny * 2);
    }
  }
  // inner contact shadow
  strokeWeight(5);
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let dx = p[0] - W * 0.5, dy = p[1] - H * 0.665;
    let ix = W * 0.5 + dx * 0.965, iy = H * 0.665 + dy * 0.965;
    stroke(138, 132, 122, 34);
    point(ix, iy);
  }
  pop();

  // 5) tiny grains collected in the hollow
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let x = random(W * 0.5 - 320, W * 0.5 + 320);
    let y = random(H * 0.665 - 560, H * 0.665 + 560);
    if (!insidePoly(x, y, pts)) continue;
    fill(random() < 0.5 ? 240 : 150, random(140, 240), random(130, 220), random(8, 26));
    rect(x, y, 1.4, 1.4);
  }
}

function insidePoly(x, y, pts) {
  let c = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    let xi = pts[i][0], yi = pts[i][1], xj = pts[j][0], yj = pts[j][1];
    if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) c = !c;
  }
  return c;
}

/* ---------- FOAM / TIDE LINE ---------- */
function drawFoamLine() {
  let baseY = H * 0.415;
  noFill();
  for (let layer = 0; layer < 5; layer++) {
    let y0 = baseY + layer * 9;
    stroke(255, 255, 252, 90 - layer * 14);
    strokeWeight(2.2 - layer * 0.3);
    beginShape();
    for (let x = -10; x <= W + 10; x += 9) {
      let yy = y0 + (noise(x * 0.0035, layer * 5.5) - 0.5) * 26 + sin(x * 0.004 + layer) * 5;
      vertex(x, yy);
    }
    endShape();
  }
  // foam speckles
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(W);
    let y = baseY + (noise(x * 0.0035, 0) - 0.5) * 26 + randomGaussian(0, 16);
    fill(255, 255, 253, random(20, 120));
    ellipse(x, y, random(1, 4), random(1, 3));
  }
  // thin dark wrack line (debris) — abstract dashes
  for (let i = 0; i < 260; i++) {
    let x = random(W);
    let y = baseY + 30 + (noise(x * 0.003, 9) - 0.5) * 30 + randomGaussian(0, 9);
    fill(120, 112, 100, random(20, 70));
    push();
    translate(x, y);
    rotate(random(-0.4, 0.4));
    rect(0, 0, random(3, 16), random(1, 2.2));
    pop();
  }
}

/* ---------- LIGHT ---------- */
function drawLightShaft() {
  noStroke();
  // soft glow from upper-left
  for (let i = 0; i < 70; i++) {
    let r = 1700 - i * 20;
    fill(255, 252, 240, 2.2);
    ellipse(W * 0.26, H * 0.10, r * 1.5, r);
  }
  // gentle reflected sheen on sand near hollow
  for (let i = 0; i < 40; i++) {
    fill(255, 250, 236, 3);
    ellipse(W * 0.44, H * 0.60, 1500 - i * 25, 1100 - i * 20);
  }
}

/* ---------- GRAIN + VIGNETTE ---------- */
function grainAndVignette() {
  noStroke();
  for (let i = 0; i < 90000; i++) {
    let x = random(W), y = random(H);
    let v = random(255);
    fill(v, random(6, 16));
    rect(x, y, 1, 1);
  }
  // paper fiber streaks
  for (let i = 0; i < 1200; i++) {
    let x = random(W), y = random(H);
    fill(255, random(4, 12));
    rect(x, y, random(2, 30), 1);
  }
  // vignette
  for (let i = 0; i < 160; i++) {
    let a = i / 160;
    noFill();
    stroke(70, 66, 60, 1.6 * a * a * 10);
    strokeWeight(14);
    ellipse(W / 2, H / 2, W * 1.45 - i * 11, H * 1.35 - i * 11);
  }
  noStroke();
  // subtle edge darkening rectangles
  for (let i = 0; i < 60; i++) {
    fill(60, 56, 50, 1.2);
    rect(0, 0, W, i * 1.6);
    rect(0, H - i * 1.6, W, i * 1.6);
    rect(0, 0, i * 1.6, H);
    rect(W - i * 1.6, 0, i * 1.6, H);
  }
}

// 退潮 / Ebb
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(18, 20, 26);

  // ---------- 背景渐变：上方温热，下方沉静 ----------
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(58, 20, pow(t, 0.8));
    let g = lerp(44, 28, pow(t, 0.8));
    let b = lerp(42, 44, pow(t, 0.8));
    // 顶部微暗晕
    let vign = 1 - 0.35 * pow(abs(t - 0.45) * 2, 2.2);
    fill(r * vign, g * vign, b * vign);
    rect(0, y, width, 1);
  }

  // ---------- 柔和的大气噪点底层 ----------
  push();
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    let a = 10 + n * 25;
    fill(255, 250, 240, a * 0.25);
    ellipse(x, y, random(1, 3));
  }
  pop();

  // ---------- 主体：笔触场 ----------
  // 密度随高度衰减
  let total = 42000;
  for (let i = 0; i < total; i++) {
    // 采样 y，偏向上方
    let u = random();
    let y = pow(u, 1.9) * height * 1.05 - 20;
    if (y < -30 || y > height + 30) continue;

    let t = constrain(y / height, 0, 1);

    // 存活概率：随深度骤降
    let survive = 1 - smooth01(t, 0.12, 0.92);
    if (random() > survive * 0.98 + 0.02) continue;

    let x = random(-40, width + 40);

    // 噪声场方向
    let nx = x * 0.0018;
    let ny = y * 0.0018;
    let ang = (noise(nx, ny, 0.3) - 0.5) * PI * 1.6;
    // 越往下越水平、越拉长
    ang = lerp(ang, ang * 0.18, pow(t, 1.3));

    let len = lerp(random(6, 26), random(30, 120), pow(t, 1.6));
    let w = lerp(random(2.2, 5.5), random(0.5, 1.6), pow(t, 1.1));

    // 颜色：上方温热赭红橙，下方灰蓝
    let warm = color(
      random(215, 252),
      random(150, 200),
      random(110, 155)
    );
    let cool = color(
      random(120, 165),
      random(140, 175),
      random(160, 195)
    );
    let c = lerpColor(warm, cool, constrain(pow(t, 0.75) * 1.15, 0, 1));

    let alpha = lerp(random(90, 190), random(8, 45), pow(t, 1.2));

    // 少量偏暗的"阴影"笔触增加层次
    if (random() < 0.22) {
      c = lerpColor(c, color(25, 22, 28), 0.55);
      alpha *= 1.1;
    }

    strokeWeight(w);
    stroke(red(c), green(c), blue(c), alpha);
    strokeCap(ROUND);

    // 稍带弯曲的笔触
    let steps = 4;
    let px = x, py = y;
    let a2 = ang;
    noFill();
    beginShape();
    curveVertex(px, py);
    curveVertex(px, py);
    for (let s = 1; s <= steps; s++) {
      a2 += (noise(px * 0.004, py * 0.004, s * 0.5) - 0.5) * 0.7 * (1 - t);
      px += cos(a2) * (len / steps);
      py += sin(a2) * (len / steps);
      curveVertex(px, py);
    }
    curveVertex(px, py);
    endShape();
  }

  // ---------- 上方的高密度核心：更紧实的生命 ----------
  for (let i = 0; i < 9000; i++) {
    let y = pow(random(), 2.6) * height * 0.42;
    let x = random(-20, width + 20);
    let t = y / height;
    let ang = (noise(x * 0.0022, y * 0.0022, 2.1) - 0.5) * PI * 1.8;
    let len = random(4, 16);
    let w = random(1.6, 4.2);
    let c = lerpColor(
      color(255, 196, 150),
      color(190, 80, 70),
      random()
    );
    stroke(red(c), green(c), blue(c), random(60, 170) * (1 - t * 1.4));
    strokeWeight(w);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // ---------- 中部裂隙：呼吸停止的一瞬 ----------
  let gapY = height * 0.505;
  push();
  noStroke();
  for (let k = 0; k < 160; k++) {
    let hh = 1;
    let yy = gapY - 26 + k * 0.34;
    let d = abs(yy - gapY) / 28;
    let a = (1 - d) * 190;
    fill(14, 16, 22, a);
    rect(0, yy, width, 1.4);
  }
  // 裂隙中的一道极淡亮线
  for (let x = 0; x < width; x += 1) {
    let n = noise(x * 0.004, 77.7);
    let yy = gapY + (n - 0.5) * 10;
    let a = 40 + noise(x * 0.01, 3.3) * 70;
    stroke(225, 222, 215, a * 0.5);
    strokeWeight(1);
    point(x, yy);
  }
  pop();

  // ---------- 下方沉静的水平层 ----------
  for (let i = 0; i < 2600; i++) {
    let y = gapY + pow(random(), 0.75) * (height - gapY);
    let t = (y - gapY) / (height - gapY);
    let x = random(-60, width + 60);
    let len = random(60, 420) * (0.4 + t);
    let a = random(5, 34) * (1 - t * 0.55);
    let c = lerpColor(color(150, 168, 186), color(70, 84, 100), random());
    stroke(red(c), green(c), blue(c), a);
    strokeWeight(random(0.4, 1.8));
    let dy = (noise(x * 0.001, y * 0.004) - 0.5) * 8;
    line(x, y, x + len, y + dy);
  }

  // ---------- 极少数残存者：孤立的温暖点 ----------
  for (let i = 0; i < 110; i++) {
    let y = gapY + pow(random(), 0.6) * (height - gapY) * 0.95;
    let x = random(width);
    let t = (y - gapY) / (height - gapY);
    let a = random(30, 150) * (1 - t * 0.85);
    noStroke();
    fill(240, 170, 130, a);
    ellipse(x, y, random(1.5, 4.5));
  }

  // ---------- 整体颗粒与压暗 ----------
  push();
  noStroke();
  for (let i = 0; i < 26000; i++) {
    let x = random(width), y = random(height);
    let b = random(-16, 16);
    fill(128 + b, 126 + b, 124 + b, 16);
    rect(x, y, 1.6, 1.6);
  }
  pop();

  // 暗角
  push();
  noFill();
  for (let i = 0; i < 300; i++) {
    let a = i * 0.55;
    stroke(10, 11, 15, a * 0.12);
    strokeWeight(3);
    rect(-i * 1.6, -i * 1.6, width + i * 3.2, height + i * 3.2);
  }
  pop();
}

function smooth01(x, a, b) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// "Ebb Tide" — a static meditation on dissolution
let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(16, 19, 26);

  // ---------- deep ground: an old grey-blue tide ----------
  loadPixels();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    for (let x = 0; x < W; x++) {
      let n = noise(x * 0.0016, y * 0.0016 * 0.6, 3.7);
      let n2 = noise(x * 0.006, y * 0.004, 11.2);
      // vertical gradient: warm-dim above, cold-pale below
      let base = lerp(20, 86, pow(t, 1.25));
      let r = base + n * 26 + n2 * 8 - 10 * (1 - t);
      let g = base + n * 24 + n2 * 7 + 4 * t;
      let b = base + n * 30 + n2 * 9 + 24 * t;
      let i = 4 * (y * W + x);
      pixels[i] = r;
      pixels[i + 1] = g;
      pixels[i + 2] = b;
      pixels[i + 3] = 255;
    }
  }
  updatePixels();

  // ---------- horizontal strata: slow water layers ----------
  noStroke();
  for (let k = 0; k < 160; k++) {
    let y = random(H * 0.25, H);
    let h = random(1, 9);
    let a = random(4, 16);
    let c = random() < 0.5 ? color(150, 168, 186, a) : color(10, 14, 22, a);
    fill(c);
    rect(0, y, W, h);
  }

  // ---------- the body: a vertical column of density ----------
  // density(y): 1 at top, 0 at bottom — the slow ebb
  let cx = W * 0.5;

  // silhouette profile of a seated/standing figure, abstracted
  function bodyWidth(yy) {
    // yy normalized 0..1 over the figure's span
    let w;
    if (yy < 0.10) {
      // head
      let u = yy / 0.10;
      w = 90 * sin(u * PI) * 0.95 + 20;
    } else if (yy < 0.16) {
      // neck
      let u = (yy - 0.10) / 0.06;
      w = lerp(52, 110, u);
    } else if (yy < 0.42) {
      // shoulders -> torso
      let u = (yy - 0.16) / 0.26;
      w = lerp(230, 185, pow(u, 0.6));
    } else if (yy < 0.70) {
      let u = (yy - 0.42) / 0.28;
      w = lerp(185, 215, u);
    } else {
      let u = (yy - 0.70) / 0.30;
      w = lerp(215, 300, pow(u, 1.5));
    }
    return w;
  }

  let topY = H * 0.14;
  let botY = H * 0.93;
  let span = botY - topY;

  // --- core solid mass (upper body, painted with soft strokes) ---
  for (let pass = 0; pass < 3; pass++) {
    for (let i = 0; i < 26000; i++) {
      let yy = pow(random(), 1.0);          // 0..1 along figure
      let y = topY + yy * span;
      let dens = constrain(1.0 - pow(yy, 0.75) * 1.18, 0, 1);
      if (dens <= 0.001) continue;
      if (random() > dens * 0.95 + 0.05) continue;

      let bw = bodyWidth(yy);
      // lateral position with edge softening that grows downward
      let soft = lerp(0.04, 0.9, pow(yy, 1.1));
      let r = random(-1, 1);
      let xo = r * bw * (0.5 + soft * 0.9 * abs(r));
      // noise displacement increases as it dissolves
      let dx = (noise(y * 0.004, i * 0.0007, 5.1) - 0.5) * 260 * pow(yy, 1.6);
      let x = cx + xo + dx;

      // color: warm pallor above, cooling into the tide
      let warmth = 1 - yy;
      let rr = lerp(132, 196, warmth) + random(-14, 14);
      let gg = lerp(140, 182, warmth) + random(-14, 14);
      let bb = lerp(156, 168, warmth) + random(-14, 14);
      let a = dens * random(18, 58);

      // shading: body darker toward the left, light from upper right
      let shade = map(xo, -bw * 0.6, bw * 0.6, -46, 30);
      fill(rr + shade, gg + shade, bb + shade * 0.8, a);
      noStroke();
      let s = random(1.2, 4.4) * (1 + yy * 1.6);
      ellipse(x, y, s, s * random(0.6, 1.4));
    }
  }

  // --- interior darkness: the hollow under the ribs ---
  for (let i = 0; i < 9000; i++) {
    let yy = random(0.18, 0.62);
    let y = topY + yy * span;
    let bw = bodyWidth(yy);
    let x = cx + random(-bw * 0.42, bw * 0.42) + random(-10, 10);
    let dens = constrain(1.0 - pow(yy, 0.75) * 1.18, 0, 1);
    let d = dist(x, y, cx - 10, topY + 0.38 * span);
    let a = map(d, 0, 300, 40, 0) * dens;
    if (a <= 0) continue;
    fill(18, 22, 30, a * random(0.4, 1));
    ellipse(x, y, random(2, 7), random(2, 7));
  }

  // --- the dissolution field: particles leaving the body ---
  for (let i = 0; i < 52000; i++) {
    let yy = pow(random(), 0.55);          // biased to lower half
    let y = topY + yy * span + random(-20, 160);
    if (y > H) continue;
    let bw = bodyWidth(constrain(yy, 0, 1));
    let spreadAmt = pow(yy, 1.8) * 820;
    let x = cx + random(-bw * 0.55, bw * 0.55) + randomGaussianish() * spreadAmt;
    if (x < -40 || x > W + 40) continue;

    // probability of surviving as a visible grain fades downward
    let survive = 1 - pow(yy, 0.6);
    if (random() > survive * 0.85 + 0.03) continue;

    let a = random(6, 46) * (0.25 + survive * 0.9);
    let warmth = 1 - yy;
    fill(
      lerp(150, 198, warmth) + random(-18, 18),
      lerp(158, 186, warmth) + random(-18, 18),
      lerp(176, 172, warmth) + random(-18, 18),
      a
    );
    noStroke();
    let s = random(0.8, 2.8);
    ellipse(x, y, s, s);
  }

  // --- faint drifting veils, carried sideways by the tide ---
  for (let k = 0; k < 1400; k++) {
    let y = random(H * 0.42, H * 1.0);
    let t = (y - H * 0.42) / (H * 0.58);
    let len = random(40, 420) * (0.4 + t);
    let x = cx + randomGaussianish() * (260 + t * 700);
    let a = random(3, 13) * (1 - t * 0.5);
    stroke(176, 190, 206, a);
    strokeWeight(random(0.6, 1.9));
    let yj = random(-2, 2);
    line(x, y, x + len, y + yj);
  }
  noStroke();

  // ---------- the light not yet taken: above the head ----------
  for (let i = 0; i < 20000; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 1.7) * 300;
    let x = cx + 18 + cos(ang) * rad * 1.15;
    let y = topY - 20 + sin(ang) * rad * 0.85;
    if (y < 0 || y > H) continue;
    let a = map(rad, 0, 300, 30, 0);
    fill(236, 230, 214, a * random(0.3, 1));
    ellipse(x, y, random(1, 3.2), random(1, 3.2));
  }
  // small dense core of light, slightly off-center from the head
  for (let i = 0; i < 4000; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 2.3) * 70;
    let x = cx + 16 + cos(ang) * rad;
    let y = topY - 46 + sin(ang) * rad * 0.8;
    fill(248, 244, 232, map(rad, 0, 70, 44, 0));
    ellipse(x, y, random(1.2, 3.4), random(1.2, 3.4));
  }

  // ---------- overall grain ----------
  for (let i = 0; i < 90000; i++) {
    let x = random(W), y = random(H);
    let v = random() < 0.5 ? 255 : 0;
    fill(v, random(3, 11));
    rect(x, y, 1, 1);
  }

  // ---------- vignette ----------
  for (let i = 0; i < 260; i++) {
    let a = map(i, 0, 260, 0, 24);
    noFill();
    stroke(8, 10, 15, a * 0.12);
    strokeWeight(3);
    rect(-i, -i, W + i * 2, H + i * 2);
  }
  noStroke();

  // ---------- subtle warm bloom at the very top edge ----------
  for (let y = 0; y < 320; y++) {
    fill(60, 54, 46, map(y, 0, 320, 16, 0));
    rect(0, y, W, 1);
  }
}

function randomGaussianish() {
  // sum of uniforms -> soft bell, kept deterministic via random()
  let s = 0;
  for (let i = 0; i < 4; i++) s += random(-1, 1);
  return s / 2.2;
}

// 退潮 / Ebb
let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
}

function draw() {
  background(20);
  drawSky();
  drawSea();
  drawWetSand();
  drawBodyHollow();
  drawFoamLines();
  drawGrain();
  drawVignette();
}

/* ---------- 天空：无边的灰蓝 ---------- */
function drawSky() {
  const horizon = H * 0.42;
  noStroke();
  for (let y = 0; y < horizon; y++) {
    const t = y / horizon;
    // 顶部深灰蓝 -> 地平线处苍白
    const r = lerp(58, 168, pow(t, 1.5));
    const g = lerp(68, 178, pow(t, 1.45));
    const b = lerp(80, 182, pow(t, 1.3));
    stroke(r, g, b);
    line(0, y, W, y);
  }

  // 云：水平拉长的噪声带
  noStroke();
  for (let i = 0; i < 2600; i++) {
    const x = random(-100, W + 100);
    const y = random(horizon * 0.05, horizon * 0.98);
    const n = noise(x * 0.0012, y * 0.009, 3.3);
    const n2 = noise(x * 0.004, y * 0.02, 11.1);
    if (n > 0.52) {
      const a = map(n, 0.52, 0.85, 0, 26, true) * (0.4 + 0.6 * n2);
      const w = random(60, 420);
      const h = random(2, 14);
      const t = y / horizon;
      const c = lerp(120, 205, t);
      fill(c + 10, c + 12, c + 16, a);
      ellipse(x, y, w, h);
    }
  }

  // 地平线上方的一层薄雾
  for (let y = horizon - 160; y < horizon; y++) {
    const t = (y - (horizon - 160)) / 160;
    stroke(190, 196, 198, 34 * t);
    line(0, y, W, y);
  }
}

/* ---------- 海：天与海已无法分辨 ---------- */
function drawSea() {
  const horizon = H * 0.42;
  const shore = H * 0.60;
  noStroke();
  for (let y = horizon; y < shore; y++) {
    const t = (y - horizon) / (shore - horizon);
    const r = lerp(166, 118, pow(t, 0.8));
    const g = lerp(176, 130, pow(t, 0.8));
    const b = lerp(180, 136, pow(t, 0.8));
    stroke(r, g, b);
    line(0, y, W, y);
  }

  // 水面横纹
  for (let i = 0; i < 900; i++) {
    const y = random(horizon + 2, shore);
    const t = (y - horizon) / (shore - horizon);
    const x = random(-50, W);
    const len = random(20, 260) * (0.3 + t);
    const n = noise(x * 0.003, y * 0.05, 7.7);
    const a = map(n, 0.3, 0.8, 0, 46, true) * (0.25 + t);
    const c = n > 0.55 ? 210 : 95;
    stroke(c, c + 4, c + 8, a);
    strokeWeight(random(0.6, 2.2) * (0.5 + t));
    line(x, y, x + len, y + random(-0.6, 0.6));
  }
  strokeWeight(1);

  // 远处一条极细的亮线：地平线
  stroke(225, 230, 232, 70);
  strokeWeight(1.2);
  line(0, horizon + 0.5, W, horizon + 0.5);
  noStroke();
}

/* ---------- 湿沙滩 ---------- */
function drawWetSand() {
  const shore = H * 0.60;
  noStroke();
  for (let y = shore; y < H; y++) {
    const t = (y - shore) / (H - shore);
    // 近水处仍映着天色，往前渐成暗沙
    const r = lerp(132, 74, pow(t, 0.75));
    const g = lerp(136, 70, pow(t, 0.75));
    const b = lerp(138, 66, pow(t, 0.8));
    stroke(r, g, b);
    line(0, y, W, y);
  }

  // 水边的反光带
  for (let y = shore - 30; y < shore + 90; y++) {
    const d = abs(y - (shore + 22)) / 70;
    const a = 50 * (1 - constrain(d, 0, 1));
    stroke(205, 210, 212, a);
    line(0, y, W, y);
  }

  // 沙的纹理：被水抚平的弧线
  for (let i = 0; i < 260; i++) {
    const baseY = random(shore + 10, H);
    const t = (baseY - shore) / (H - shore);
    const a = random(8, 30) * (0.4 + t * 0.9);
    const bright = random() < 0.5;
    stroke(bright ? 190 : 48, bright ? 192 : 44, bright ? 194 : 42, a);
    strokeWeight(random(0.6, 2.4));
    noFill();
    beginShape();
    const x0 = random(-200, W);
    const len = random(200, 1100);
    for (let x = x0; x < x0 + len; x += 14) {
      const yy = baseY + sin((x - x0) * 0.004 + baseY * 0.01) * (8 + 26 * t)
        + (noise(x * 0.002, baseY * 0.01, 2.2) - 0.5) * 30;
      vertex(x, yy);
    }
    endShape();
  }
  strokeWeight(1);

  // 散落的暗点（贝壳碎屑 / 湿斑）
  for (let i = 0; i < 2200; i++) {
    const y = random(shore + 5, H);
    const t = (y - shore) / (H - shore);
    if (random() > 0.25 + t * 0.7) continue;
    const x = random(W);
    const dark = random() < 0.7;
    fill(dark ? 40 : 200, dark ? 37 : 200, dark ? 35 : 198, random(10, 70));
    noStroke();
    ellipse(x, y, random(1, 5) * (0.5 + t), random(1, 3.5) * (0.5 + t));
  }
}

/* ---------- 身体的凹痕 ---------- */
function drawBodyHollow() {
  const cx = W * 0.50;
  const cy = H * 0.805;
  const s = 1.0;

  push();
  translate(cx, cy);
  rotate(-0.06);

  // 轮廓点：一个侧卧蜷缩的人形（极简，几乎只是隆起的沙）
  const pts = bodyOutline(s);

  // 1) 凹陷的阴影（上缘深，下缘亮）—— 多层偏移模糊
  noStroke();
  for (let k = 22; k >= 1; k--) {
    const e = k * 3.0;
    const a = map(k, 1, 22, 26, 2);
    fill(30, 28, 27, a);
    drawOffsetShape(pts, e, -e * 0.45);
  }

  // 2) 内部更暗的核心
  for (let k = 8; k >= 1; k--) {
    fill(26, 24, 24, 10);
    drawOffsetShape(pts, k * 1.6, -k * 0.6);
  }

  // 3) 下缘的沙脊亮边
  for (let k = 1; k <= 14; k++) {
    const e = k * 2.4;
    const a = map(k, 1, 14, 30, 2);
    fill(206, 203, 196, a);
    drawOffsetShape(pts, e, e * 0.9);
  }

  // 4) 凹痕内部的浅水反光
  push();
  drawingContext.save();
  beginShape();
  for (const p of pts) vertex(p[0], p[1]);
  endShape(CLOSE);
  drawingContext.clip();
  noStroke();
  for (let i = 0; i < 1400; i++) {
    const x = random(-420, 420);
    const y = random(-260, 260);
    const n = noise(x * 0.004 + 10, y * 0.004 + 10, 5.5);
    if (n > 0.55) {
      fill(170, 176, 180, map(n, 0.55, 0.85, 0, 34, true));
      ellipse(x, y, random(4, 40), random(2, 8));
    } else {
      fill(34, 32, 31, random(4, 16));
      ellipse(x, y, random(3, 26), random(2, 7));
    }
  }
  drawingContext.restore();
  pop();

  // 5) 边缘被潮水咬掉：用背景色的斑块侵蚀轮廓
  noStroke();
  for (let i = 0; i < 520; i++) {
    const idx = floor(random(pts.length));
    const p = pts[idx];
    const t = (p[1] + cy - H * 0.60) / (H - H * 0.60);
    const sandR = lerp(132, 74, pow(constrain(t, 0, 1), 0.75));
    const sandG = lerp(136, 70, pow(constrain(t, 0, 1), 0.75));
    const sandB = lerp(138, 66, pow(constrain(t, 0, 1), 0.8));
    fill(sandR, sandG, sandB, random(14, 60));
    const jx = p[0] + random(-26, 26);
    const jy = p[1] + random(-18, 18);
    ellipse(jx, jy, random(8, 50), random(6, 28));
  }

  // 6) 极细的轮廓暗示线，断续
  stroke(48, 45, 44, 42);
  noFill();
  strokeWeight(1.4);
  for (let i = 0; i < pts.length - 1; i++) {
    if (noise(i * 0.08, 42.0) > 0.52) {
      line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    }
  }
  strokeWeight(1);
  pop();
}

function drawOffsetShape(pts, ex, ey) {
  beginShape();
  for (const p of pts) {
    const nx = noise(p[0] * 0.004 + 50, p[1] * 0.004 + 50, 1.3) - 0.5;
    vertex(p[0] + ex * (1 + nx * 1.2), p[1] + ey * (1 + nx * 1.2));
  }
  endShape(CLOSE);
}

// 构造一个侧卧蜷缩人形的闭合轮廓点列
function bodyOutline(s) {
  const pts = [];
  const add = (x, y) => pts.push([x * s, y * s]);

  // 使用若干关键点，再做样条平滑
  const key = [
    [-430, 40],   // 脚尖
    [-370, 10],
    [-300, -10],
    [-240, -36],  // 小腿
    [-180, -70],
    [-130, -108], // 膝
    [-70, -120],
    [-10, -100],
    [40, -92],    // 髋
    [95, -112],
    [150, -140],  // 腰 -> 背
    [215, -150],
    [275, -140],
    [325, -118],  // 肩
    [372, -128],
    [410, -152],  // 头顶
    [440, -132],
    [448, -98],   // 面
    [432, -70],
    [398, -58],
    [360, -62],   // 下巴/颈
    [320, -48],
    [280, -22],   // 胸前
    [230, -4],
    [180, 6],     // 臂
    [120, 2],
    [70, 14],     // 手
    [20, 30],
    [-40, 40],    // 腹下
    [-110, 48],
    [-180, 52],
    [-250, 56],
    [-330, 54],
    [-400, 50]
  ];

  // Catmull-Rom 平滑
  const n = key.length;
  for (let i = 0; i < n; i++) {
    const p0 = key[(i - 1 + n) % n];
    const p1 = key[i];
    const p2 = key[(i + 1) % n];
    const p3 = key[(i + 2) % n];
    for (let t = 0; t < 1; t += 0.08) {
      const t2 = t * t, t3 = t2 * t;
      const x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      const y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      // 轮廓本身被噪声微微侵蚀
      const w = (noise(x * 0.006 + 7, y * 0.006 + 7, 9.9) - 0.5) * 26;
      add(x + w, y + w * 0.5);
    }
  }
  return pts;
}

/* ---------- 泡沫线：潮水退去留下的边 ---------- */
function drawFoamLines() {
  const shore = H * 0.60;
  const lines = [
    { y: shore + 18, a: 95, w: 2.6 },
    { y: shore + 92, a: 62, w: 2.2 },
    { y: shore + 210, a: 40, w: 1.8 },
    { y: shore + 380, a: 26, w: 1.6 },
    { y: shore + 600, a: 16, w: 1.4 }
  ];
  noFill();
  for (let li = 0; li < lines.length; li++) {
    const L = lines[li];
    for (let pass = 0; pass < 3; pass++) {
      stroke(228, 230, 230, L.a * (pass === 0 ? 1 : 0.35));
      strokeWeight(L.w * (pass === 0 ? 1 : 2.4));
      beginShape();
      for (let x = -20; x < W + 20; x += 8) {
        const amp = 16 + li * 10;
        const yy = L.y
          + (noise(x * 0.0016, li * 3.3 + 0.5) - 0.5) * amp * 3
          + sin(x * 0.006 + li) * amp * 0.5
          + pass * 2;
        if (noise(x * 0.01, li * 7.7) > 0.3) vertex(x, yy);
        else { endShape(); beginShape(); }
      }
      endShape();
    }
    // 泡沫颗粒
    noStroke();
    for (let i = 0; i < 700; i++) {
      const x = random(W);
      const amp = 16 + li * 10;
      const yy = L.y + (noise(x * 0.0016, li * 3.3 + 0.5) - 0.5) * amp * 3
        + sin(x * 0.006 + li) * amp * 0.5 + random(-10, 10);
      fill(235, 236, 236, random(5, L.a * 0.8));
      ellipse(x, yy, random(1, 6), random(1, 4));
    }
  }
  strokeWeight(1);
}

/* ---------- 颗粒 ---------- */
function drawGrain() {
  noStroke();
  for (let i = 0; i < 90000; i++) {
    const x = random(W), y = random(H);
    const v = random(-16, 16);
    fill(128 + v, 128 + v, 128 + v, 12);
    rect(x, y, 1.4, 1.4);
  }
}

/* ---------- 暗角 ---------- */
function drawVignette() {
  noFill();
  for (let i = 0; i < 300; i++) {
    const a = map(i, 0, 300, 0, 46);
    stroke(14, 14, 18, a * 0.09);
    rect(i * 0.9, i * 1.1, W - i * 1.8, H - i * 2.2);
  }
  noStroke();
}
